window.SEARCH=[{"k": "a", "a": "1.1 Виды матриц и обозначения (лекция 1)", "b": "Матрица — это таблица чисел, но с собственными правилами игры: матрицы складывают, перемножают, находят их определитель и обращают. Сначала надо выучить «язык» матриц: что такое размер, элемент, диагональ и какие бывают особые виды. Он нужен в каждой следующей статье, а потом пригодится в системах уравнений (лекция 2) и линейных отображениях (лекция 5). Что такое матрица Матрица Матрица — это прям", "u": "lectures/01/vidy-matric.html"},{"k": "a", "a": "Что такое матрица — Виды матриц и обозначения (1.1)", "b": "", "u": "lectures/01/vidy-matric.html#chto"},{"k": "a", "a": "Равенство — Виды матриц и обозначения (1.1)", "b": "", "u": "lectures/01/vidy-matric.html#ravenstvo"},{"k": "a", "a": "Квадратные и диагонали — Виды матриц и обозначения (1.1)", "b": "", "u": "lectures/01/vidy-matric.html#kvadrat"},{"k": "a", "a": "Особые виды — Виды матриц и обозначения (1.1)", "b": "", "u": "lectures/01/vidy-matric.html#vidy"},{"k": "a", "a": "Частые ошибки — Виды матриц и обозначения (1.1)", "b": "", "u": "lectures/01/vidy-matric.html#oshibki"},{"k": "a", "a": "Кратко — Виды матриц и обозначения (1.1)", "b": "", "u": "lectures/01/vidy-matric.html#kratko"},{"k": "a", "a": "Проверь себя — Виды матриц и обозначения (1.1)", "b": "", "u": "lectures/01/vidy-matric.html#proverka"},{"k": "a", "a": "1.2 Действия над матрицами (лекция 1)", "b": "С матрицами можно делать четыре вещи: складывать, умножать на число, перемножать друг на друга и «переворачивать» (транспонировать). Первые две операции совсем простые. Третья — произведение матриц — устроена не так, как кажется, и именно на ней чаще всего ошибаются. Разберём каждую на числах из лекции. Сложение: клетка к клетке Сумма матриц Суммой двух матриц A = (a ij ) и B = (b ij ) одного разм", "u": "lectures/01/dejstviya-nad-matricami.html"},{"k": "a", "a": "Сложение — Действия над матрицами (1.2)", "b": "", "u": "lectures/01/dejstviya-nad-matricami.html#slozhenie"},{"k": "a", "a": "Умножение на число — Действия над матрицами (1.2)", "b": "", "u": "lectures/01/dejstviya-nad-matricami.html#chislo"},{"k": "a", "a": "Произведение матриц — Действия над матрицами (1.2)", "b": "", "u": "lectures/01/dejstviya-nad-matricami.html#proizvedenie"},{"k": "a", "a": "Свойства произведения — Действия над матрицами (1.2)", "b": "", "u": "lectures/01/dejstviya-nad-matricami.html#svojstva"},{"k": "a", "a": "Транспонирование — Действия над матрицами (1.2)", "b": "", "u": "lectures/01/dejstviya-nad-matricami.html#transp"},{"k": "a", "a": "Симметрические — Действия над матрицами (1.2)", "b": "", "u": "lectures/01/dejstviya-nad-matricami.html#simm"},{"k": "a", "a": "Частые ошибки — Действия над матрицами (1.2)", "b": "", "u": "lectures/01/dejstviya-nad-matricami.html#oshibki"},{"k": "a", "a": "Кратко — Действия над матрицами (1.2)", "b": "", "u": "lectures/01/dejstviya-nad-matricami.html#kratko"},{"k": "a", "a": "Проверь себя — Действия над матрицами (1.2)", "b": "", "u": "lectures/01/dejstviya-nad-matricami.html#proverka"},{"k": "a", "a": "1.3 Определитель: 2×2 и 3×3 (лекция 1)", "b": "Определитель — это одно число, которое «сворачивает» квадратную матрицу. По нему узнают, можно ли обратить матрицу (статья 1.6), а в лекции 2 он понадобится для решения систем уравнений. Сейчас учимся его считать для порядков 1, 2 и 3. Для больших порядков будут другие приёмы (статьи 1.4 и 1.5). Определение и обозначения Определитель Для квадратной матрицы A порядка n вводят числовую характеристик", "u": "lectures/01/opredelitel-2-i-3.html"},{"k": "a", "a": "Определение — Определитель: 2×2 и 3×3 (1.3)", "b": "", "u": "lectures/01/opredelitel-2-i-3.html#opredelenie"},{"k": "a", "a": "Порядок 2 — Определитель: 2×2 и 3×3 (1.3)", "b": "", "u": "lectures/01/opredelitel-2-i-3.html#d2"},{"k": "a", "a": "Порядок 3 и Саррюс — Определитель: 2×2 и 3×3 (1.3)", "b": "", "u": "lectures/01/opredelitel-2-i-3.html#d3"},{"k": "a", "a": "Когда определитель нуль — Определитель: 2×2 и 3×3 (1.3)", "b": "", "u": "lectures/01/opredelitel-2-i-3.html#nol"},{"k": "a", "a": "Частые ошибки — Определитель: 2×2 и 3×3 (1.3)", "b": "", "u": "lectures/01/opredelitel-2-i-3.html#oshibki"},{"k": "a", "a": "Кратко — Определитель: 2×2 и 3×3 (1.3)", "b": "", "u": "lectures/01/opredelitel-2-i-3.html#kratko"},{"k": "a", "a": "Проверь себя — Определитель: 2×2 и 3×3 (1.3)", "b": "", "u": "lectures/01/opredelitel-2-i-3.html#proverka"},{"k": "a", "a": "1.4 Свойства определителей (лекция 1)", "b": "Считать определитель «в лоб» долго, особенно для порядка 4 и выше. Свойства определителя позволяют его упрощать: менять местами строки, выносить множители, обнулять элементы. Главное из них — можно прибавлять к одной строке другую, умноженную на число, и значение не изменится . Именно оно превращает громоздкий определитель в треугольный, а у треугольного ответ получается одним умножением. Что тако", "u": "lectures/01/svojstva-opredelitelej.html"},{"k": "a", "a": "Что такое ряд — Свойства определителей (1.4)", "b": "", "u": "lectures/01/svojstva-opredelitelej.html#ryad"},{"k": "a", "a": "Свойства 1–7 — Свойства определителей (1.4)", "b": "", "u": "lectures/01/svojstva-opredelitelej.html#svojstva"},{"k": "a", "a": "Свойства 10–12 — Свойства определителей (1.4)", "b": "", "u": "lectures/01/svojstva-opredelitelej.html#proizv"},{"k": "a", "a": "Приём: треугольный вид — Свойства определителей (1.4)", "b": "", "u": "lectures/01/svojstva-opredelitelej.html#priem"},{"k": "a", "a": "Частые ошибки — Свойства определителей (1.4)", "b": "", "u": "lectures/01/svojstva-opredelitelej.html#oshibki"},{"k": "a", "a": "Кратко — Свойства определителей (1.4)", "b": "", "u": "lectures/01/svojstva-opredelitelej.html#kratko"},{"k": "a", "a": "Проверь себя — Свойства определителей (1.4)", "b": "", "u": "lectures/01/svojstva-opredelitelej.html#proverka"},{"k": "a", "a": "1.5 Миноры и разложение определителя (лекция 1)", "b": "Определитель 2×2 считается в одну строчку, 3×3 — по правилу Саррюса (шесть слагаемых). А что делать с 4×4? Правила треугольников для него нет, а в полной формуле было бы 24 слагаемых. Выход — свести большой определитель к определителям поменьше. Для этого и нужны миноры и алгебраические дополнения : они «разворачивают» определитель порядка n в сумму определителей порядка n − 1. Повторил пару раз —", "u": "lectures/01/minory-i-razlozhenie.html"},{"k": "a", "a": "Минор — Миноры и разложение определителя (1.5)", "b": "", "u": "lectures/01/minory-i-razlozhenie.html#minor"},{"k": "a", "a": "Алгебраическое дополнение — Миноры и разложение определителя (1.5)", "b": "", "u": "lectures/01/minory-i-razlozhenie.html#dopolnenie"},{"k": "a", "a": "Разложение по ряду — Миноры и разложение определителя (1.5)", "b": "", "u": "lectures/01/minory-i-razlozhenie.html#razlozhenie"},{"k": "a", "a": "Пример из лекции — Миноры и разложение определителя (1.5)", "b": "", "u": "lectures/01/minory-i-razlozhenie.html#primer1"},{"k": "a", "a": "Какой ряд выбрать — Миноры и разложение определителя (1.5)", "b": "", "u": "lectures/01/minory-i-razlozhenie.html#vybor"},{"k": "a", "a": "Создаём нули — Миноры и разложение определителя (1.5)", "b": "", "u": "lectures/01/minory-i-razlozhenie.html#nuli"},{"k": "a", "a": "Чужие дополнения — Миноры и разложение определителя (1.5)", "b": "", "u": "lectures/01/minory-i-razlozhenie.html#chuzhie"},{"k": "a", "a": "Частые ошибки — Миноры и разложение определителя (1.5)", "b": "", "u": "lectures/01/minory-i-razlozhenie.html#oshibki"},{"k": "a", "a": "Кратко — Миноры и разложение определителя (1.5)", "b": "", "u": "lectures/01/minory-i-razlozhenie.html#kratko"},{"k": "a", "a": "Проверь себя — Миноры и разложение определителя (1.5)", "b": "", "u": "lectures/01/minory-i-razlozhenie.html#proverka"},{"k": "a", "a": "1.6 Обратная матрица и матричные уравнения (лекция 1)", "b": "Делить матрицу на матрицу нельзя. Зато у многих матриц есть обратная — аналог числа 1/a . Число a умножаем на 1/a и получаем единицу; матрицу A умножаем на A⁻¹ и получаем единичную матрицу. Обратная матрица помогает решать матричные уравнения и (лекция 2) системы линейных уравнений. В статье два способа её найти и несколько проверок, чтобы не ошибиться. Что такое обратная матрица Невырожденная мат", "u": "lectures/01/obratnaya-matrica.html"},{"k": "a", "a": "Что такое обратная — Обратная матрица и матричные уравнения (1.6)", "b": "", "u": "lectures/01/obratnaya-matrica.html#chto"},{"k": "a", "a": "Способ 1: присоединённая — Обратная матрица и матричные уравнения (1.6)", "b": "", "u": "lectures/01/obratnaya-matrica.html#adj"},{"k": "a", "a": "Способ 2: преобразования — Обратная матрица и матричные уравнения (1.6)", "b": "", "u": "lectures/01/obratnaya-matrica.html#elem"},{"k": "a", "a": "Свойства — Обратная матрица и матричные уравнения (1.6)", "b": "", "u": "lectures/01/obratnaya-matrica.html#svojstva"},{"k": "a", "a": "Матричные уравнения — Обратная матрица и матричные уравнения (1.6)", "b": "", "u": "lectures/01/obratnaya-matrica.html#uravneniya"},{"k": "a", "a": "Частые ошибки — Обратная матрица и матричные уравнения (1.6)", "b": "", "u": "lectures/01/obratnaya-matrica.html#oshibki"},{"k": "a", "a": "Кратко — Обратная матрица и матричные уравнения (1.6)", "b": "", "u": "lectures/01/obratnaya-matrica.html#kratko"},{"k": "a", "a": "Проверь себя — Обратная матрица и матричные уравнения (1.6)", "b": "", "u": "lectures/01/obratnaya-matrica.html#proverka"},{"k": "a", "a": "1.7 Ранг матрицы (лекция 1)", "b": "Ранг матрицы отвечает на вопрос: сколько в ней «по-настоящему разных» строк? Если одна строка получается из других (сложением, умножением на число), новой информации она не несёт и на ранг не влияет. Ранг нужен в лекции 2: по нему узнают, есть ли у системы уравнений решения. Здесь два способа его находить и связь с линейной зависимостью строк. Миноры произвольной матрицы Раньше (статья 1.5) минор ", "u": "lectures/01/rang-matricy.html"},{"k": "a", "a": "Миноры матрицы — Ранг матрицы (1.7)", "b": "", "u": "lectures/01/rang-matricy.html#minory"},{"k": "a", "a": "Что такое ранг — Ранг матрицы (1.7)", "b": "", "u": "lectures/01/rang-matricy.html#rang"},{"k": "a", "a": "Метод окаймляющих миноров — Ранг матрицы (1.7)", "b": "", "u": "lectures/01/rang-matricy.html#okajm"},{"k": "a", "a": "Метод преобразований — Ранг матрицы (1.7)", "b": "", "u": "lectures/01/rang-matricy.html#stupeni"},{"k": "a", "a": "Линейная зависимость — Ранг матрицы (1.7)", "b": "", "u": "lectures/01/rang-matricy.html#zavis"},{"k": "a", "a": "Частые ошибки — Ранг матрицы (1.7)", "b": "", "u": "lectures/01/rang-matricy.html#oshibki"},{"k": "a", "a": "Кратко — Ранг матрицы (1.7)", "b": "", "u": "lectures/01/rang-matricy.html#kratko"},{"k": "a", "a": "Проверь себя — Ранг матрицы (1.7)", "b": "", "u": "lectures/01/rang-matricy.html#proverka"},{"k": "a", "a": "1.8 Практикум: типовые задачи практик 1 и 2 (лекция 1)", "b": "Практики № 1 и № 2 — сборники типовых задач: линейные комбинации матриц, произведения (2×2, 3×3, прямоугольные, A·A T , A² ), определители 3×3 и 4×4, обратная матрица двумя способами, ступенчатый и канонический вид, ранг. Методы разобраны в статьях 1.1–1.7, но на практике попадаются приёмы и названия, которых там нет. Здесь — словарь практики и раздел на каждый тип задач, в порядке заданий. Числа ", "u": "lectures/01/praktikum.html"},{"k": "a", "a": "Словарь практики — Практикум: типовые задачи практик 1 и 2 (1.8)", "b": "", "u": "lectures/01/praktikum.html#slovar"},{"k": "a", "a": "Линейная комбинация — Практикум: типовые задачи практик 1 и 2 (1.8)", "b": "", "u": "lectures/01/praktikum.html#komb"},{"k": "a", "a": "Произведение 3×3 — Практикум: типовые задачи практик 1 и 2 (1.8)", "b": "", "u": "lectures/01/praktikum.html#proizv"},{"k": "a", "a": "Размеры, столбец, цепочка — Практикум: типовые задачи практик 1 и 2 (1.8)", "b": "", "u": "lectures/01/praktikum.html#razmery"},{"k": "a", "a": "A·Aᵀ и A² — Практикум: типовые задачи практик 1 и 2 (1.8)", "b": "", "u": "lectures/01/praktikum.html#aat"},{"k": "a", "a": "Определитель 3×3 — Практикум: типовые задачи практик 1 и 2 (1.8)", "b": "", "u": "lectures/01/praktikum.html#det3"},{"k": "a", "a": "Определитель 4×4 — Практикум: типовые задачи практик 1 и 2 (1.8)", "b": "", "u": "lectures/01/praktikum.html#det4"},{"k": "a", "a": "Обратная матрица — Практикум: типовые задачи практик 1 и 2 (1.8)", "b": "", "u": "lectures/01/praktikum.html#obr"},{"k": "a", "a": "Ступенчатый вид и ранг — Практикум: типовые задачи практик 1 и 2 (1.8)", "b": "", "u": "lectures/01/praktikum.html#rang"},{"k": "a", "a": "Опечатки в пособиях — Практикум: типовые задачи практик 1 и 2 (1.8)", "b": "", "u": "lectures/01/praktikum.html#opechatki"},{"k": "a", "a": "Кратко — Практикум: типовые задачи практик 1 и 2 (1.8)", "b": "", "u": "lectures/01/praktikum.html#kratko"},{"k": "a", "a": "Проверь себя — Практикум: типовые задачи практик 1 и 2 (1.8)", "b": "", "u": "lectures/01/praktikum.html#proverka"},{"k": "a", "a": "2.1 Система линейных уравнений: запись и основные понятия (лекция 2)", "b": "Система линейных алгебраических уравнений (СЛАУ) — это несколько уравнений первой степени с одними и теми же неизвестными, которые должны выполняться одновременно. Вся лекция 2 отвечает на три вопроса: есть ли у системы решения, сколько их и как их найти. В этой статье мы учим язык: как записать систему матрицами, что называть решением и какими бывают системы. Без этого не читаются ни теорема Крон", "u": "lectures/02/osnovnye-ponyatiya.html"},{"k": "a", "a": "Что такое система — Система линейных уравнений: запись и основные понятия (2.1)", "b": "", "u": "lectures/02/osnovnye-ponyatiya.html#chto"},{"k": "a", "a": "Матричная запись — Система линейных уравнений: запись и основные понятия (2.1)", "b": "", "u": "lectures/02/osnovnye-ponyatiya.html#matrica"},{"k": "a", "a": "Решение — Система линейных уравнений: запись и основные понятия (2.1)", "b": "", "u": "lectures/02/osnovnye-ponyatiya.html#reshenie"},{"k": "a", "a": "Виды систем — Система линейных уравнений: запись и основные понятия (2.1)", "b": "", "u": "lectures/02/osnovnye-ponyatiya.html#vidy"},{"k": "a", "a": "Две неизвестные: картинка — Система линейных уравнений: запись и основные понятия (2.1)", "b": "", "u": "lectures/02/osnovnye-ponyatiya.html#geom"},{"k": "a", "a": "Частые ошибки — Система линейных уравнений: запись и основные понятия (2.1)", "b": "", "u": "lectures/02/osnovnye-ponyatiya.html#oshibki"},{"k": "a", "a": "Кратко — Система линейных уравнений: запись и основные понятия (2.1)", "b": "", "u": "lectures/02/osnovnye-ponyatiya.html#kratko"},{"k": "a", "a": "Проверь себя — Система линейных уравнений: запись и основные понятия (2.1)", "b": "", "u": "lectures/02/osnovnye-ponyatiya.html#proverka"},{"k": "a", "a": "2.2 Матричный метод решения систем (лекция 2)", "b": "Если в системе столько же уравнений, сколько неизвестных, и определитель из коэффициентов не равен нулю, систему можно решить «одной формулой» через обратную матрицу. Это матричный метод. Он коротко записывается и опирается на всё, что мы выучили в лекции 1, но требует найти обратную матрицу. Поэтому в статье заодно разберём, когда метод оправдан, а когда лучше взять другой. Квадратная система и е", "u": "lectures/02/matrichnyj-metod.html"},{"k": "a", "a": "Невырожденная система — Матричный метод решения систем (2.2)", "b": "", "u": "lectures/02/matrichnyj-metod.html#nevyrozh"},{"k": "a", "a": "Вывод X = A⁻¹B — Матричный метод решения систем (2.2)", "b": "", "u": "lectures/02/matrichnyj-metod.html#vyvod"},{"k": "a", "a": "Алгоритм — Матричный метод решения систем (2.2)", "b": "", "u": "lectures/02/matrichnyj-metod.html#algoritm"},{"k": "a", "a": "Примеры — Матричный метод решения систем (2.2)", "b": "", "u": "lectures/02/matrichnyj-metod.html#primery"},{"k": "a", "a": "Если Δ = 0 — Матричный метод решения систем (2.2)", "b": "", "u": "lectures/02/matrichnyj-metod.html#delta0"},{"k": "a", "a": "Когда выбирать метод — Матричный метод решения систем (2.2)", "b": "", "u": "lectures/02/matrichnyj-metod.html#kogda"},{"k": "a", "a": "Частые ошибки — Матричный метод решения систем (2.2)", "b": "", "u": "lectures/02/matrichnyj-metod.html#oshibki"},{"k": "a", "a": "Кратко — Матричный метод решения систем (2.2)", "b": "", "u": "lectures/02/matrichnyj-metod.html#kratko"},{"k": "a", "a": "Проверь себя — Матричный метод решения систем (2.2)", "b": "", "u": "lectures/02/matrichnyj-metod.html#proverka"},{"k": "a", "a": "2.3 Формулы Крамера (лекция 2)", "b": "Формулы Крамера — второй способ решить квадратную невырожденную систему. Он вытекает из матричного метода, но обходится без обратной матрицы: каждая неизвестная считается как отношение двух определителей. Для систем 2×2 и 3×3 это самый короткий путь. Кроме того, к формулам Крамера придётся вернуться в статьях 2.4, 2.6 и 2.7, когда будем находить главные неизвестные. Формулы Крамера Формулы Крамера", "u": "lectures/02/formuly-kramera.html"},{"k": "a", "a": "Формулы Крамера — Формулы Крамера (2.3)", "b": "", "u": "lectures/02/formuly-kramera.html#formuly"},{"k": "a", "a": "Откуда они берутся — Формулы Крамера (2.3)", "b": "", "u": "lectures/02/formuly-kramera.html#vyvod"},{"k": "a", "a": "Алгоритм — Формулы Крамера (2.3)", "b": "", "u": "lectures/02/formuly-kramera.html#algoritm"},{"k": "a", "a": "Примеры — Формулы Крамера (2.3)", "b": "", "u": "lectures/02/formuly-kramera.html#primery"},{"k": "a", "a": "Если Δ = 0 — Формулы Крамера (2.3)", "b": "", "u": "lectures/02/formuly-kramera.html#delta0"},{"k": "a", "a": "Крамер или матричный метод — Формулы Крамера (2.3)", "b": "", "u": "lectures/02/formuly-kramera.html#sravnenie"},{"k": "a", "a": "Частые ошибки — Формулы Крамера (2.3)", "b": "", "u": "lectures/02/formuly-kramera.html#oshibki"},{"k": "a", "a": "Кратко — Формулы Крамера (2.3)", "b": "", "u": "lectures/02/formuly-kramera.html#kratko"},{"k": "a", "a": "Проверь себя — Формулы Крамера (2.3)", "b": "", "u": "lectures/02/formuly-kramera.html#proverka"},{"k": "a", "a": "2.4 Теорема Кронекера–Капелли и общее решение системы (лекция 2)", "b": "До сих пор система была квадратной и невырожденной. Теперь возьмём произвольную: уравнений может быть больше, меньше или столько же, сколько неизвестных, а определителя у матрицы может не быть вовсе. Как узнать, есть ли решения и сколько их? Ответ даёт теорема Кронекера–Капелли: через ранги двух матриц. А затем идёт правило, которое шаг за шагом приводит к общему решению : главные неизвестные выра", "u": "lectures/02/kronecker-kapelli.html"},{"k": "a", "a": "Теорема Кронекера–Капелли — Теорема Кронекера–Капелли и общее решение системы (2.4)", "b": "", "u": "lectures/02/kronecker-kapelli.html#kk"},{"k": "a", "a": "Сколько решений — Теорема Кронекера–Капелли и общее решение системы (2.4)", "b": "", "u": "lectures/02/kronecker-kapelli.html#skolko"},{"k": "a", "a": "Главные и свободные неизвестные — Теорема Кронекера–Капелли и общее решение системы (2.4)", "b": "", "u": "lectures/02/kronecker-kapelli.html#neizv"},{"k": "a", "a": "Правила решения — Теорема Кронекера–Капелли и общее решение системы (2.4)", "b": "", "u": "lectures/02/kronecker-kapelli.html#pravila"},{"k": "a", "a": "Пример из лекции — Теорема Кронекера–Капелли и общее решение системы (2.4)", "b": "", "u": "lectures/02/kronecker-kapelli.html#primer1"},{"k": "a", "a": "Несовместная система — Теорема Кронекера–Капелли и общее решение системы (2.4)", "b": "", "u": "lectures/02/kronecker-kapelli.html#primer2"},{"k": "a", "a": "Другие главные неизвестные — Теорема Кронекера–Капелли и общее решение системы (2.4)", "b": "", "u": "lectures/02/kronecker-kapelli.html#primer3"},{"k": "a", "a": "Частые ошибки — Теорема Кронекера–Капелли и общее решение системы (2.4)", "b": "", "u": "lectures/02/kronecker-kapelli.html#oshibki"},{"k": "a", "a": "Кратко — Теорема Кронекера–Капелли и общее решение системы (2.4)", "b": "", "u": "lectures/02/kronecker-kapelli.html#kratko"},{"k": "a", "a": "Проверь себя — Теорема Кронекера–Капелли и общее решение системы (2.4)", "b": "", "u": "lectures/02/kronecker-kapelli.html#proverka"},{"k": "a", "a": "2.5 Метод Гаусса (лекция 2)", "b": "Метод Гаусса — главный рабочий инструмент лекции. Он годится для любой системы: квадратной и прямоугольной, определённой и неопределённой. Сам показывает несовместность и заодно считает ранги. Идея знакома со школы: складываем уравнения так, чтобы очередная неизвестная пропала, и исключаем неизвестные одну за другой, пока система не станет настолько простой, что её можно решить снизу вверх. Идея м", "u": "lectures/02/metod-gaussa.html"},{"k": "a", "a": "Идея метода — Метод Гаусса (2.5)", "b": "", "u": "lectures/02/metod-gaussa.html#idea"},{"k": "a", "a": "Ступенчатый вид — Метод Гаусса (2.5)", "b": "", "u": "lectures/02/metod-gaussa.html#stupen"},{"k": "a", "a": "Прямой ход — Метод Гаусса (2.5)", "b": "", "u": "lectures/02/metod-gaussa.html#pryamoj"},{"k": "a", "a": "Обратный ход — Метод Гаусса (2.5)", "b": "", "u": "lectures/02/metod-gaussa.html#obratnyj"},{"k": "a", "a": "Примеры — Метод Гаусса (2.5)", "b": "", "u": "lectures/02/metod-gaussa.html#primery"},{"k": "a", "a": "Частые ошибки — Метод Гаусса (2.5)", "b": "", "u": "lectures/02/metod-gaussa.html#oshibki"},{"k": "a", "a": "Кратко — Метод Гаусса (2.5)", "b": "", "u": "lectures/02/metod-gaussa.html#kratko"},{"k": "a", "a": "Проверь себя — Метод Гаусса (2.5)", "b": "", "u": "lectures/02/metod-gaussa.html#proverka"},{"k": "a", "a": "2.6 Однородные системы и фундаментальная система решений (лекция 2)", "b": "Однородные системы — это системы, у которых справа стоят одни нули. Устроены они особенно красиво. Решение у такой системы есть всегда, а когда решений больше одного, все они собираются из нескольких «кирпичиков» — фундаментальной системы решений (ФСР). Эти же кирпичики понадобятся в статье 2.7 для неоднородных систем. Однородная система Однородная система Система линейных уравнений называется одн", "u": "lectures/02/odnorodnye-fsr.html"},{"k": "a", "a": "Однородная система — Однородные системы и фундаментальная система решений (2.6)", "b": "", "u": "lectures/02/odnorodnye-fsr.html#opred"},{"k": "a", "a": "Когда есть ненулевые решения — Однородные системы и фундаментальная система решений (2.6)", "b": "", "u": "lectures/02/odnorodnye-fsr.html#teorema"},{"k": "a", "a": "Свойства решений — Однородные системы и фундаментальная система решений (2.6)", "b": "", "u": "lectures/02/odnorodnye-fsr.html#svojstva"},{"k": "a", "a": "ФСР — Однородные системы и фундаментальная система решений (2.6)", "b": "", "u": "lectures/02/odnorodnye-fsr.html#fsr"},{"k": "a", "a": "Как построить ФСР — Однородные системы и фундаментальная система решений (2.6)", "b": "", "u": "lectures/02/odnorodnye-fsr.html#postroenie"},{"k": "a", "a": "Пример из лекции — Однородные системы и фундаментальная система решений (2.6)", "b": "", "u": "lectures/02/odnorodnye-fsr.html#primer"},{"k": "a", "a": "Частые ошибки — Однородные системы и фундаментальная система решений (2.6)", "b": "", "u": "lectures/02/odnorodnye-fsr.html#oshibki"},{"k": "a", "a": "Кратко — Однородные системы и фундаментальная система решений (2.6)", "b": "", "u": "lectures/02/odnorodnye-fsr.html#kratko"},{"k": "a", "a": "Проверь себя — Однородные системы и фундаментальная система решений (2.6)", "b": "", "u": "lectures/02/odnorodnye-fsr.html#proverka"},{"k": "a", "a": "2.7 Общее решение неоднородной системы (лекция 2)", "b": "Общее решение неоднородной системы устроено просто: нужно одно её частное решение, а к нему добавляется всё, что даёт соответствующая однородная система. Так задача сводится к уже знакомой (ФСР, статья 2.6), а ответ получает аккуратную запись X = X₀ + c₁e₁ + … + c k e k . Теорема о структуре общего решения Соответствующая однородная система Для неоднородной системы A·X = B соответствующей однородн", "u": "lectures/02/obshchee-reshenie.html"},{"k": "a", "a": "Теорема о структуре — Общее решение неоднородной системы (2.7)", "b": "", "u": "lectures/02/obshchee-reshenie.html#teorema"},{"k": "a", "a": "Картинка — Общее решение неоднородной системы (2.7)", "b": "", "u": "lectures/02/obshchee-reshenie.html#kartinka"},{"k": "a", "a": "Алгоритм — Общее решение неоднородной системы (2.7)", "b": "", "u": "lectures/02/obshchee-reshenie.html#algoritm"},{"k": "a", "a": "Пример из лекции — Общее решение неоднородной системы (2.7)", "b": "", "u": "lectures/02/obshchee-reshenie.html#primer1"},{"k": "a", "a": "Ещё примеры — Общее решение неоднородной системы (2.7)", "b": "", "u": "lectures/02/obshchee-reshenie.html#primery"},{"k": "a", "a": "Частые ошибки — Общее решение неоднородной системы (2.7)", "b": "", "u": "lectures/02/obshchee-reshenie.html#oshibki"},{"k": "a", "a": "Кратко — Общее решение неоднородной системы (2.7)", "b": "", "u": "lectures/02/obshchee-reshenie.html#kratko"},{"k": "a", "a": "Проверь себя — Общее решение неоднородной системы (2.7)", "b": "", "u": "lectures/02/obshchee-reshenie.html#proverka"},{"k": "a", "a": "2.8 Метод Жордана–Гаусса (лекция 2)", "b": "Метод Жордана–Гаусса — продолжение метода Гаусса. Нули делаются не только под главными элементами, но и над ними, а сами главные элементы превращаются в единицы. Тогда обратный ход не нужен: решение читается прямо из матрицы. Это тот же приём, которым мы находили обратную матрицу в статье 1.6: (A | E) → (E | A⁻¹) . Заодно метод находит ранг. Идея и вид матрицы Элементарными преобразованиями строк ", "u": "lectures/02/metod-zhordana-gaussa.html"},{"k": "a", "a": "Идея и вид матрицы — Метод Жордана–Гаусса (2.8)", "b": "", "u": "lectures/02/metod-zhordana-gaussa.html#ideya"},{"k": "a", "a": "Алгоритм — Метод Жордана–Гаусса (2.8)", "b": "", "u": "lectures/02/metod-zhordana-gaussa.html#algoritm"},{"k": "a", "a": "Примеры — Метод Жордана–Гаусса (2.8)", "b": "", "u": "lectures/02/metod-zhordana-gaussa.html#primery"},{"k": "a", "a": "Ранг методом Жордана–Гаусса — Метод Жордана–Гаусса (2.8)", "b": "", "u": "lectures/02/metod-zhordana-gaussa.html#rang"},{"k": "a", "a": "Гаусс или Жордан–Гаусс — Метод Жордана–Гаусса (2.8)", "b": "", "u": "lectures/02/metod-zhordana-gaussa.html#sravnenie"},{"k": "a", "a": "Частые ошибки — Метод Жордана–Гаусса (2.8)", "b": "", "u": "lectures/02/metod-zhordana-gaussa.html#oshibki"},{"k": "a", "a": "Кратко — Метод Жордана–Гаусса (2.8)", "b": "", "u": "lectures/02/metod-zhordana-gaussa.html#kratko"},{"k": "a", "a": "Проверь себя — Метод Жордана–Гаусса (2.8)", "b": "", "u": "lectures/02/metod-zhordana-gaussa.html#proverka"},{"k": "a", "a": "2.9 Практикум: типовые задачи практики 3 (лекция 2)", "b": "Практика № 3 состоит из образцов 1–7 и двух заданий: 30 вариантов по две системы 3×3, которые решают тремя способами, и 30 однородных систем, у которых ищут ФСР. Методы разобраны в статьях 2.1–2.8. Здесь собрано то, чего в них нет: язык пособия, приёмы против громоздких дробей, одна система тремя способами и опечатки пособия. Карта практики Что в практике Где метод Задание 1, п. 1: Гаусс (образцы ", "u": "lectures/02/praktikum.html"},{"k": "a", "a": "Карта практики — Практикум: типовые задачи практики 3 (2.9)", "b": "", "u": "lectures/02/praktikum.html#karta"},{"k": "a", "a": "Словарь практики — Практикум: типовые задачи практики 3 (2.9)", "b": "", "u": "lectures/02/praktikum.html#slovar"},{"k": "a", "a": "Гаусс без ведущей единицы — Практикум: типовые задачи практики 3 (2.9)", "b": "", "u": "lectures/02/praktikum.html#gauss"},{"k": "a", "a": "Одна система тремя способами — Практикум: типовые задачи практики 3 (2.9)", "b": "", "u": "lectures/02/praktikum.html#tri"},{"k": "a", "a": "ФСР без дробей — Практикум: типовые задачи практики 3 (2.9)", "b": "", "u": "lectures/02/praktikum.html#fsr"},{"k": "a", "a": "Пустая ФСР и m > n — Практикум: типовые задачи практики 3 (2.9)", "b": "", "u": "lectures/02/praktikum.html#pusto"},{"k": "a", "a": "Частые ошибки — Практикум: типовые задачи практики 3 (2.9)", "b": "", "u": "lectures/02/praktikum.html#oshibki"},{"k": "a", "a": "Опечатки в пособии практики — Практикум: типовые задачи практики 3 (2.9)", "b": "", "u": "lectures/02/praktikum.html#opechatki"},{"k": "a", "a": "Кратко — Практикум: типовые задачи практики 3 (2.9)", "b": "", "u": "lectures/02/praktikum.html#kratko"},{"k": "a", "a": "Проверь себя — Практикум: типовые задачи практики 3 (2.9)", "b": "", "u": "lectures/02/praktikum.html#proverka"},{"k": "a", "a": "3.1 Линейное пространство: определение, аксиомы, примеры (лекция 3)", "b": "До сих пор мы складывали и умножали на число таблицы чисел: матрицы, столбцы неизвестных, строки коэффициентов. Но то же самое умеют делать и стрелки на плоскости, и многочлены, и функции. Линейное пространство — общий язык для всех таких объектов сразу: правила игры (аксиомы) договариваются один раз, а дальше теоремы доказываются сразу для всех примеров. В этой статье: определение, восемь аксиом,", "u": "lectures/03/definition.html"},{"k": "a", "a": "Идея и обозначения — Линейное пространство: определение, аксиомы, примеры (3.1)", "b": "", "u": "lectures/03/definition.html#idea"},{"k": "a", "a": "Определение — Линейное пространство: определение, аксиомы, примеры (3.1)", "b": "", "u": "lectures/03/definition.html#opred"},{"k": "a", "a": "Восемь аксиом — Линейное пространство: определение, аксиомы, примеры (3.1)", "b": "", "u": "lectures/03/definition.html#aksiomy"},{"k": "a", "a": "Следствия из аксиом — Линейное пространство: определение, аксиомы, примеры (3.1)", "b": "", "u": "lectures/03/definition.html#sledstviya"},{"k": "a", "a": "Примеры пространств — Линейное пространство: определение, аксиомы, примеры (3.1)", "b": "", "u": "lectures/03/definition.html#primery"},{"k": "a", "a": "Арифметические пространства — Линейное пространство: определение, аксиомы, примеры (3.1)", "b": "", "u": "lectures/03/definition.html#rn"},{"k": "a", "a": "Пример из лекции — Линейное пространство: определение, аксиомы, примеры (3.1)", "b": "", "u": "lectures/03/definition.html#primer1"},{"k": "a", "a": "Как проверить, что это пространство — Линейное пространство: определение, аксиомы, примеры (3.1)", "b": "", "u": "lectures/03/definition.html#proverka"},{"k": "a", "a": "Частые ошибки — Линейное пространство: определение, аксиомы, примеры (3.1)", "b": "", "u": "lectures/03/definition.html#oshibki"},{"k": "a", "a": "Кратко — Линейное пространство: определение, аксиомы, примеры (3.1)", "b": "", "u": "lectures/03/definition.html#kratko"},{"k": "a", "a": "Проверь себя — Линейное пространство: определение, аксиомы, примеры (3.1)", "b": "", "u": "lectures/03/definition.html#zadaniya"},{"k": "a", "a": "3.2 Линейная зависимость и независимость векторов (лекция 3)", "b": "Пусть дан набор векторов. Нет ли в нём лишних, то есть нельзя ли получить один из остальных сложением и умножением на число? Это и есть вопрос о линейной зависимости. Он возникает везде: при выборе базиса, при решении систем, при подсчёте размерности. В статье — точное определение (его часто формулируют неверно), критерий зависимости (теорема 1), две простые теоремы и рабочий способ проверки через", "u": "lectures/03/dependence.html"},{"k": "a", "a": "Линейная комбинация — Линейная зависимость и независимость векторов (3.2)", "b": "", "u": "lectures/03/dependence.html#kombinaciya"},{"k": "a", "a": "Зависимость и независимость — Линейная зависимость и независимость векторов (3.2)", "b": "", "u": "lectures/03/dependence.html#opred"},{"k": "a", "a": "Один, два, три вектора — Линейная зависимость и независимость векторов (3.2)", "b": "", "u": "lectures/03/dependence.html#malye"},{"k": "a", "a": "Теорема 1 — Линейная зависимость и независимость векторов (3.2)", "b": "", "u": "lectures/03/dependence.html#teorema1"},{"k": "a", "a": "Теоремы 2 и 3 — Линейная зависимость и независимость векторов (3.2)", "b": "", "u": "lectures/03/dependence.html#teoremy23"},{"k": "a", "a": "Как проверить в ℝⁿ — Линейная зависимость и независимость векторов (3.2)", "b": "", "u": "lectures/03/dependence.html#algoritm"},{"k": "a", "a": "Примеры — Линейная зависимость и независимость векторов (3.2)", "b": "", "u": "lectures/03/dependence.html#primery"},{"k": "a", "a": "Частые ошибки — Линейная зависимость и независимость векторов (3.2)", "b": "", "u": "lectures/03/dependence.html#oshibki"},{"k": "a", "a": "Кратко — Линейная зависимость и независимость векторов (3.2)", "b": "", "u": "lectures/03/dependence.html#kratko"},{"k": "a", "a": "Проверь себя — Линейная зависимость и независимость векторов (3.2)", "b": "", "u": "lectures/03/dependence.html#zadaniya"},{"k": "a", "a": "3.3 Размерность, базис и координаты (лекция 3)", "b": "В конечномерном пространстве (при n ≥ 1 ) бесконечно много векторов, но все они собираются из нескольких «кирпичиков» — базисных векторов — и притом единственным способом. Число кирпичиков называют размерностью, коэффициенты сборки — координатами. После выбора базиса вектор превращается в набор чисел, а действия над векторами — в действия над числами. Это главная идея лекции: она объясняет, почему", "u": "lectures/03/basis.html"},{"k": "a", "a": "Размерность — Размерность, базис и координаты (3.3)", "b": "", "u": "lectures/03/basis.html#razmernost"},{"k": "a", "a": "Базис — Размерность, базис и координаты (3.3)", "b": "", "u": "lectures/03/basis.html#bazis"},{"k": "a", "a": "Теорема 4 — Размерность, базис и координаты (3.3)", "b": "", "u": "lectures/03/basis.html#teorema4"},{"k": "a", "a": "Координаты — Размерность, базис и координаты (3.3)", "b": "", "u": "lectures/03/basis.html#koordinaty"},{"k": "a", "a": "Теорема 5 — Размерность, базис и координаты (3.3)", "b": "", "u": "lectures/03/basis.html#teorema5"},{"k": "a", "a": "Как проверить базис и найти координаты — Размерность, базис и координаты (3.3)", "b": "", "u": "lectures/03/basis.html#algoritm"},{"k": "a", "a": "Примеры — Размерность, базис и координаты (3.3)", "b": "", "u": "lectures/03/basis.html#primery"},{"k": "a", "a": "Частые ошибки — Размерность, базис и координаты (3.3)", "b": "", "u": "lectures/03/basis.html#oshibki"},{"k": "a", "a": "Кратко — Размерность, базис и координаты (3.3)", "b": "", "u": "lectures/03/basis.html#kratko"},{"k": "a", "a": "Проверь себя — Размерность, базис и координаты (3.3)", "b": "", "u": "lectures/03/basis.html#zadaniya"},{"k": "a", "a": "3.4 Изоморфизм линейных пространств (лекция 3)", "b": "Многочлены, матрицы, столбцы чисел: на вид совершенно разные объекты. Но после выбора базиса каждый из них записывается набором из n чисел, а действия над ними превращаются в покомпонентные. Значит, как «линейные пространства» они устроены одинаково. Это наблюдение оформляется понятием изоморфизма . Оно даёт сильный практический приём: любой вопрос о линейной зависимости, базисе, размерности в мно", "u": "lectures/03/isomorphism.html"},{"k": "a", "a": "Определение — Изоморфизм линейных пространств (3.4)", "b": "", "u": "lectures/03/isomorphism.html#opred"},{"k": "a", "a": "Что сохраняется — Изоморфизм линейных пространств (3.4)", "b": "", "u": "lectures/03/isomorphism.html#svojstva"},{"k": "a", "a": "Любые два n-мерных изоморфны — Изоморфизм линейных пространств (3.4)", "b": "", "u": "lectures/03/isomorphism.html#teorema"},{"k": "a", "a": "Как этим пользоваться — Изоморфизм линейных пространств (3.4)", "b": "", "u": "lectures/03/isomorphism.html#kak"},{"k": "a", "a": "Примеры — Изоморфизм линейных пространств (3.4)", "b": "", "u": "lectures/03/isomorphism.html#primery"},{"k": "a", "a": "Частые ошибки — Изоморфизм линейных пространств (3.4)", "b": "", "u": "lectures/03/isomorphism.html#oshibki"},{"k": "a", "a": "Кратко — Изоморфизм линейных пространств (3.4)", "b": "", "u": "lectures/03/isomorphism.html#kratko"},{"k": "a", "a": "Проверь себя — Изоморфизм линейных пространств (3.4)", "b": "", "u": "lectures/03/isomorphism.html#zadaniya"},{"k": "a", "a": "3.5 Подпространства и линейная оболочка (лекция 3)", "b": "Внутри большого пространства всегда есть «пространства поменьше»: плоскость в трёхмерном пространстве, прямая на плоскости. Но не любая часть пространства так устроена: четверть плоскости или круг — не подходят. Точное условие — замкнутость относительно линейных операций. А ещё есть универсальный способ породить подпространство: взять несколько векторов и всевозможные их комбинации. Это линейная о", "u": "lectures/03/subspace.html"},{"k": "a", "a": "Подпространство — Подпространства и линейная оболочка (3.5)", "b": "", "u": "lectures/03/subspace.html#podprostranstvo"},{"k": "a", "a": "Как проверить — Подпространства и линейная оболочка (3.5)", "b": "", "u": "lectures/03/subspace.html#kriterij"},{"k": "a", "a": "Линейная оболочка — Подпространства и линейная оболочка (3.5)", "b": "", "u": "lectures/03/subspace.html#obolochka"},{"k": "a", "a": "Теорема 6 — Подпространства и линейная оболочка (3.5)", "b": "", "u": "lectures/03/subspace.html#teorema6"},{"k": "a", "a": "Размерность и базис оболочки — Подпространства и линейная оболочка (3.5)", "b": "", "u": "lectures/03/subspace.html#algoritm"},{"k": "a", "a": "Примеры — Подпространства и линейная оболочка (3.5)", "b": "", "u": "lectures/03/subspace.html#primery"},{"k": "a", "a": "Частые ошибки — Подпространства и линейная оболочка (3.5)", "b": "", "u": "lectures/03/subspace.html#oshibki"},{"k": "a", "a": "Кратко — Подпространства и линейная оболочка (3.5)", "b": "", "u": "lectures/03/subspace.html#kratko"},{"k": "a", "a": "Проверь себя — Подпространства и линейная оболочка (3.5)", "b": "", "u": "lectures/03/subspace.html#zadaniya"},{"k": "a", "a": "3.6 Аффинное пространство (лекция 3)", "b": "В геометрии мы различаем точки (где находится объект) и векторы (на сколько сместиться). Точки нельзя складывать: «Москва плюс Тверь» ничего не значит. А вот от точки отложить вектор и получить новую точку, или по двум точкам построить вектор из одной в другую — можно. Математическая структура, которая это оформляет, называется аффинным пространством. Она нужна для геометрических задач: координаты", "u": "lectures/03/affine.html"},{"k": "a", "a": "Точки и векторы — Аффинное пространство (3.6)", "b": "", "u": "lectures/03/affine.html#zachem"},{"k": "a", "a": "Определение — Аффинное пространство (3.6)", "b": "", "u": "lectures/03/affine.html#opred"},{"k": "a", "a": "Простые утверждения — Аффинное пространство (3.6)", "b": "", "u": "lectures/03/affine.html#prostye"},{"k": "a", "a": "Аффинная система координат — Аффинное пространство (3.6)", "b": "", "u": "lectures/03/affine.html#koordinaty"},{"k": "a", "a": "Точка и вектор: что от чего зависит — Аффинное пространство (3.6)", "b": "", "u": "lectures/03/affine.html#tochka"},{"k": "a", "a": "Типовые задачи — Аффинное пространство (3.6)", "b": "", "u": "lectures/03/affine.html#algoritm"},{"k": "a", "a": "Примеры — Аффинное пространство (3.6)", "b": "", "u": "lectures/03/affine.html#primery"},{"k": "a", "a": "Частые ошибки — Аффинное пространство (3.6)", "b": "", "u": "lectures/03/affine.html#oshibki"},{"k": "a", "a": "Кратко — Аффинное пространство (3.6)", "b": "", "u": "lectures/03/affine.html#kratko"},{"k": "a", "a": "Проверь себя — Аффинное пространство (3.6)", "b": "", "u": "lectures/03/affine.html#zadaniya"},{"k": "a", "a": "3.7 Переход к другому базису (лекция 3)", "b": "Координаты вектора зависят от базиса: тот же вектор в другом базисе записывается другими числами. Как пересчитать координаты, не раскладывая вектор заново? Для этого вводят матрицу перехода: она хранит, как новый базис выражается через старый, и по ней, по формулам лекции, координаты пересчитываются одним умножением на матрицу. Главная сложность здесь — не вычисления, а направление: на что умножат", "u": "lectures/03/transition.html"},{"k": "a", "a": "Старый и новый базисы — Переход к другому базису (3.7)", "b": "", "u": "lectures/03/transition.html#staryj"},{"k": "a", "a": "Матрица перехода — Переход к другому базису (3.7)", "b": "", "u": "lectures/03/transition.html#matrica"},{"k": "a", "a": "Формулы для координат — Переход к другому базису (3.7)", "b": "", "u": "lectures/03/transition.html#formuly"},{"k": "a", "a": "В какую сторону работает C — Переход к другому базису (3.7)", "b": "", "u": "lectures/03/transition.html#napravlenie"},{"k": "a", "a": "Ортогональные матрицы — Переход к другому базису (3.7)", "b": "", "u": "lectures/03/transition.html#ortogonalnaya"},{"k": "a", "a": "Типовые задачи — Переход к другому базису (3.7)", "b": "", "u": "lectures/03/transition.html#algoritm"},{"k": "a", "a": "Примеры — Переход к другому базису (3.7)", "b": "", "u": "lectures/03/transition.html#primery"},{"k": "a", "a": "Частые ошибки — Переход к другому базису (3.7)", "b": "", "u": "lectures/03/transition.html#oshibki"},{"k": "a", "a": "Кратко — Переход к другому базису (3.7)", "b": "", "u": "lectures/03/transition.html#kratko"},{"k": "a", "a": "Проверь себя — Переход к другому базису (3.7)", "b": "", "u": "lectures/03/transition.html#zadaniya"},{"k": "a", "a": "3.8 Разбор задач для самостоятельного решения (лекция 3)", "b": "В конце лекции собраны 14 задач. У половины задач есть ответ, но нет решения, а в нескольких местах печатные условия и ответы не сходятся между собой. Здесь все задачи разобраны: что проверять, в каком порядке, как оформить. Ссылки ведут на статьи, где объяснена теория: аксиомы — статья 3.1, зависимость — 3.2, базис — 3.3, подпространства и оболочки — 3.5, смена базиса — 3.7. Каждый ответ пересчит", "u": "lectures/03/problems.html"},{"k": "a", "a": "Задачи 1–3: многочлены и матрицы — Разбор задач для самостоятельного решения (3.8)", "b": "", "u": "lectures/03/problems.html#p13"},{"k": "a", "a": "Задачи 4–5: необычные операции — Разбор задач для самостоятельного решения (3.8)", "b": "", "u": "lectures/03/problems.html#p45"},{"k": "a", "a": "Задачи 6–8: зависимость — Разбор задач для самостоятельного решения (3.8)", "b": "", "u": "lectures/03/problems.html#p68"},{"k": "a", "a": "Задачи 9–10: подпространство и оболочка — Разбор задач для самостоятельного решения (3.8)", "b": "", "u": "lectures/03/problems.html#p910"},{"k": "a", "a": "Задачи 11–14: новый базис — Разбор задач для самостоятельного решения (3.8)", "b": "", "u": "lectures/03/problems.html#p1114"},{"k": "a", "a": "Частые ошибки — Разбор задач для самостоятельного решения (3.8)", "b": "", "u": "lectures/03/problems.html#oshibki"},{"k": "a", "a": "Кратко — Разбор задач для самостоятельного решения (3.8)", "b": "", "u": "lectures/03/problems.html#kratko"},{"k": "a", "a": "Проверь себя — Разбор задач для самостоятельного решения (3.8)", "b": "", "u": "lectures/03/problems.html#zadaniya"},{"k": "a", "a": "3.9 Практикум 4: зависимость, базис, разложение векторов (лекция 3)", "b": "Практика № 4 говорит на языке статей 3.1–3.8, но с другими обозначениями и номерами аксиом, а часть её задач там не разобрана: зависимость функций, разложение по векторам фигуры, параметр при k &lt; n . Здесь — словарь «практика ↔ статьи», метод и пример на каждый тип, опечатки пособия. Словарь практики: обозначения и номера аксиом Математика та же, различаются буквы и порядок. Опаснее всего номер", "u": "lectures/03/praktikum-4.html"},{"k": "a", "a": "Словарь практики — Практикум 4: зависимость, базис, разложение векторов (3.9)", "b": "", "u": "lectures/03/praktikum-4.html#slovar"},{"k": "a", "a": "Функции как векторы — Практикум 4: зависимость, базис, разложение векторов (3.9)", "b": "", "u": "lectures/03/praktikum-4.html#funkcii"},{"k": "a", "a": "Зависимость функций — Практикум 4: зависимость, базис, разложение векторов (3.9)", "b": "", "u": "lectures/03/praktikum-4.html#zavfunk"},{"k": "a", "a": "Разложение по векторам фигуры — Практикум 4: зависимость, базис, разложение векторов (3.9)", "b": "", "u": "lectures/03/praktikum-4.html#figury"},{"k": "a", "a": "Параметр, коллинеарность — Практикум 4: зависимость, базис, разложение векторов (3.9)", "b": "", "u": "lectures/03/praktikum-4.html#parametr"},{"k": "a", "a": "Дополнение до базиса — Практикум 4: зависимость, базис, разложение векторов (3.9)", "b": "", "u": "lectures/03/praktikum-4.html#dopolnenie"},{"k": "a", "a": "Новый базис по соотношениям — Практикум 4: зависимость, базис, разложение векторов (3.9)", "b": "", "u": "lectures/03/praktikum-4.html#novyj"},{"k": "a", "a": "Опечатки и пробелы в пособии практики — Практикум 4: зависимость, базис, разложение векторов (3.9)", "b": "", "u": "lectures/03/praktikum-4.html#opechatki"},{"k": "a", "a": "Частые ошибки — Практикум 4: зависимость, базис, разложение векторов (3.9)", "b": "", "u": "lectures/03/praktikum-4.html#oshibki"},{"k": "a", "a": "Кратко — Практикум 4: зависимость, базис, разложение векторов (3.9)", "b": "", "u": "lectures/03/praktikum-4.html#kratko"},{"k": "a", "a": "Проверь себя — Практикум 4: зависимость, базис, разложение векторов (3.9)", "b": "", "u": "lectures/03/praktikum-4.html#zadaniya"},{"k": "a", "a": "3.10 Практикум 5: линейные многообразия, сумма и пересечение подпространств (лекция 3)", "b": "Практика № 5 называется «Аффинные векторные пространства». Аффинное пространство статьи 3.6 (точки и векторы) она как структуру не вводит, но линейное многообразие L + x₀ — это и есть аффинное подпространство : множество точек M₀ + L (в ℝⁿ , как в статье 3.6), где L — векторы между его точками. Кроме многообразий, практика охватывает сумму, пересечение и прямую сумму подпространств, зависимость си", "u": "lectures/03/praktikum-5.html"},{"k": "a", "a": "Карта практики — Практикум 5: линейные многообразия, сумма и пересечение подпространств (3.10)", "b": "", "u": "lectures/03/praktikum-5.html#karta"},{"k": "a", "a": "Линейное многообразие — Практикум 5: линейные многообразия, сумма и пересечение подпространств (3.10)", "b": "", "u": "lectures/03/praktikum-5.html#mnogoobrazie"},{"k": "a", "a": "Сумма, пересечение, прямая сумма — Практикум 5: линейные многообразия, сумма и пересечение подпространств (3.10)", "b": "", "u": "lectures/03/praktikum-5.html#summa"},{"k": "a", "a": "Подпространство решений и ФСР — Практикум 5: линейные многообразия, сумма и пересечение подпространств (3.10)", "b": "", "u": "lectures/03/praktikum-5.html#fsr"},{"k": "a", "a": "Подпространство или нет — Практикум 5: линейные многообразия, сумма и пересечение подпространств (3.10)", "b": "", "u": "lectures/03/praktikum-5.html#sluchai"},{"k": "a", "a": "Опечатки и неясности в пособии практики — Практикум 5: линейные многообразия, сумма и пересечение подпространств (3.10)", "b": "", "u": "lectures/03/praktikum-5.html#opechatki"},{"k": "a", "a": "Частые ошибки — Практикум 5: линейные многообразия, сумма и пересечение подпространств (3.10)", "b": "", "u": "lectures/03/praktikum-5.html#oshibki"},{"k": "a", "a": "Кратко — Практикум 5: линейные многообразия, сумма и пересечение подпространств (3.10)", "b": "", "u": "lectures/03/praktikum-5.html#kratko"},{"k": "a", "a": "Проверь себя — Практикум 5: линейные многообразия, сумма и пересечение подпространств (3.10)", "b": "", "u": "lectures/03/praktikum-5.html#zadaniya"},{"k": "a", "a": "4.1 Скалярное произведение и евклидово пространство (лекция 4)", "b": "В линейном пространстве (лекция 3) можно складывать векторы и умножать их на числа. А вот слов «длина», «угол», «перпендикулярны» там пока нет: сложение и умножение на число их не определяют. Их даёт одна дополнительная операция — скалярное произведение : правило, которое паре векторов ставит в соответствие число . В статье мы выясним, каким требованиям (аксиомам) это правило должно удовлетворять,", "u": "lectures/04/skalyarnoe-proizvedenie.html"},{"k": "a", "a": "Что такое норма — Скалярное произведение и евклидово пространство (4.1)", "b": "", "u": "lectures/04/skalyarnoe-proizvedenie.html#norma"},{"k": "a", "a": "Четыре аксиомы — Скалярное произведение и евклидово пространство (4.1)", "b": "", "u": "lectures/04/skalyarnoe-proizvedenie.html#skalyar"},{"k": "a", "a": "Стандартное произведение в ℝⁿ — Скалярное произведение и евклидово пространство (4.1)", "b": "", "u": "lectures/04/skalyarnoe-proizvedenie.html#rn"},{"k": "a", "a": "Не всякое правило подходит — Скалярное произведение и евклидово пространство (4.1)", "b": "", "u": "lectures/04/skalyarnoe-proizvedenie.html#ne"},{"k": "a", "a": "Длина вектора — Скалярное произведение и евклидово пространство (4.1)", "b": "", "u": "lectures/04/skalyarnoe-proizvedenie.html#dlina"},{"k": "a", "a": "Частые ошибки — Скалярное произведение и евклидово пространство (4.1)", "b": "", "u": "lectures/04/skalyarnoe-proizvedenie.html#oshibki"},{"k": "a", "a": "Кратко — Скалярное произведение и евклидово пространство (4.1)", "b": "", "u": "lectures/04/skalyarnoe-proizvedenie.html#kratko"},{"k": "a", "a": "Проверь себя — Скалярное произведение и евклидово пространство (4.1)", "b": "", "u": "lectures/04/skalyarnoe-proizvedenie.html#proverka"},{"k": "a", "a": "4.2 Длина, угол и неравенство Коши–Буняковского (лекция 4)", "b": "В статье 4.1 скалярное произведение дало длину вектора |x| = √(x, x) . Теперь нужен угол. Его хочется определить формулой cos φ = (x, y) / (|x|·|y|) , но корректно ли это? Косинус не бывает больше 1 по модулю, а вдруг дробь в произвольном евклидовом пространстве получится равной 2? Ответ даёт неравенство Коши–Буняковского: оно гарантирует, что дробь лежит в [−1; 1] . Из него же выводится неравенст", "u": "lectures/04/koshi-bunyakovskij.html"},{"k": "a", "a": "Неравенство Коши–Буняковского — Длина, угол и неравенство Коши–Буняковского (4.2)", "b": "", "u": "lectures/04/koshi-bunyakovskij.html#kb"},{"k": "a", "a": "Угол между векторами — Длина, угол и неравенство Коши–Буняковского (4.2)", "b": "", "u": "lectures/04/koshi-bunyakovskij.html#ugol"},{"k": "a", "a": "Ортогональность — Длина, угол и неравенство Коши–Буняковского (4.2)", "b": "", "u": "lectures/04/koshi-bunyakovskij.html#ortog"},{"k": "a", "a": "Неравенство треугольника — Длина, угол и неравенство Коши–Буняковского (4.2)", "b": "", "u": "lectures/04/koshi-bunyakovskij.html#mink"},{"k": "a", "a": "Проекция вектора — Длина, угол и неравенство Коши–Буняковского (4.2)", "b": "", "u": "lectures/04/koshi-bunyakovskij.html#proekciya"},{"k": "a", "a": "Частые ошибки — Длина, угол и неравенство Коши–Буняковского (4.2)", "b": "", "u": "lectures/04/koshi-bunyakovskij.html#oshibki"},{"k": "a", "a": "Кратко — Длина, угол и неравенство Коши–Буняковского (4.2)", "b": "", "u": "lectures/04/koshi-bunyakovskij.html#kratko"},{"k": "a", "a": "Проверь себя — Длина, угол и неравенство Коши–Буняковского (4.2)", "b": "", "u": "lectures/04/koshi-bunyakovskij.html#proverka"},{"k": "a", "a": "4.3 Ортогональные базисы и процесс ортогонализации (лекция 4)", "b": "Базисы бывают удобные и неудобные. В неудобном, чтобы найти координаты вектора, нужно решать систему уравнений (лекция 2). В ортогональном базисе каждая координата находится одним скалярным произведением, а само скалярное произведение считается по привычной формуле x₁y₁ + … + xₙyₙ . В статье: почему ортогональные системы всегда независимы, чем ортонормированный базис отличается от ортогонального, ", "u": "lectures/04/ortogonalnye-bazisy.html"},{"k": "a", "a": "Ортогональная система — Ортогональные базисы и процесс ортогонализации (4.3)", "b": "", "u": "lectures/04/ortogonalnye-bazisy.html#sistema"},{"k": "a", "a": "Ортогональный и ортонормированный базис — Ортогональные базисы и процесс ортогонализации (4.3)", "b": "", "u": "lectures/04/ortogonalnye-bazisy.html#bazis"},{"k": "a", "a": "Произведение в ортонормированном базисе — Ортогональные базисы и процесс ортогонализации (4.3)", "b": "", "u": "lectures/04/ortogonalnye-bazisy.html#formula"},{"k": "a", "a": "Процесс ортогонализации — Ортогональные базисы и процесс ортогонализации (4.3)", "b": "", "u": "lectures/04/ortogonalnye-bazisy.html#process"},{"k": "a", "a": "Примеры ортогонализации — Ортогональные базисы и процесс ортогонализации (4.3)", "b": "", "u": "lectures/04/ortogonalnye-bazisy.html#primery"},{"k": "a", "a": "Частые ошибки — Ортогональные базисы и процесс ортогонализации (4.3)", "b": "", "u": "lectures/04/ortogonalnye-bazisy.html#oshibki"},{"k": "a", "a": "Кратко — Ортогональные базисы и процесс ортогонализации (4.3)", "b": "", "u": "lectures/04/ortogonalnye-bazisy.html#kratko"},{"k": "a", "a": "Проверь себя — Ортогональные базисы и процесс ортогонализации (4.3)", "b": "", "u": "lectures/04/ortogonalnye-bazisy.html#proverka"},{"k": "a", "a": "4.4 Правая и левая тройки, векторное произведение (лекция 4)", "b": "Скалярное произведение двух векторов — число. Но в геометрии часто нужен вектор , перпендикулярный двум данным: нормаль к плоскости, ось вращения. Нужна и площадь параллелограмма, построенного на двух векторах. Всё это даёт векторное произведение a × b . Оно определено только для векторов в трёхмерном пространстве и зависит от ориентации — выбора, какая тройка считается «правой». Начнём с ориентац", "u": "lectures/04/vektornoe-proizvedenie.html"},{"k": "a", "a": "Правая и левая тройки — Правая и левая тройки, векторное произведение (4.4)", "b": "", "u": "lectures/04/vektornoe-proizvedenie.html#troyki"},{"k": "a", "a": "Определение — Правая и левая тройки, векторное произведение (4.4)", "b": "", "u": "lectures/04/vektornoe-proizvedenie.html#opred"},{"k": "a", "a": "Произведения ортов — Правая и левая тройки, векторное произведение (4.4)", "b": "", "u": "lectures/04/vektornoe-proizvedenie.html#orty"},{"k": "a", "a": "Свойства 1°–4° — Правая и левая тройки, векторное произведение (4.4)", "b": "", "u": "lectures/04/vektornoe-proizvedenie.html#svojstva"},{"k": "a", "a": "Частые ошибки — Правая и левая тройки, векторное произведение (4.4)", "b": "", "u": "lectures/04/vektornoe-proizvedenie.html#oshibki"},{"k": "a", "a": "Кратко — Правая и левая тройки, векторное произведение (4.4)", "b": "", "u": "lectures/04/vektornoe-proizvedenie.html#kratko"},{"k": "a", "a": "Проверь себя — Правая и левая тройки, векторное произведение (4.4)", "b": "", "u": "lectures/04/vektornoe-proizvedenie.html#proverka"},{"k": "a", "a": "4.5 Векторное произведение в координатах: площадь и коллинеарность (лекция 4)", "b": "Определение векторного произведения через три условия хорошо работает на чертеже, но в задачах векторы заданы координатами . Формула, которую мы выведем, — определитель с буквами i, j, k в первой строке — главный рабочий инструмент темы. По ней находят вектор, перпендикулярный двум данным, площадь параллелограмма и треугольника, проверяют, параллельны ли векторы. Координаты вектора по двум точкам ", "u": "lectures/04/vektornoe-v-koordinatah.html"},{"k": "a", "a": "Вектор по двум точкам — Векторное произведение в координатах: площадь и коллинеарность (4.5)", "b": "", "u": "lectures/04/vektornoe-v-koordinatah.html#tochki"},{"k": "a", "a": "Вывод формулы — Векторное произведение в координатах: площадь и коллинеарность (4.5)", "b": "", "u": "lectures/04/vektornoe-v-koordinatah.html#vyvod"},{"k": "a", "a": "Определитель с i, j, k — Векторное произведение в координатах: площадь и коллинеарность (4.5)", "b": "", "u": "lectures/04/vektornoe-v-koordinatah.html#opredelitel"},{"k": "a", "a": "Как считать — Векторное произведение в координатах: площадь и коллинеарность (4.5)", "b": "", "u": "lectures/04/vektornoe-v-koordinatah.html#algoritm"},{"k": "a", "a": "Площадь треугольника — Векторное произведение в координатах: площадь и коллинеарность (4.5)", "b": "", "u": "lectures/04/vektornoe-v-koordinatah.html#ploshad"},{"k": "a", "a": "Нормаль к плоскости — Векторное произведение в координатах: площадь и коллинеарность (4.5)", "b": "", "u": "lectures/04/vektornoe-v-koordinatah.html#normal"},{"k": "a", "a": "Коллинеарность — Векторное произведение в координатах: площадь и коллинеарность (4.5)", "b": "", "u": "lectures/04/vektornoe-v-koordinatah.html#kollin"},{"k": "a", "a": "Векторы на плоскости — Векторное произведение в координатах: площадь и коллинеарность (4.5)", "b": "", "u": "lectures/04/vektornoe-v-koordinatah.html#ploskost"},{"k": "a", "a": "Частые ошибки — Векторное произведение в координатах: площадь и коллинеарность (4.5)", "b": "", "u": "lectures/04/vektornoe-v-koordinatah.html#oshibki"},{"k": "a", "a": "Кратко — Векторное произведение в координатах: площадь и коллинеарность (4.5)", "b": "", "u": "lectures/04/vektornoe-v-koordinatah.html#kratko"},{"k": "a", "a": "Проверь себя — Векторное произведение в координатах: площадь и коллинеарность (4.5)", "b": "", "u": "lectures/04/vektornoe-v-koordinatah.html#proverka"},{"k": "a", "a": "4.6 Смешанное произведение: смысл и свойства (лекция 4)", "b": "Скалярное и векторное произведения можно объединить: сначала a × b (вектор), потом скалярно на третий вектор c . Получается число (a × b)·c , и оно оказывается «объёмом со знаком» параллелепипеда на этих трёх векторах. По его величине находят объём, по знаку — ориентацию тройки (правая или левая), а по равенству нулю — лежат ли векторы в одной плоскости. Определение Смешанное произведение Рассмотр", "u": "lectures/04/smeshannoe-proizvedenie.html"},{"k": "a", "a": "Определение — Смешанное произведение: смысл и свойства (4.6)", "b": "", "u": "lectures/04/smeshannoe-proizvedenie.html#opred"},{"k": "a", "a": "Геометрический смысл — Смешанное произведение: смысл и свойства (4.6)", "b": "", "u": "lectures/04/smeshannoe-proizvedenie.html#smysl"},{"k": "a", "a": "Свойства 1°–4° — Смешанное произведение: смысл и свойства (4.6)", "b": "", "u": "lectures/04/smeshannoe-proizvedenie.html#svojstva"},{"k": "a", "a": "Знак и ориентация — Смешанное произведение: смысл и свойства (4.6)", "b": "", "u": "lectures/04/smeshannoe-proizvedenie.html#orient"},{"k": "a", "a": "Компланарность — Смешанное произведение: смысл и свойства (4.6)", "b": "", "u": "lectures/04/smeshannoe-proizvedenie.html#komplan"},{"k": "a", "a": "Частые ошибки — Смешанное произведение: смысл и свойства (4.6)", "b": "", "u": "lectures/04/smeshannoe-proizvedenie.html#oshibki"},{"k": "a", "a": "Кратко — Смешанное произведение: смысл и свойства (4.6)", "b": "", "u": "lectures/04/smeshannoe-proizvedenie.html#kratko"},{"k": "a", "a": "Проверь себя — Смешанное произведение: смысл и свойства (4.6)", "b": "", "u": "lectures/04/smeshannoe-proizvedenie.html#proverka"},{"k": "a", "a": "4.7 Смешанное произведение в координатах: объём и компланарность (лекция 4)", "b": "В координатах смешанное произведение превращается в обычный определитель третьего порядка. Это даёт готовый способ находить объёмы параллелепипеда и пирамиды, определять ориентацию тройки и проверять, лежат ли векторы (или четыре точки) в одной плоскости. Статья опирается на формулу векторного произведения из статьи 4.5 и свойства определителей из лекции 1. Формула в координатах Пусть a = {a x , a", "u": "lectures/04/smeshannoe-v-koordinatah.html"},{"k": "a", "a": "Формула в координатах — Смешанное произведение в координатах: объём и компланарность (4.7)", "b": "", "u": "lectures/04/smeshannoe-v-koordinatah.html#formula"},{"k": "a", "a": "Свойства из определителя — Смешанное произведение в координатах: объём и компланарность (4.7)", "b": "", "u": "lectures/04/smeshannoe-v-koordinatah.html#svyaz"},{"k": "a", "a": "Объём параллелепипеда и пирамиды — Смешанное произведение в координатах: объём и компланарность (4.7)", "b": "", "u": "lectures/04/smeshannoe-v-koordinatah.html#obem"},{"k": "a", "a": "Пример из лекции — Смешанное произведение в координатах: объём и компланарность (4.7)", "b": "", "u": "lectures/04/smeshannoe-v-koordinatah.html#primer"},{"k": "a", "a": "Высота пирамиды — Смешанное произведение в координатах: объём и компланарность (4.7)", "b": "", "u": "lectures/04/smeshannoe-v-koordinatah.html#vysota"},{"k": "a", "a": "Компланарность — Смешанное произведение в координатах: объём и компланарность (4.7)", "b": "", "u": "lectures/04/smeshannoe-v-koordinatah.html#komplan"},{"k": "a", "a": "Частые ошибки — Смешанное произведение в координатах: объём и компланарность (4.7)", "b": "", "u": "lectures/04/smeshannoe-v-koordinatah.html#oshibki"},{"k": "a", "a": "Кратко — Смешанное произведение в координатах: объём и компланарность (4.7)", "b": "", "u": "lectures/04/smeshannoe-v-koordinatah.html#kratko"},{"k": "a", "a": "Проверь себя — Смешанное произведение в координатах: объём и компланарность (4.7)", "b": "", "u": "lectures/04/smeshannoe-v-koordinatah.html#proverka"},{"k": "a", "a": "4.8 Что чем считать: сводка по произведениям векторов (лекция 4)", "b": "К концу лекции накопились три похожих названия — скалярное, векторное и смешанное произведения — и с десяток формул. Типичный вопрос на практике и на экзамене: «что здесь надо считать?». Эта статья — карта. Сначала три произведения рядом, потом таблица «задача → формула» со ссылками на статьи, а в конце один сквозной пример: по четырём точкам из лекции находим длины, угол, площадь, объём, высоту и", "u": "lectures/04/chto-chem-schitat.html"},{"k": "a", "a": "Три произведения рядом — Что чем считать: сводка по произведениям векторов (4.8)", "b": "", "u": "lectures/04/chto-chem-schitat.html#tri"},{"k": "a", "a": "Как они связаны — Что чем считать: сводка по произведениям векторов (4.8)", "b": "", "u": "lectures/04/chto-chem-schitat.html#svyaz"},{"k": "a", "a": "Задача → что считать — Что чем считать: сводка по произведениям векторов (4.8)", "b": "", "u": "lectures/04/chto-chem-schitat.html#zadachi"},{"k": "a", "a": "Все характеристики пирамиды — Что чем считать: сводка по произведениям векторов (4.8)", "b": "", "u": "lectures/04/chto-chem-schitat.html#primer"},{"k": "a", "a": "Частые ошибки — Что чем считать: сводка по произведениям векторов (4.8)", "b": "", "u": "lectures/04/chto-chem-schitat.html#oshibki"},{"k": "a", "a": "Кратко — Что чем считать: сводка по произведениям векторов (4.8)", "b": "", "u": "lectures/04/chto-chem-schitat.html#kratko"},{"k": "a", "a": "Проверь себя — Что чем считать: сводка по произведениям векторов (4.8)", "b": "", "u": "lectures/04/chto-chem-schitat.html#proverka"},{"k": "a", "a": "4.9 Практикум: типовые задачи практики 6 (лекция 4)", "b": "Практика № 6 — краткая теория, десять образцов (пр. 1.1–1.10) и «тест»: задачи 1 (скалярное произведение, угол, проекция), 6 (векторное произведение, в том числе [a + b, 2a − b] ) и 9 (компланарность). Координатные формулы, угол, проекция, площадь, объём и компланарность разобраны в статьях 4.1–4.8. Здесь остальное: словарь обозначений, типы задач, которых в статьях не было, и четыре образца пособ", "u": "lectures/04/praktikum.html"},{"k": "a", "a": "Словарь практики — Практикум: типовые задачи практики 6 (4.9)", "b": "", "u": "lectures/04/praktikum.html#slovar"},{"k": "a", "a": "Выражения с a² (пр. 1.2) — Практикум: типовые задачи практики 6 (4.9)", "b": "", "u": "lectures/04/praktikum.html#kvadrat"},{"k": "a", "a": "Диагонали параллелограмма (пр. 1.3) — Практикум: типовые задачи практики 6 (4.9)", "b": "", "u": "lectures/04/praktikum.html#diagonali"},{"k": "a", "a": "Перпендикуляр с заданной z (пр. 1.4) — Практикум: типовые задачи практики 6 (4.9)", "b": "", "u": "lectures/04/praktikum.html#perp"},{"k": "a", "a": "Работа силы (пр. 1.5) — Практикум: типовые задачи практики 6 (4.9)", "b": "", "u": "lectures/04/praktikum.html#rabota"},{"k": "a", "a": "Комбинации в [·, ·] (пр. 1.6) — Практикум: типовые задачи практики 6 (4.9)", "b": "", "u": "lectures/04/praktikum.html#komb"},{"k": "a", "a": "Высота треугольника (пр. 1.7) — Практикум: типовые задачи практики 6 (4.9)", "b": "", "u": "lectures/04/praktikum.html#vysota"},{"k": "a", "a": "Момент силы (пр. 1.8) — Практикум: типовые задачи практики 6 (4.9)", "b": "", "u": "lectures/04/praktikum.html#moment"},{"k": "a", "a": "Как читать условия теста — Практикум: типовые задачи практики 6 (4.9)", "b": "", "u": "lectures/04/praktikum.html#test"},{"k": "a", "a": "Опечатки пособия — Практикум: типовые задачи практики 6 (4.9)", "b": "", "u": "lectures/04/praktikum.html#opechatki"},{"k": "a", "a": "Частые ошибки — Практикум: типовые задачи практики 6 (4.9)", "b": "", "u": "lectures/04/praktikum.html#oshibki"},{"k": "a", "a": "Кратко — Практикум: типовые задачи практики 6 (4.9)", "b": "", "u": "lectures/04/praktikum.html#kratko"},{"k": "a", "a": "Проверь себя — Практикум: типовые задачи практики 6 (4.9)", "b": "", "u": "lectures/04/praktikum.html#proverka"},{"k": "a", "a": "5.1 Отображения: основные понятия (лекция 5)", "b": "Линейное отображение — это отображение со специальным свойством, поэтому сначала нужен словарь самого слова «отображение»: образ и прообраз, инъекция, сюръекция, биекция, композиция, обратное. Этот словарь работает всю лекцию: инъективность проверяют через ядро, сюръективность — через образ, обратимость оператора — это биекция, а произведение матриц отвечает композиции отображений. Примеры здесь п", "u": "lectures/05/otobrazheniya.html"},{"k": "a", "a": "Отображение, образ и прообраз — Отображения: основные понятия (5.1)", "b": "", "u": "lectures/05/otobrazheniya.html#otobr"},{"k": "a", "a": "Инъекция, сюръекция, биекция — Отображения: основные понятия (5.1)", "b": "", "u": "lectures/05/otobrazheniya.html#tipy"},{"k": "a", "a": "Как это проверять — Отображения: основные понятия (5.1)", "b": "", "u": "lectures/05/otobrazheniya.html#kak"},{"k": "a", "a": "Композиция — Отображения: основные понятия (5.1)", "b": "", "u": "lectures/05/otobrazheniya.html#kompoz"},{"k": "a", "a": "Тождественное и обратное — Отображения: основные понятия (5.1)", "b": "", "u": "lectures/05/otobrazheniya.html#obratnoe"},{"k": "a", "a": "Частые ошибки — Отображения: основные понятия (5.1)", "b": "", "u": "lectures/05/otobrazheniya.html#oshibki"},{"k": "a", "a": "Кратко — Отображения: основные понятия (5.1)", "b": "", "u": "lectures/05/otobrazheniya.html#kratko"},{"k": "a", "a": "Проверь себя — Отображения: основные понятия (5.1)", "b": "", "u": "lectures/05/otobrazheniya.html#proverka"},{"k": "a", "a": "5.2 Линейное отображение: определение и примеры (лекция 5)", "b": "Линейное отображение — главный герой лекции: отображение, согласованное со сложением векторов и умножением на число. Именно такие отображения можно целиком описать матрицей (статья 5.4), и именно к ним применимы ядро, образ и теорема о размерностях. В статье — определение, быстрый способ проверить линейность и стандартные примеры, как линейные, так и нелинейные: такие задачи встречаются на любой п", "u": "lectures/05/linejnoe-otobrazhenie.html"},{"k": "a", "a": "Определение — Линейное отображение: определение и примеры (5.2)", "b": "", "u": "lectures/05/linejnoe-otobrazhenie.html#opred"},{"k": "a", "a": "Замечания 9.1 — Линейное отображение: определение и примеры (5.2)", "b": "", "u": "lectures/05/linejnoe-otobrazhenie.html#zam"},{"k": "a", "a": "Как проверить линейность — Линейное отображение: определение и примеры (5.2)", "b": "", "u": "lectures/05/linejnoe-otobrazhenie.html#kak"},{"k": "a", "a": "Примеры из лекции — Линейное отображение: определение и примеры (5.2)", "b": "", "u": "lectures/05/linejnoe-otobrazhenie.html#primery"},{"k": "a", "a": "Ещё примеры — Линейное отображение: определение и примеры (5.2)", "b": "", "u": "lectures/05/linejnoe-otobrazhenie.html#svoi"},{"k": "a", "a": "Частые ошибки — Линейное отображение: определение и примеры (5.2)", "b": "", "u": "lectures/05/linejnoe-otobrazhenie.html#oshibki"},{"k": "a", "a": "Кратко — Линейное отображение: определение и примеры (5.2)", "b": "", "u": "lectures/05/linejnoe-otobrazhenie.html#kratko"},{"k": "a", "a": "Проверь себя — Линейное отображение: определение и примеры (5.2)", "b": "", "u": "lectures/05/linejnoe-otobrazhenie.html#proverka"},{"k": "a", "a": "5.3 Свойства линейных отображений и операции над ними (лекция 5)", "b": "Линейное отображение «ведёт себя хорошо» по отношению к линейной зависимости, размерностям, композициям и обращению. Шесть свойств из лекции отвечают на вопросы вроде: может ли линейное отображение «склеить» независимые векторы? можно ли линейно отобразить ℝ² на ℝ³ ? обязана ли композиция линейных отображений быть линейной? Самое практичное — свойство 6: линейное отображение полностью определяется", "u": "lectures/05/svojstva-otobrazhenij.html"},{"k": "a", "a": "Свойство 1: зависимые → зависимые — Свойства линейных отображений и операции над ними (5.3)", "b": "", "u": "lectures/05/svojstva-otobrazhenij.html#s1"},{"k": "a", "a": "Свойство 2: прообразы независимых — Свойства линейных отображений и операции над ними (5.3)", "b": "", "u": "lectures/05/svojstva-otobrazhenij.html#s2"},{"k": "a", "a": "Свойство 3: размерности — Свойства линейных отображений и операции над ними (5.3)", "b": "", "u": "lectures/05/svojstva-otobrazhenij.html#s3"},{"k": "a", "a": "Свойства 4 и 5: композиция и обратное — Свойства линейных отображений и операции над ними (5.3)", "b": "", "u": "lectures/05/svojstva-otobrazhenij.html#s45"},{"k": "a", "a": "Свойство 6: образы базиса — Свойства линейных отображений и операции над ними (5.3)", "b": "", "u": "lectures/05/svojstva-otobrazhenij.html#s6"},{"k": "a", "a": "Сумма и умножение на число — Свойства линейных отображений и операции над ними (5.3)", "b": "", "u": "lectures/05/svojstva-otobrazhenij.html#oper"},{"k": "a", "a": "Частые ошибки — Свойства линейных отображений и операции над ними (5.3)", "b": "", "u": "lectures/05/svojstva-otobrazhenij.html#oshibki"},{"k": "a", "a": "Кратко — Свойства линейных отображений и операции над ними (5.3)", "b": "", "u": "lectures/05/svojstva-otobrazhenij.html#kratko"},{"k": "a", "a": "Проверь себя — Свойства линейных отображений и операции над ними (5.3)", "b": "", "u": "lectures/05/svojstva-otobrazhenij.html#proverka"},{"k": "a", "a": "5.4 Матрица линейного отображения (лекция 5)", "b": "Линейное отображение — абстрактный объект, а матрица — конкретная таблица чисел, с которой можно считать. Если зафиксировать базисы, то каждому линейному отображению отвечает ровно одна матрица, и наоборот. Образ вектора превращается в произведение матрицы на столбец, композиция отображений — в произведение матриц, обратное отображение — в обратную матрицу. Это главный мост от лекции 5 к матричной", "u": "lectures/05/matrica-otobrazheniya.html"},{"k": "a", "a": "Определение матрицы — Матрица линейного отображения (5.4)", "b": "", "u": "lectures/05/matrica-otobrazheniya.html#opred"},{"k": "a", "a": "Как построить матрицу — Матрица линейного отображения (5.4)", "b": "", "u": "lectures/05/matrica-otobrazheniya.html#alg"},{"k": "a", "a": "Формула w = Av — Матрица линейного отображения (5.4)", "b": "", "u": "lectures/05/matrica-otobrazheniya.html#wav"},{"k": "a", "a": "Матрицы примеров лекции — Матрица линейного отображения (5.4)", "b": "", "u": "lectures/05/matrica-otobrazheniya.html#primery"},{"k": "a", "a": "Свойства матриц отображений — Матрица линейного отображения (5.4)", "b": "", "u": "lectures/05/matrica-otobrazheniya.html#svojstva"},{"k": "a", "a": "Примеры в других базисах — Матрица линейного отображения (5.4)", "b": "", "u": "lectures/05/matrica-otobrazheniya.html#svoi"},{"k": "a", "a": "Частые ошибки — Матрица линейного отображения (5.4)", "b": "", "u": "lectures/05/matrica-otobrazheniya.html#oshibki"},{"k": "a", "a": "Кратко — Матрица линейного отображения (5.4)", "b": "", "u": "lectures/05/matrica-otobrazheniya.html#kratko"},{"k": "a", "a": "Проверь себя — Матрица линейного отображения (5.4)", "b": "", "u": "lectures/05/matrica-otobrazheniya.html#proverka"},{"k": "a", "a": "5.5 Ядро и образ линейного отображения (лекция 5)", "b": "У линейного отображения два главных «следа»: что оно убивает (ядро) и что оно достигает (образ). Ядро показывает, насколько отображение склеивает векторы, образ — какую часть пространства W оно покрывает. Через эти два множества проверяют инъективность и сюръективность, а размерности ядра и образа связаны красивой теоремой (статья 5.6). В статье — определения, примеры лекции, критерии и практическ", "u": "lectures/05/yadro-obraz.html"},{"k": "a", "a": "Определения — Ядро и образ линейного отображения (5.5)", "b": "", "u": "lectures/05/yadro-obraz.html#opred"},{"k": "a", "a": "Примеры из лекции — Ядро и образ линейного отображения (5.5)", "b": "", "u": "lectures/05/yadro-obraz.html#primery"},{"k": "a", "a": "Ядро и образ — подпространства — Ядро и образ линейного отображения (5.5)", "b": "", "u": "lectures/05/yadro-obraz.html#podpr"},{"k": "a", "a": "Ранг отображения и ранг матрицы — Ядро и образ линейного отображения (5.5)", "b": "", "u": "lectures/05/yadro-obraz.html#rang"},{"k": "a", "a": "Критерии инъективности и сюръективности — Ядро и образ линейного отображения (5.5)", "b": "", "u": "lectures/05/yadro-obraz.html#kriterii"},{"k": "a", "a": "Как найти ядро и образ — Ядро и образ линейного отображения (5.5)", "b": "", "u": "lectures/05/yadro-obraz.html#kak"},{"k": "a", "a": "Частые ошибки — Ядро и образ линейного отображения (5.5)", "b": "", "u": "lectures/05/yadro-obraz.html#oshibki"},{"k": "a", "a": "Кратко — Ядро и образ линейного отображения (5.5)", "b": "", "u": "lectures/05/yadro-obraz.html#kratko"},{"k": "a", "a": "Проверь себя — Ядро и образ линейного отображения (5.5)", "b": "", "u": "lectures/05/yadro-obraz.html#proverka"},{"k": "a", "a": "5.6 Теорема о размерностях ядра и образа (лекция 5)", "b": "Ядро и образ — подпространства разных пространств, но их размерности связаны простой формулой: «сколько отображение гасит» плюс «сколько оно сохраняет» равно размерности исходного пространства. Это теорема 9.1, одна из главных в лекции. Из неё следует, когда отображение может быть инъективным или сюръективным, зачем у обратимого отображения квадратная матрица, и почему число свободных неизвестных ", "u": "lectures/05/teorema-razmernostej.html"},{"k": "a", "a": "Теорема 9.1 — Теорема о размерностях ядра и образа (5.6)", "b": "", "u": "lectures/05/teorema-razmernostej.html#teorema"},{"k": "a", "a": "Доказательство по шагам — Теорема о размерностях ядра и образа (5.6)", "b": "", "u": "lectures/05/teorema-razmernostej.html#dokaz"},{"k": "a", "a": "Доказательство на числах — Теорема о размерностях ядра и образа (5.6)", "b": "", "u": "lectures/05/teorema-razmernostej.html#chislo"},{"k": "a", "a": "Что из неё следует — Теорема о размерностях ядра и образа (5.6)", "b": "", "u": "lectures/05/teorema-razmernostej.html#sledstviya"},{"k": "a", "a": "Следствие лекции: обратимость — Теорема о размерностях ядра и образа (5.6)", "b": "", "u": "lectures/05/teorema-razmernostej.html#obratimost"},{"k": "a", "a": "Примеры — Теорема о размерностях ядра и образа (5.6)", "b": "", "u": "lectures/05/teorema-razmernostej.html#primery"},{"k": "a", "a": "Частые ошибки — Теорема о размерностях ядра и образа (5.6)", "b": "", "u": "lectures/05/teorema-razmernostej.html#oshibki"},{"k": "a", "a": "Кратко — Теорема о размерностях ядра и образа (5.6)", "b": "", "u": "lectures/05/teorema-razmernostej.html#kratko"},{"k": "a", "a": "Проверь себя — Теорема о размерностях ядра и образа (5.6)", "b": "", "u": "lectures/05/teorema-razmernostej.html#proverka"},{"k": "a", "a": "5.7 Линейные преобразования (операторы) и их примеры (лекция 5)", "b": "Линейное преобразование (оператор) — это линейное отображение пространства в себя : 𝒜: V → V . Растяжение, поворот, симметрия, проекция на плоскость, дифференцирование многочленов — всё это операторы. Раз начало и конец совпадают, матрицу оператора принято строить в одном базисе (для прообразов и образов): она квадратная , и появляются новые вопросы (обратим ли оператор, как меняется матрица при с", "u": "lectures/05/operatory.html"},{"k": "a", "a": "Определение оператора — Линейные преобразования (операторы) и их примеры (5.7)", "b": "", "u": "lectures/05/operatory.html#opred"},{"k": "a", "a": "Простейшие операторы — Линейные преобразования (операторы) и их примеры (5.7)", "b": "", "u": "lectures/05/operatory.html#prostye"},{"k": "a", "a": "Поворот — Линейные преобразования (операторы) и их примеры (5.7)", "b": "", "u": "lectures/05/operatory.html#povorot"},{"k": "a", "a": "Дифференцирование — Линейные преобразования (операторы) и их примеры (5.7)", "b": "", "u": "lectures/05/operatory.html#diff"},{"k": "a", "a": "Проекция и отражение — Линейные преобразования (операторы) и их примеры (5.7)", "b": "", "u": "lectures/05/operatory.html#proekciya"},{"k": "a", "a": "Сводная таблица — Линейные преобразования (операторы) и их примеры (5.7)", "b": "", "u": "lectures/05/operatory.html#tablica"},{"k": "a", "a": "Свойства и приём исследования — Линейные преобразования (операторы) и их примеры (5.7)", "b": "", "u": "lectures/05/operatory.html#svojstva"},{"k": "a", "a": "Частые ошибки — Линейные преобразования (операторы) и их примеры (5.7)", "b": "", "u": "lectures/05/operatory.html#oshibki"},{"k": "a", "a": "Кратко — Линейные преобразования (операторы) и их примеры (5.7)", "b": "", "u": "lectures/05/operatory.html#kratko"},{"k": "a", "a": "Проверь себя — Линейные преобразования (операторы) и их примеры (5.7)", "b": "", "u": "lectures/05/operatory.html#proverka"},{"k": "a", "a": "5.8 Матрица оператора в разных базисах (лекция 5)", "b": "Матрица оператора зависит от выбранного базиса: один и тот же оператор в разных базисах записывается разными таблицами чисел. Как эти таблицы связаны? Ответ даёт формула (9.4): матрица в новом базисе получается из матрицы в старом сопряжением матрицей перехода, A (f) = S⁻¹ A (e) S . Это главный вычислительный результат конца лекции: он нужен для задач «найти матрицу оператора в новом базисе». В ле", "u": "lectures/05/smena-bazisa.html"},{"k": "a", "a": "Напоминание: матрица перехода — Матрица оператора в разных базисах (5.8)", "b": "", "u": "lectures/05/smena-bazisa.html#perehod"},{"k": "a", "a": "Формула (9.4) и её вывод — Матрица оператора в разных базисах (5.8)", "b": "", "u": "lectures/05/smena-bazisa.html#formula"},{"k": "a", "a": "Числовой пример — Матрица оператора в разных базисах (5.8)", "b": "", "u": "lectures/05/smena-bazisa.html#primer"},{"k": "a", "a": "Подобные матрицы — Матрица оператора в разных базисах (5.8)", "b": "", "u": "lectures/05/smena-bazisa.html#podobie"},{"k": "a", "a": "Зачем менять базис — Матрица оператора в разных базисах (5.8)", "b": "", "u": "lectures/05/smena-bazisa.html#zachem"},{"k": "a", "a": "Частые ошибки — Матрица оператора в разных базисах (5.8)", "b": "", "u": "lectures/05/smena-bazisa.html#oshibki"},{"k": "a", "a": "Кратко — Матрица оператора в разных базисах (5.8)", "b": "", "u": "lectures/05/smena-bazisa.html#kratko"},{"k": "a", "a": "Проверь себя — Матрица оператора в разных базисах (5.8)", "b": "", "u": "lectures/05/smena-bazisa.html#proverka"},{"k": "a", "a": "5.9 Собственные числа и собственные векторы (лекция 5)", "b": "У оператора бывают направления, которые он не «ломает», а лишь растягивает или сжимает. Вектор, остающийся на своей прямой, называют собственным , а коэффициент растяжения — собственным числом . Эти понятия нужны для задания 14 практики № 7 (30 вариантов) и отвечают на вопрос статьи 5.8: как выбрать базис, в котором матрица оператора диагональна. В лекции 5 этой темы нет, поэтому статья строится с", "u": "lectures/05/sobstvennye-chisla.html"},{"k": "a", "a": "Определение и смысл — Собственные числа и собственные векторы (5.9)", "b": "", "u": "lectures/05/sobstvennye-chisla.html#opred"},{"k": "a", "a": "Характеристическое уравнение — Собственные числа и собственные векторы (5.9)", "b": "", "u": "lectures/05/sobstvennye-chisla.html#harakt"},{"k": "a", "a": "Матрица 2×2 — Собственные числа и собственные векторы (5.9)", "b": "", "u": "lectures/05/sobstvennye-chisla.html#dva"},{"k": "a", "a": "Матрица 3×3 — Собственные числа и собственные векторы (5.9)", "b": "", "u": "lectures/05/sobstvennye-chisla.html#tri"},{"k": "a", "a": "Кратные корни — Собственные числа и собственные векторы (5.9)", "b": "", "u": "lectures/05/sobstvennye-chisla.html#kratn"},{"k": "a", "a": "Диагональный вид и подобие — Собственные числа и собственные векторы (5.9)", "b": "", "u": "lectures/05/sobstvennye-chisla.html#podobie"},{"k": "a", "a": "Симметрические операторы — Собственные числа и собственные векторы (5.9)", "b": "", "u": "lectures/05/sobstvennye-chisla.html#simm"},{"k": "a", "a": "Как проверить ответ — Собственные числа и собственные векторы (5.9)", "b": "", "u": "lectures/05/sobstvennye-chisla.html#proverka_o"},{"k": "a", "a": "Частые ошибки — Собственные числа и собственные векторы (5.9)", "b": "", "u": "lectures/05/sobstvennye-chisla.html#oshibki"},{"k": "a", "a": "Кратко — Собственные числа и собственные векторы (5.9)", "b": "", "u": "lectures/05/sobstvennye-chisla.html#kratko"},{"k": "a", "a": "Проверь себя — Собственные числа и собственные векторы (5.9)", "b": "", "u": "lectures/05/sobstvennye-chisla.html#proverka"},{"k": "a", "a": "5.10 Практикум: типовые задачи практики 7 (лекция 5)", "b": "Статьи 5.1–5.9 дают теорию, а практика № 7 просит три вещи: матрицу оператора в новом базисе (задание 12), геометрические операторы в ℝ³ (задание 13) и собственные числа (задание 14, статья 5.9). В статьях нет примеров 3×3 для заданий 12 и 13, а обозначения практики местами расходятся со статьями и содержат опечатки. Здесь: карта практики, словарь, разбор заданий 12 и 13, опечатки, контрольные зад", "u": "lectures/05/praktikum.html"},{"k": "a", "a": "Карта практики — Практикум: типовые задачи практики 7 (5.10)", "b": "", "u": "lectures/05/praktikum.html#karta"},{"k": "a", "a": "Словарь практики — Практикум: типовые задачи практики 7 (5.10)", "b": "", "u": "lectures/05/praktikum.html#slovar"},{"k": "a", "a": "Линейность и матрица в ℝ³ — Практикум: типовые задачи практики 7 (5.10)", "b": "", "u": "lectures/05/praktikum.html#lin"},{"k": "a", "a": "Задание 13: проекции, отражения, повороты — Практикум: типовые задачи практики 7 (5.10)", "b": "", "u": "lectures/05/praktikum.html#geom"},{"k": "a", "a": "Задание 12: матрица в новом базисе — Практикум: типовые задачи практики 7 (5.10)", "b": "", "u": "lectures/05/praktikum.html#bazis"},{"k": "a", "a": "Опечатки пособия — Практикум: типовые задачи практики 7 (5.10)", "b": "", "u": "lectures/05/praktikum.html#opechatki"},{"k": "a", "a": "Частые ошибки — Практикум: типовые задачи практики 7 (5.10)", "b": "", "u": "lectures/05/praktikum.html#oshibki"},{"k": "a", "a": "Кратко — Практикум: типовые задачи практики 7 (5.10)", "b": "", "u": "lectures/05/praktikum.html#kratko"},{"k": "a", "a": "Проверь себя — Практикум: типовые задачи практики 7 (5.10)", "b": "", "u": "lectures/05/praktikum.html#proverka"},{"k": "a", "a": "6.1 Логика: высказывания, импликация, кванторы (лекция 6)", "b": "Математика записана почти как язык программирования: в ней нет «пожалуй» и «обычно», любое утверждение либо верно, либо неверно. Здесь собран минимум логики, без которого не читаются определения и теоремы анализа: что такое импликация и чем «необходимо» отличается от «достаточно», как устроена алгебра высказываний и как строить отрицание утверждения с кванторами. Последнее важнее всего. Определени", "u": "lectures/06/logika-kvantory.html"},{"k": "a", "a": "Высказывания и операции — Логика: высказывания, импликация, кванторы (6.1)", "b": "", "u": "lectures/06/logika-kvantory.html#vyskaz"},{"k": "a", "a": "Импликация, теорема, необходимо и достаточно — Логика: высказывания, импликация, кванторы (6.1)", "b": "", "u": "lectures/06/logika-kvantory.html#impl"},{"k": "a", "a": "Алгебра высказываний — Логика: высказывания, импликация, кванторы (6.1)", "b": "", "u": "lectures/06/logika-kvantory.html#algebra"},{"k": "a", "a": "Обратная теорема и контрапозиция — Логика: высказывания, импликация, кванторы (6.1)", "b": "", "u": "lectures/06/logika-kvantory.html#kontra"},{"k": "a", "a": "Предикаты и кванторы — Логика: высказывания, импликация, кванторы (6.1)", "b": "", "u": "lectures/06/logika-kvantory.html#predikaty"},{"k": "a", "a": "Отрицание с кванторами — Логика: высказывания, импликация, кванторы (6.1)", "b": "", "u": "lectures/06/logika-kvantory.html#otric"},{"k": "a", "a": "Частые ошибки — Логика: высказывания, импликация, кванторы (6.1)", "b": "", "u": "lectures/06/logika-kvantory.html#oshibki"},{"k": "a", "a": "Кратко — Логика: высказывания, импликация, кванторы (6.1)", "b": "", "u": "lectures/06/logika-kvantory.html#kratko"},{"k": "a", "a": "Проверь себя — Логика: высказывания, импликация, кванторы (6.1)", "b": "", "u": "lectures/06/logika-kvantory.html#proverka"},{"k": "a", "a": "6.2 Множества, декартово произведение и метод индукции (лекция 6)", "b": "Множества — язык, на котором в анализе записывают области определения функций, окрестности точек, решения неравенств. Метод математической индукции — способ доказать утверждение сразу для всех натуральных n . В статье: основные понятия теории множеств, операции ∩ , ∪ , дополнение, разность и диаграммы Эйлера–Венна, декартово произведение (оттуда берутся плоскость ℝ² и пространство ℝ³ ), доказатель", "u": "lectures/06/mnozhestva-indukciya.html"},{"k": "a", "a": "Множество и подмножество — Множества, декартово произведение и метод индукции (6.2)", "b": "", "u": "lectures/06/mnozhestva-indukciya.html#osnovy"},{"k": "a", "a": "Операции над множествами — Множества, декартово произведение и метод индукции (6.2)", "b": "", "u": "lectures/06/mnozhestva-indukciya.html#operacii"},{"k": "a", "a": "Декартово произведение — Множества, декартово произведение и метод индукции (6.2)", "b": "", "u": "lectures/06/mnozhestva-indukciya.html#product"},{"k": "a", "a": "Как доказывать равенство множеств — Множества, декартово произведение и метод индукции (6.2)", "b": "", "u": "lectures/06/mnozhestva-indukciya.html#dokaz"},{"k": "a", "a": "Метод индукции — Множества, декартово произведение и метод индукции (6.2)", "b": "", "u": "lectures/06/mnozhestva-indukciya.html#indukciya"},{"k": "a", "a": "Неравенство Бернулли — Множества, декартово произведение и метод индукции (6.2)", "b": "", "u": "lectures/06/mnozhestva-indukciya.html#bernulli"},{"k": "a", "a": "Частые ошибки — Множества, декартово произведение и метод индукции (6.2)", "b": "", "u": "lectures/06/mnozhestva-indukciya.html#oshibki"},{"k": "a", "a": "Кратко — Множества, декартово произведение и метод индукции (6.2)", "b": "", "u": "lectures/06/mnozhestva-indukciya.html#kratko"},{"k": "a", "a": "Проверь себя — Множества, декартово произведение и метод индукции (6.2)", "b": "", "u": "lectures/06/mnozhestva-indukciya.html#proverka"},{"k": "a", "a": "6.3 Предел последовательности по определению (лекция 6)", "b": "Предел последовательности — первый «настоящий» объект анализа: точная формулировка слов « x n приближается к a , когда n велико». Определение записано кванторами ∀ε ∃N ∀n , и главный навык статьи — читать его как игру: противник называет сколь угодно малое ε , а ты в ответ находишь номер N , после которого все члены попадают в ε -окрестность. Здесь же собраны сведения о последовательностях, которы", "u": "lectures/06/predel-posledovatelnosti.html"},{"k": "a", "a": "Последовательность — Предел последовательности по определению (6.3)", "b": "", "u": "lectures/06/predel-posledovatelnosti.html#posl"},{"k": "a", "a": "Ограниченность и монотонность — Предел последовательности по определению (6.3)", "b": "", "u": "lectures/06/predel-posledovatelnosti.html#svoistva"},{"k": "a", "a": "Определение предела — Предел последовательности по определению (6.3)", "b": "", "u": "lectures/06/predel-posledovatelnosti.html#opred"},{"k": "a", "a": "Как найти N(ε) — Предел последовательности по определению (6.3)", "b": "", "u": "lectures/06/predel-posledovatelnosti.html#kak"},{"k": "a", "a": "Разобранные примеры — Предел последовательности по определению (6.3)", "b": "", "u": "lectures/06/predel-posledovatelnosti.html#primery"},{"k": "a", "a": "Когда предела нет — Предел последовательности по определению (6.3)", "b": "", "u": "lectures/06/predel-posledovatelnosti.html#net"},{"k": "a", "a": "Частые ошибки — Предел последовательности по определению (6.3)", "b": "", "u": "lectures/06/predel-posledovatelnosti.html#oshibki"},{"k": "a", "a": "Кратко — Предел последовательности по определению (6.3)", "b": "", "u": "lectures/06/predel-posledovatelnosti.html#kratko"},{"k": "a", "a": "Проверь себя — Предел последовательности по определению (6.3)", "b": "", "u": "lectures/06/predel-posledovatelnosti.html#proverka"},{"k": "a", "a": "6.4 Свойства сходящихся последовательностей (лекция 6)", "b": "Определение по ε–N — это способ проверить предел, но считать пределы по нему никто не будет. Считают с помощью свойств: предел единственный, сходящаяся последовательность ограничена, пределы можно складывать, умножать и делить, а «зажатую» последовательность вычисляют по её соседям. Все эти свойства доказываются из определения, и доказательства из лекции стоит разобрать: в них видны приёмы ( ε/2 ,", "u": "lectures/06/svojstva-skhodyashchikhsya.html"},{"k": "a", "a": "Единственность предела — Свойства сходящихся последовательностей (6.4)", "b": "", "u": "lectures/06/svojstva-skhodyashchikhsya.html#edin"},{"k": "a", "a": "Ограниченность — Свойства сходящихся последовательностей (6.4)", "b": "", "u": "lectures/06/svojstva-skhodyashchikhsya.html#ogr"},{"k": "a", "a": "Теорема о двух милиционерах — Свойства сходящихся последовательностей (6.4)", "b": "", "u": "lectures/06/svojstva-skhodyashchikhsya.html#zazh"},{"k": "a", "a": "Арифметика пределов — Свойства сходящихся последовательностей (6.4)", "b": "", "u": "lectures/06/svojstva-skhodyashchikhsya.html#arif"},{"k": "a", "a": "Неравенства и пределы — Свойства сходящихся последовательностей (6.4)", "b": "", "u": "lectures/06/svojstva-skhodyashchikhsya.html#neravenstva"},{"k": "a", "a": "Частые ошибки — Свойства сходящихся последовательностей (6.4)", "b": "", "u": "lectures/06/svojstva-skhodyashchikhsya.html#oshibki"},{"k": "a", "a": "Кратко — Свойства сходящихся последовательностей (6.4)", "b": "", "u": "lectures/06/svojstva-skhodyashchikhsya.html#kratko"},{"k": "a", "a": "Проверь себя — Свойства сходящихся последовательностей (6.4)", "b": "", "u": "lectures/06/svojstva-skhodyashchikhsya.html#proverka"},{"k": "a", "a": "6.5 Бесконечно малые, бесконечно большие и вычисление пределов последовательностей (лекция 6)", "b": "Свойства из статьи 6.4 позволяют считать пределы, если выражение уже разложено на простые сходящиеся части. Но на практике дроби вида (2n³ − 3n + 1)/(3n³ + 7) или разности корней √(n² + 5n) − n сначала нужно преобразовать. Две идеи делают это почти механическим: бесконечно малые ( 1/n , 1/n² и всё, что к ним сводится) и деление на старшую степень . В статье доказываются свойства бесконечно малых и", "u": "lectures/06/bm-bb-vychislenie.html"},{"k": "a", "a": "Бесконечно малые — Бесконечно малые, бесконечно большие и вычисление пределов последовательностей (6.5)", "b": "", "u": "lectures/06/bm-bb-vychislenie.html#bm"},{"k": "a", "a": "Бесконечно большие — Бесконечно малые, бесконечно большие и вычисление пределов последовательностей (6.5)", "b": "", "u": "lectures/06/bm-bb-vychislenie.html#bb"},{"k": "a", "a": "Неопределённости — Бесконечно малые, бесконечно большие и вычисление пределов последовательностей (6.5)", "b": "", "u": "lectures/06/bm-bb-vychislenie.html#neopr"},{"k": "a", "a": "Дробь из многочленов — Бесконечно малые, бесконечно большие и вычисление пределов последовательностей (6.5)", "b": "", "u": "lectures/06/bm-bb-vychislenie.html#ratsional"},{"k": "a", "a": "Корни: сравниваем степени роста — Бесконечно малые, бесконечно большие и вычисление пределов последовательностей (6.5)", "b": "", "u": "lectures/06/bm-bb-vychislenie.html#irrat"},{"k": "a", "a": "Разность корней: сопряжённое — Бесконечно малые, бесконечно большие и вычисление пределов последовательностей (6.5)", "b": "", "u": "lectures/06/bm-bb-vychislenie.html#sopr"},{"k": "a", "a": "Частые ошибки — Бесконечно малые, бесконечно большие и вычисление пределов последовательностей (6.5)", "b": "", "u": "lectures/06/bm-bb-vychislenie.html#oshibki"},{"k": "a", "a": "Кратко — Бесконечно малые, бесконечно большие и вычисление пределов последовательностей (6.5)", "b": "", "u": "lectures/06/bm-bb-vychislenie.html#kratko"},{"k": "a", "a": "Проверь себя — Бесконечно малые, бесконечно большие и вычисление пределов последовательностей (6.5)", "b": "", "u": "lectures/06/bm-bb-vychislenie.html#proverka"},{"k": "a", "a": "6.6 Монотонные последовательности, число e и теорема Больцано–Вейерштрасса (лекция 6)", "b": "До сих пор, чтобы доказать, что предел существует, надо было знать его значение. Теоремы этой статьи работают иначе: они гарантируют существование предела по общему виду последовательности (монотонная и ограниченная) и позволяют «вычислить» его потом. Так определяется число e , которое станет основанием натуральных логарифмов. В конце — теорема Больцано–Вейерштрасса: у ограниченной последовательно", "u": "lectures/06/monotonnye-e.html"},{"k": "a", "a": "Монотонные последовательности — Монотонные последовательности, число e и теорема Больцано–Вейерштрасса (6.6)", "b": "", "u": "lectures/06/monotonnye-e.html#mon"},{"k": "a", "a": "Рекуррентные последовательности — Монотонные последовательности, число e и теорема Больцано–Вейерштрасса (6.6)", "b": "", "u": "lectures/06/monotonnye-e.html#rek"},{"k": "a", "a": "Число e — Монотонные последовательности, число e и теорема Больцано–Вейерштрасса (6.6)", "b": "", "u": "lectures/06/monotonnye-e.html#e"},{"k": "a", "a": "Пределы вида 1^∞ — Монотонные последовательности, число e и теорема Больцано–Вейерштрасса (6.6)", "b": "", "u": "lectures/06/monotonnye-e.html#odin"},{"k": "a", "a": "Подпоследовательности — Монотонные последовательности, число e и теорема Больцано–Вейерштрасса (6.6)", "b": "", "u": "lectures/06/monotonnye-e.html#podp"},{"k": "a", "a": "Больцано–Вейерштрасс — Монотонные последовательности, число e и теорема Больцано–Вейерштрасса (6.6)", "b": "", "u": "lectures/06/monotonnye-e.html#bv"},{"k": "a", "a": "Частые ошибки — Монотонные последовательности, число e и теорема Больцано–Вейерштрасса (6.6)", "b": "", "u": "lectures/06/monotonnye-e.html#oshibki"},{"k": "a", "a": "Кратко — Монотонные последовательности, число e и теорема Больцано–Вейерштрасса (6.6)", "b": "", "u": "lectures/06/monotonnye-e.html#kratko"},{"k": "a", "a": "Проверь себя — Монотонные последовательности, число e и теорема Больцано–Вейерштрасса (6.6)", "b": "", "u": "lectures/06/monotonnye-e.html#proverka"},{"k": "a", "a": "6.7 Предел функции: по Коши, по Гейне, односторонние и бесконечные пределы (лекция 6)", "b": "Предел функции — тот же образ, что и у последовательности («значения f(x) сколь угодно близки к A , когда x близко к x₀ »), но аргумент теперь меняется непрерывно, и появляются новые вопросы: с какой стороны приближаться, что делать, если функция в самой точке не определена, как говорить о бесконечных пределах и пределах на бесконечности. В статье: определение по Коши ( ε–δ ) из лекции, определени", "u": "lectures/06/predel-funkcii.html"},{"k": "a", "a": "Проколотая окрестность — Предел функции: по Коши, по Гейне, односторонние и бесконечные пределы (6.7)", "b": "", "u": "lectures/06/predel-funkcii.html#okr"},{"k": "a", "a": "Определение по Коши — Предел функции: по Коши, по Гейне, односторонние и бесконечные пределы (6.7)", "b": "", "u": "lectures/06/predel-funkcii.html#koshi"},{"k": "a", "a": "Как найти δ(ε) — Предел функции: по Коши, по Гейне, односторонние и бесконечные пределы (6.7)", "b": "", "u": "lectures/06/predel-funkcii.html#kak"},{"k": "a", "a": "Определение по Гейне — Предел функции: по Коши, по Гейне, односторонние и бесконечные пределы (6.7)", "b": "", "u": "lectures/06/predel-funkcii.html#gejne"},{"k": "a", "a": "Односторонние пределы — Предел функции: по Коши, по Гейне, односторонние и бесконечные пределы (6.7)", "b": "", "u": "lectures/06/predel-funkcii.html#odnostor"},{"k": "a", "a": "Бесконечные пределы — Предел функции: по Коши, по Гейне, односторонние и бесконечные пределы (6.7)", "b": "", "u": "lectures/06/predel-funkcii.html#besk"},{"k": "a", "a": "Пределы на бесконечности — Предел функции: по Коши, по Гейне, односторонние и бесконечные пределы (6.7)", "b": "", "u": "lectures/06/predel-funkcii.html#inf"},{"k": "a", "a": "Единственность — Предел функции: по Коши, по Гейне, односторонние и бесконечные пределы (6.7)", "b": "", "u": "lectures/06/predel-funkcii.html#edin"},{"k": "a", "a": "Частые ошибки — Предел функции: по Коши, по Гейне, односторонние и бесконечные пределы (6.7)", "b": "", "u": "lectures/06/predel-funkcii.html#oshibki"},{"k": "a", "a": "Кратко — Предел функции: по Коши, по Гейне, односторонние и бесконечные пределы (6.7)", "b": "", "u": "lectures/06/predel-funkcii.html#kratko"},{"k": "a", "a": "Проверь себя — Предел функции: по Коши, по Гейне, односторонние и бесконечные пределы (6.7)", "b": "", "u": "lectures/06/predel-funkcii.html#proverka"},{"k": "a", "a": "6.8 Теоремы о пределах функций (лекция 6)", "b": "Эта статья — «инструментальный ящик» для пределов функций. Теоремы 8.3–8.11 лекции повторяют то, что для последовательностей доказано в статье 6.4, но формулируются локально : утверждения верны не «везде», а в окрестности точки. Главная идея — основная теорема о бесконечно малых: функция, имеющая предел A , равна A плюс бесконечно малая. Через неё доказывается правило частного (теорема 8.8), и в э", "u": "lectures/06/teoremy-o-predelakh.html"},{"k": "a", "a": "Ограниченность (теоремы 8.3–8.4) — Теоремы о пределах функций (6.8)", "b": "", "u": "lectures/06/teoremy-o-predelakh.html#ogr"},{"k": "a", "a": "Бесконечно малые функции (8.5–8.7) — Теоремы о пределах функций (6.8)", "b": "", "u": "lectures/06/teoremy-o-predelakh.html#bm"},{"k": "a", "a": "Арифметика пределов (8.8) — Теоремы о пределах функций (6.8)", "b": "", "u": "lectures/06/teoremy-o-predelakh.html#arif"},{"k": "a", "a": "Неравенства (8.9–8.11) — Теоремы о пределах функций (6.8)", "b": "", "u": "lectures/06/teoremy-o-predelakh.html#neravenstva"},{"k": "a", "a": "Частые ошибки — Теоремы о пределах функций (6.8)", "b": "", "u": "lectures/06/teoremy-o-predelakh.html#oshibki"},{"k": "a", "a": "Кратко — Теоремы о пределах функций (6.8)", "b": "", "u": "lectures/06/teoremy-o-predelakh.html#kratko"},{"k": "a", "a": "Проверь себя — Теоремы о пределах функций (6.8)", "b": "", "u": "lectures/06/teoremy-o-predelakh.html#proverka"},{"k": "a", "a": "6.9 Замечательные пределы и эквивалентные бесконечно малые (лекция 6)", "b": "В лекции нет ни одного вычисленного предела функции, а на практике почти все задания — именно вычисления. Здесь закрывается главный пробел: два замечательных предела , из которых выводятся все остальные, и эквивалентные бесконечно малые — таблица замен, превращающая сложные дроби в простые. Практика № 9 (задачи 11–14) строится на этом, но часть задач требует ещё нескольких приёмов: они собраны в р", "u": "lectures/06/zamechatelnye-predely.html"},{"k": "a", "a": "Первый замечательный предел — Замечательные пределы и эквивалентные бесконечно малые (6.9)", "b": "", "u": "lectures/06/zamechatelnye-predely.html#first"},{"k": "a", "a": "Второй замечательный предел — Замечательные пределы и эквивалентные бесконечно малые (6.9)", "b": "", "u": "lectures/06/zamechatelnye-predely.html#second"},{"k": "a", "a": "Сравнение бесконечно малых — Замечательные пределы и эквивалентные бесконечно малые (6.9)", "b": "", "u": "lectures/06/zamechatelnye-predely.html#sravn"},{"k": "a", "a": "Таблица эквивалентных — Замечательные пределы и эквивалентные бесконечно малые (6.9)", "b": "", "u": "lectures/06/zamechatelnye-predely.html#tabl"},{"k": "a", "a": "Алгоритм и разбор типов практики — Замечательные пределы и эквивалентные бесконечно малые (6.9)", "b": "", "u": "lectures/06/zamechatelnye-predely.html#alg"},{"k": "a", "a": "Приёмы для задач 11–14 — Замечательные пределы и эквивалентные бесконечно малые (6.9)", "b": "", "u": "lectures/06/zamechatelnye-predely.html#priemy"},{"k": "a", "a": "Частые ошибки — Замечательные пределы и эквивалентные бесконечно малые (6.9)", "b": "", "u": "lectures/06/zamechatelnye-predely.html#oshibki"},{"k": "a", "a": "Кратко — Замечательные пределы и эквивалентные бесконечно малые (6.9)", "b": "", "u": "lectures/06/zamechatelnye-predely.html#kratko"},{"k": "a", "a": "Проверь себя — Замечательные пределы и эквивалентные бесконечно малые (6.9)", "b": "", "u": "lectures/06/zamechatelnye-predely.html#proverka"},{"k": "a", "a": "6.10 Раскрытие неопределённостей: 0/0, ∞/∞, ∞−∞, 1^∞ (лекция 6)", "b": "Подстановка числа в предел чаще всего даёт один из «странных» результатов: 0/0 , ∞/∞ , ∞ − ∞ , 0·∞ , 1^∞ . Каждый такой символ называется неопределённостью : ответ зависит от того, какие именно функции стоят в выражении, и его нужно найти, преобразовав выражение. В лекции этих методов нет; здесь они собраны по типам заданий практики № 9: дробь из многочленов (задание 1), иррациональности (задание ", "u": "lectures/06/neopredelennosti.html"},{"k": "a", "a": "Карта методов — Раскрытие неопределённостей: 0/0, ∞/∞, ∞−∞, 1^∞ (6.10)", "b": "", "u": "lectures/06/neopredelennosti.html#karta"},{"k": "a", "a": "0/0: дробь из многочленов — Раскрытие неопределённостей: 0/0, ∞/∞, ∞−∞, 1^∞ (6.10)", "b": "", "u": "lectures/06/neopredelennosti.html#nul"},{"k": "a", "a": "0/0 с корнями — Раскрытие неопределённостей: 0/0, ∞/∞, ∞−∞, 1^∞ (6.10)", "b": "", "u": "lectures/06/neopredelennosti.html#irr"},{"k": "a", "a": "∞/∞ при x → ∞ — Раскрытие неопределённостей: 0/0, ∞/∞, ∞−∞, 1^∞ (6.10)", "b": "", "u": "lectures/06/neopredelennosti.html#inf"},{"k": "a", "a": "∞ − ∞ и 0·∞ — Раскрытие неопределённостей: 0/0, ∞/∞, ∞−∞, 1^∞ (6.10)", "b": "", "u": "lectures/06/neopredelennosti.html#raznost"},{"k": "a", "a": "Степень 1^∞ — Раскрытие неопределённостей: 0/0, ∞/∞, ∞−∞, 1^∞ (6.10)", "b": "", "u": "lectures/06/neopredelennosti.html#edinitsa"},{"k": "a", "a": "Частые ошибки — Раскрытие неопределённостей: 0/0, ∞/∞, ∞−∞, 1^∞ (6.10)", "b": "", "u": "lectures/06/neopredelennosti.html#oshibki"},{"k": "a", "a": "Кратко — Раскрытие неопределённостей: 0/0, ∞/∞, ∞−∞, 1^∞ (6.10)", "b": "", "u": "lectures/06/neopredelennosti.html#kratko"},{"k": "a", "a": "Проверь себя — Раскрытие неопределённостей: 0/0, ∞/∞, ∞−∞, 1^∞ (6.10)", "b": "", "u": "lectures/06/neopredelennosti.html#proverka"},{"k": "a", "a": "7.1 Непрерывность в точке: определения (лекция 7)", "b": "Непрерывность — это математическая запись слов «без скачков»: малое изменение аргумента даёт малое изменение значения функции. С неё начинается всё остальное в лекции: точки разрыва, теоремы на отрезке, непрерывность элементарных функций. В статье — определение в пяти равносильных формах, три условия, которые нужно проверить, и приём «докажи по определению». Идея непрерывности Многие зависимости в", "u": "lectures/07/opredelenie.html"},{"k": "a", "a": "Идея непрерывности — Непрерывность в точке: определения (7.1)", "b": "", "u": "lectures/07/opredelenie.html#ideya"},{"k": "a", "a": "Определение через предел — Непрерывность в точке: определения (7.1)", "b": "", "u": "lectures/07/opredelenie.html#predel"},{"k": "a", "a": "Ещё три формы определения — Непрерывность в точке: определения (7.1)", "b": "", "u": "lectures/07/opredelenie.html#formy"},{"k": "a", "a": "Как доказать по определению — Непрерывность в точке: определения (7.1)", "b": "", "u": "lectures/07/opredelenie.html#dokaz"},{"k": "a", "a": "Как непрерывность нарушается — Непрерывность в точке: определения (7.1)", "b": "", "u": "lectures/07/opredelenie.html#narush"},{"k": "a", "a": "Частые ошибки — Непрерывность в точке: определения (7.1)", "b": "", "u": "lectures/07/opredelenie.html#oshibki"},{"k": "a", "a": "Кратко — Непрерывность в точке: определения (7.1)", "b": "", "u": "lectures/07/opredelenie.html#kratko"},{"k": "a", "a": "Проверь себя — Непрерывность в точке: определения (7.1)", "b": "", "u": "lectures/07/opredelenie.html#proverka"},{"k": "a", "a": "7.2 Односторонняя непрерывность и свойства в точке (лекция 7)", "b": "Непрерывность в точке можно проверять «по частям»: отдельно слева и отдельно справа. Это нужно для кусочных функций, у которых слева и справа от точки работают разные формулы, и для задач вида «при каком a функция непрерывна». Затем две теоремы в точке: если непрерывная функция положительна в точке, то она положительна и в некоторой окрестности этой точки; а суммы, произведения и частные непрерывн", "u": "lectures/07/odnostoronnyaya.html"},{"k": "a", "a": "Односторонняя непрерывность — Односторонняя непрерывность и свойства в точке (7.2)", "b": "", "u": "lectures/07/odnostoronnyaya.html#odnostor"},{"k": "a", "a": "Пример: целая часть — Односторонняя непрерывность и свойства в точке (7.2)", "b": "", "u": "lectures/07/odnostoronnyaya.html#celaya"},{"k": "a", "a": "Кусочная функция: подбор параметра — Односторонняя непрерывность и свойства в точке (7.2)", "b": "", "u": "lectures/07/odnostoronnyaya.html#shivka"},{"k": "a", "a": "Сохранение знака — Односторонняя непрерывность и свойства в точке (7.2)", "b": "", "u": "lectures/07/odnostoronnyaya.html#znak"},{"k": "a", "a": "Арифметика непрерывных функций — Односторонняя непрерывность и свойства в точке (7.2)", "b": "", "u": "lectures/07/odnostoronnyaya.html#arifm"},{"k": "a", "a": "Частые ошибки — Односторонняя непрерывность и свойства в точке (7.2)", "b": "", "u": "lectures/07/odnostoronnyaya.html#oshibki"},{"k": "a", "a": "Кратко — Односторонняя непрерывность и свойства в точке (7.2)", "b": "", "u": "lectures/07/odnostoronnyaya.html#kratko"},{"k": "a", "a": "Проверь себя — Односторонняя непрерывность и свойства в точке (7.2)", "b": "", "u": "lectures/07/odnostoronnyaya.html#proverka"},{"k": "a", "a": "7.3 Точки разрыва и их классификация (лекция 7)", "b": "Не всякая функция непрерывна: бывают точки, где ломается одно из трёх условий непрерывности. Такие точки называют точками разрыва и делят на классы. По классу сразу видно, что творится с функцией около точки и можно ли разрыв «залатать». В статье — определения лекции, четыре картинки, алгоритм и несколько разобранных примеров. Что такое точка разрыва Точка разрыва Пусть функция f определена на нек", "u": "lectures/07/tochki-razryva.html"},{"k": "a", "a": "Что такое точка разрыва — Точки разрыва и их классификация (7.3)", "b": "", "u": "lectures/07/tochki-razryva.html#opr"},{"k": "a", "a": "Первый и второй род — Точки разрыва и их классификация (7.3)", "b": "", "u": "lectures/07/tochki-razryva.html#rod"},{"k": "a", "a": "Четыре картинки — Точки разрыва и их классификация (7.3)", "b": "", "u": "lectures/07/tochki-razryva.html#kartinki"},{"k": "a", "a": "Алгоритм классификации — Точки разрыва и их классификация (7.3)", "b": "", "u": "lectures/07/tochki-razryva.html#alg"},{"k": "a", "a": "Устранимый разрыв можно залатать — Точки разрыва и их классификация (7.3)", "b": "", "u": "lectures/07/tochki-razryva.html#ustran"},{"k": "a", "a": "Ещё примеры — Точки разрыва и их классификация (7.3)", "b": "", "u": "lectures/07/tochki-razryva.html#primery"},{"k": "a", "a": "Частые ошибки — Точки разрыва и их классификация (7.3)", "b": "", "u": "lectures/07/tochki-razryva.html#oshibki"},{"k": "a", "a": "Кратко — Точки разрыва и их классификация (7.3)", "b": "", "u": "lectures/07/tochki-razryva.html#kratko"},{"k": "a", "a": "Проверь себя — Точки разрыва и их классификация (7.3)", "b": "", "u": "lectures/07/tochki-razryva.html#proverka"},{"k": "a", "a": "7.4 Исследование на непрерывность: типовые задачи (лекция 7)", "b": "Практика № 10 строится на задачах нескольких типов: найти точки разрыва и их род, найти скачок, доопределить функцию по непрерывности, подобрать параметр, выбрать функции с разрывом первого рода. Все они решаются по одному плану и одним набором предельных приёмов. Статья — рабочая тетрадь: план, справочник типовых пределов, разобранные примеры и раздел про показатели вида 1/(x² − a²) и x/(9 − x²) ", "u": "lectures/07/tipovye-zadachi.html"},{"k": "a", "a": "План исследования — Исследование на непрерывность: типовые задачи (7.4)", "b": "", "u": "lectures/07/tipovye-zadachi.html#plan"},{"k": "a", "a": "Справочник типовых пределов — Исследование на непрерывность: типовые задачи (7.4)", "b": "", "u": "lectures/07/tipovye-zadachi.html#spravochnik"},{"k": "a", "a": "Рациональная дробь — Исследование на непрерывность: типовые задачи (7.4)", "b": "", "u": "lectures/07/tipovye-zadachi.html#drob"},{"k": "a", "a": "Кусочная функция — Исследование на непрерывность: типовые задачи (7.4)", "b": "", "u": "lectures/07/tipovye-zadachi.html#kusoch"},{"k": "a", "a": "Показательная функция с 1/x — Исследование на непрерывность: типовые задачи (7.4)", "b": "", "u": "lectures/07/tipovye-zadachi.html#pokaz"},{"k": "a", "a": "Показатель посложнее: знаки по интервалам — Исследование на непрерывность: типовые задачи (7.4)", "b": "", "u": "lectures/07/tipovye-zadachi.html#pokaz2"},{"k": "a", "a": "Модуль и арктангенс — Исследование на непрерывность: типовые задачи (7.4)", "b": "", "u": "lectures/07/tipovye-zadachi.html#modul"},{"k": "a", "a": "Логарифм в знаменателе — Исследование на непрерывность: типовые задачи (7.4)", "b": "", "u": "lectures/07/tipovye-zadachi.html#logar"},{"k": "a", "a": "Доопределить по непрерывности — Исследование на непрерывность: типовые задачи (7.4)", "b": "", "u": "lectures/07/tipovye-zadachi.html#dopred"},{"k": "a", "a": "Частые ошибки — Исследование на непрерывность: типовые задачи (7.4)", "b": "", "u": "lectures/07/tipovye-zadachi.html#oshibki"},{"k": "a", "a": "Кратко — Исследование на непрерывность: типовые задачи (7.4)", "b": "", "u": "lectures/07/tipovye-zadachi.html#kratko"},{"k": "a", "a": "Проверь себя — Исследование на непрерывность: типовые задачи (7.4)", "b": "", "u": "lectures/07/tipovye-zadachi.html#proverka"},{"k": "a", "a": "7.5 Сложная функция и её непрерывность (лекция 7)", "b": "Большинство функций, с которыми приходится работать, — композиции вида sin³(x + 1) − 2 , ln(4 − x²) , √(x² + 1) . Теорема этой статьи отвечает, когда композиция непрерывна, и даёт главный вычислительный приём: предел можно проносить под знак непрерывной функции . Сложная функция Сложная функция (композиция) Пусть заданы функции f: X → Y и g: Y → Z . Каждому x ∈ X ставится в соответствие единственн", "u": "lectures/07/slozhnaya-funkciya.html"},{"k": "a", "a": "Сложная функция — Сложная функция и её непрерывность (7.5)", "b": "", "u": "lectures/07/slozhnaya-funkciya.html#kompoz"},{"k": "a", "a": "Лемма о композиции б.м.ф. — Сложная функция и её непрерывность (7.5)", "b": "", "u": "lectures/07/slozhnaya-funkciya.html#lemma"},{"k": "a", "a": "Теорема о непрерывности сложной функции — Сложная функция и её непрерывность (7.5)", "b": "", "u": "lectures/07/slozhnaya-funkciya.html#teorema"},{"k": "a", "a": "Предел под знаком функции — Сложная функция и её непрерывность (7.5)", "b": "", "u": "lectures/07/slozhnaya-funkciya.html#predel"},{"k": "a", "a": "Где непрерывна композиция — Сложная функция и её непрерывность (7.5)", "b": "", "u": "lectures/07/slozhnaya-funkciya.html#primery"},{"k": "a", "a": "Частые ошибки — Сложная функция и её непрерывность (7.5)", "b": "", "u": "lectures/07/slozhnaya-funkciya.html#oshibki"},{"k": "a", "a": "Кратко — Сложная функция и её непрерывность (7.5)", "b": "", "u": "lectures/07/slozhnaya-funkciya.html#kratko"},{"k": "a", "a": "Проверь себя — Сложная функция и её непрерывность (7.5)", "b": "", "u": "lectures/07/slozhnaya-funkciya.html#proverka"},{"k": "a", "a": "7.6 Непрерывность на промежутке и теорема Вейерштрасса (лекция 7)", "b": "До сих пор мы говорили о непрерывности в точке. Теперь поднимемся на уровень выше: функция непрерывна на промежутке , а у промежутка есть концы, и это меняет дело. Главный результат статьи — теорема Вейерштрасса: непрерывная на отрезке функция ограничена и достигает наибольшего и наименьшего значений. У теоремы три условия (непрерывность, замкнутость и ограниченность промежутка), и мы покажем, что", "u": "lectures/07/veyershtrass.html"},{"k": "a", "a": "Непрерывность на промежутке — Непрерывность на промежутке и теорема Вейерштрасса (7.6)", "b": "", "u": "lectures/07/veyershtrass.html#promezh"},{"k": "a", "a": "Теорема Вейерштрасса — Непрерывность на промежутке и теорема Вейерштрасса (7.6)", "b": "", "u": "lectures/07/veyershtrass.html#teorema"},{"k": "a", "a": "Идея доказательства — Непрерывность на промежутке и теорема Вейерштрасса (7.6)", "b": "", "u": "lectures/07/veyershtrass.html#dokaz"},{"k": "a", "a": "Зачем нужны условия — Непрерывность на промежутке и теорема Вейерштрасса (7.6)", "b": "", "u": "lectures/07/veyershtrass.html#usloviya"},{"k": "a", "a": "Как пользоваться — Непрерывность на промежутке и теорема Вейерштрасса (7.6)", "b": "", "u": "lectures/07/veyershtrass.html#primery"},{"k": "a", "a": "Частые ошибки — Непрерывность на промежутке и теорема Вейерштрасса (7.6)", "b": "", "u": "lectures/07/veyershtrass.html#oshibki"},{"k": "a", "a": "Кратко — Непрерывность на промежутке и теорема Вейерштрасса (7.6)", "b": "", "u": "lectures/07/veyershtrass.html#kratko"},{"k": "a", "a": "Проверь себя — Непрерывность на промежутке и теорема Вейерштрасса (7.6)", "b": "", "u": "lectures/07/veyershtrass.html#proverka"},{"k": "a", "a": "7.7 Теоремы о нуле и о промежуточных значениях (лекция 7)", "b": "График непрерывной функции нельзя нарисовать без «перехода» через каждое промежуточное значение: если в начале отрезка функция отрицательна, а в конце положительна, то где-то она обязана обратиться в нуль. Это теорема о нуле. Из неё выводится теорема Больцано–Коши: непрерывная функция принимает все промежуточные значения. На них держится доказательство того, что уравнение имеет корень, и ещё один ", "u": "lectures/07/nul-i-promezhutochnye.html"},{"k": "a", "a": "Теорема о нуле — Теоремы о нуле и о промежуточных значениях (7.7)", "b": "", "u": "lectures/07/nul-i-promezhutochnye.html#nul"},{"k": "a", "a": "Метод половинного деления — Теоремы о нуле и о промежуточных значениях (7.7)", "b": "", "u": "lectures/07/nul-i-promezhutochnye.html#polov"},{"k": "a", "a": "Теорема Больцано–Коши — Теоремы о нуле и о промежуточных значениях (7.7)", "b": "", "u": "lectures/07/nul-i-promezhutochnye.html#bk"},{"k": "a", "a": "Образ промежутка — Теоремы о нуле и о промежуточных значениях (7.7)", "b": "", "u": "lectures/07/nul-i-promezhutochnye.html#sled"},{"k": "a", "a": "Как доказывать существование корня — Теоремы о нуле и о промежуточных значениях (7.7)", "b": "", "u": "lectures/07/nul-i-promezhutochnye.html#primen"},{"k": "a", "a": "Частые ошибки — Теоремы о нуле и о промежуточных значениях (7.7)", "b": "", "u": "lectures/07/nul-i-promezhutochnye.html#oshibki"},{"k": "a", "a": "Кратко — Теоремы о нуле и о промежуточных значениях (7.7)", "b": "", "u": "lectures/07/nul-i-promezhutochnye.html#kratko"},{"k": "a", "a": "Проверь себя — Теоремы о нуле и о промежуточных значениях (7.7)", "b": "", "u": "lectures/07/nul-i-promezhutochnye.html#proverka"},{"k": "a", "a": "7.8 Обратная функция и непрерывность элементарных функций (лекция 7)", "b": "Последний шаг лекции отвечает на вопрос «а какие функции вообще непрерывны?». Оказывается, все, которые мы привыкли писать формулами (многочлены, дроби, степени, показательные, логарифмы, тригонометрические и их композиции), непрерывны во всех точках, где определены. Для этого нужны две вещи: теорема о непрерывности обратной функции (так получаются логарифм, корни и обратные тригонометрические) и ", "u": "lectures/07/obratnaya-i-elementarnye.html"},{"k": "a", "a": "Обратная функция — Обратная функция и непрерывность элементарных функций (7.8)", "b": "", "u": "lectures/07/obratnaya-i-elementarnye.html#obr"},{"k": "a", "a": "Теорема об обратной функции — Обратная функция и непрерывность элементарных функций (7.8)", "b": "", "u": "lectures/07/obratnaya-i-elementarnye.html#teor"},{"k": "a", "a": "Корень n-й степени — Обратная функция и непрерывность элементарных функций (7.8)", "b": "", "u": "lectures/07/obratnaya-i-elementarnye.html#koren"},{"k": "a", "a": "Основные элементарные функции — Обратная функция и непрерывность элементарных функций (7.8)", "b": "", "u": "lectures/07/obratnaya-i-elementarnye.html#osnovnye"},{"k": "a", "a": "Как доказывается непрерывность — Обратная функция и непрерывность элементарных функций (7.8)", "b": "", "u": "lectures/07/obratnaya-i-elementarnye.html#dokaz"},{"k": "a", "a": "Элементарные функции — Обратная функция и непрерывность элементарных функций (7.8)", "b": "", "u": "lectures/07/obratnaya-i-elementarnye.html#elem"},{"k": "a", "a": "Предел подстановкой — Обратная функция и непрерывность элементарных функций (7.8)", "b": "", "u": "lectures/07/obratnaya-i-elementarnye.html#predel"},{"k": "a", "a": "Частые ошибки — Обратная функция и непрерывность элементарных функций (7.8)", "b": "", "u": "lectures/07/obratnaya-i-elementarnye.html#oshibki"},{"k": "a", "a": "Кратко — Обратная функция и непрерывность элементарных функций (7.8)", "b": "", "u": "lectures/07/obratnaya-i-elementarnye.html#kratko"},{"k": "a", "a": "Проверь себя — Обратная функция и непрерывность элементарных функций (7.8)", "b": "", "u": "lectures/07/obratnaya-i-elementarnye.html#proverka"},{"k": "a", "a": "8.1 Производная в точке: определение и вычисление по определению (лекция 8)", "b": "Производная — главное понятие этой лекции: на ней держатся касательная, скорость, дифференциал и почти всё, что вы будете делать дальше (исследование функций, интегралы). Определяют её через предел: сначала смотрят, на сколько изменилась функция при небольшом сдвиге аргумента, а потом сдвиг «гасят». Считать по определению приходится редко, но без него непонятны ни таблица производных, ни слова «ди", "u": "lectures/08/proizvodnaya-v-tochke.html"},{"k": "a", "a": "Приращения — Производная в точке: определение и вычисление по определению (8.1)", "b": "", "u": "lectures/08/proizvodnaya-v-tochke.html#prirashchenie"},{"k": "a", "a": "Определение производной — Производная в точке: определение и вычисление по определению (8.1)", "b": "", "u": "lectures/08/proizvodnaya-v-tochke.html#opredelenie"},{"k": "a", "a": "Как вычислить по определению — Производная в точке: определение и вычисление по определению (8.1)", "b": "", "u": "lectures/08/proizvodnaya-v-tochke.html#alg"},{"k": "a", "a": "Примеры лекции — Производная в точке: определение и вычисление по определению (8.1)", "b": "", "u": "lectures/08/proizvodnaya-v-tochke.html#primery"},{"k": "a", "a": "Ещё два вывода — Производная в точке: определение и вычисление по определению (8.1)", "b": "", "u": "lectures/08/proizvodnaya-v-tochke.html#dop"},{"k": "a", "a": "Частые ошибки — Производная в точке: определение и вычисление по определению (8.1)", "b": "", "u": "lectures/08/proizvodnaya-v-tochke.html#oshibki"},{"k": "a", "a": "Кратко — Производная в точке: определение и вычисление по определению (8.1)", "b": "", "u": "lectures/08/proizvodnaya-v-tochke.html#kratko"},{"k": "a", "a": "Проверь себя — Производная в точке: определение и вычисление по определению (8.1)", "b": "", "u": "lectures/08/proizvodnaya-v-tochke.html#proverka"},{"k": "a", "a": "8.2 Дифференцируемость и непрерывность. Односторонние производные (лекция 8)", "b": "В статье 8.1 производная определена как конечный предел отношения приращений. Но у предела есть условия существования, и функции бывают такие, что в какой-то точке производной нет, хотя график вполне гладко проходит рядом. Здесь собраны условия: что значит «дифференцируема», почему дифференцируемая функция обязательно непрерывна (а наоборот — нет), что такое односторонние производные и как исследо", "u": "lectures/08/differentsiruemost.html"},{"k": "a", "a": "Два определения — Дифференцируемость и непрерывность. Односторонние производные (8.2)", "b": "", "u": "lectures/08/differentsiruemost.html#dva"},{"k": "a", "a": "Дифференцируемая — значит непрерывная — Дифференцируемость и непрерывность. Односторонние производные (8.2)", "b": "", "u": "lectures/08/differentsiruemost.html#neprer"},{"k": "a", "a": "Односторонние производные — Дифференцируемость и непрерывность. Односторонние производные (8.2)", "b": "", "u": "lectures/08/differentsiruemost.html#odnostor"},{"k": "a", "a": "Где нет производной — Дифференцируемость и непрерывность. Односторонние производные (8.2)", "b": "", "u": "lectures/08/differentsiruemost.html#vidy"},{"k": "a", "a": "Кусочные функции — Дифференцируемость и непрерывность. Односторонние производные (8.2)", "b": "", "u": "lectures/08/differentsiruemost.html#stykh"},{"k": "a", "a": "Частые ошибки — Дифференцируемость и непрерывность. Односторонние производные (8.2)", "b": "", "u": "lectures/08/differentsiruemost.html#oshibki"},{"k": "a", "a": "Кратко — Дифференцируемость и непрерывность. Односторонние производные (8.2)", "b": "", "u": "lectures/08/differentsiruemost.html#kratko"},{"k": "a", "a": "Проверь себя — Дифференцируемость и непрерывность. Односторонние производные (8.2)", "b": "", "u": "lectures/08/differentsiruemost.html#proverka"},{"k": "a", "a": "8.3 Таблица производных (лекция 8)", "b": "Находить производные по определению долго, поэтому на его основе составлена таблица производных основных элементарных функций; лекция требует знать её наизусть. В статье вся таблица (15 формул) с условиями, способы её запомнить, вывод нескольких формул, приём «корень и дробь — степень», примеры 2.1 и 2.2 лекции и три типа из практики № 11 (основание меньше 1, корень со степенью, деление на одночле", "u": "lectures/08/tablitsa-proizvodnykh.html"},{"k": "a", "a": "Два правила для начала — Таблица производных (8.3)", "b": "", "u": "lectures/08/tablitsa-proizvodnykh.html#pravila"},{"k": "a", "a": "Таблица 2.1 — Таблица производных (8.3)", "b": "", "u": "lectures/08/tablitsa-proizvodnykh.html#tablitsa"},{"k": "a", "a": "Как выучить — Таблица производных (8.3)", "b": "", "u": "lectures/08/tablitsa-proizvodnykh.html#pomni"},{"k": "a", "a": "Откуда формулы — Таблица производных (8.3)", "b": "", "u": "lectures/08/tablitsa-proizvodnykh.html#vyvod"},{"k": "a", "a": "Корень и дробь — степень — Таблица производных (8.3)", "b": "", "u": "lectures/08/tablitsa-proizvodnykh.html#step"},{"k": "a", "a": "Значение в точке — Таблица производных (8.3)", "b": "", "u": "lectures/08/tablitsa-proizvodnykh.html#znach"},{"k": "a", "a": "Ещё типы из практики — Таблица производных (8.3)", "b": "", "u": "lectures/08/tablitsa-proizvodnykh.html#tipy"},{"k": "a", "a": "Частые ошибки — Таблица производных (8.3)", "b": "", "u": "lectures/08/tablitsa-proizvodnykh.html#oshibki"},{"k": "a", "a": "Кратко — Таблица производных (8.3)", "b": "", "u": "lectures/08/tablitsa-proizvodnykh.html#kratko"},{"k": "a", "a": "Проверь себя — Таблица производных (8.3)", "b": "", "u": "lectures/08/tablitsa-proizvodnykh.html#proverka"},{"k": "a", "a": "8.4 Правила дифференцирования (лекция 8)", "b": "Таблица производных даёт производные только основных функций, а в задачах функции собраны из них с помощью арифметики: сумма, разность, произведение, частное. Для каждого действия есть своё правило дифференцирования. Самое важное при их использовании — правильно определить, какое действие в выражении выполняется последним, и не путать порядок слагаемых в формуле частного. Ниже все правила лекции (", "u": "lectures/08/pravila-differentsirovaniya.html"},{"k": "a", "a": "Четыре правила — Правила дифференцирования (8.4)", "b": "", "u": "lectures/08/pravila-differentsirovaniya.html#pravila"},{"k": "a", "a": "Откуда формулы — Правила дифференцирования (8.4)", "b": "", "u": "lectures/08/pravila-differentsirovaniya.html#vyvod"},{"k": "a", "a": "Как решать — Правила дифференцирования (8.4)", "b": "", "u": "lectures/08/pravila-differentsirovaniya.html#alg"},{"k": "a", "a": "Примеры лекции — Правила дифференцирования (8.4)", "b": "", "u": "lectures/08/pravila-differentsirovaniya.html#primery"},{"k": "a", "a": "Дополнительные примеры — Правила дифференцирования (8.4)", "b": "", "u": "lectures/08/pravila-differentsirovaniya.html#dop"},{"k": "a", "a": "Частые ошибки — Правила дифференцирования (8.4)", "b": "", "u": "lectures/08/pravila-differentsirovaniya.html#oshibki"},{"k": "a", "a": "Кратко — Правила дифференцирования (8.4)", "b": "", "u": "lectures/08/pravila-differentsirovaniya.html#kratko"},{"k": "a", "a": "Проверь себя — Правила дифференцирования (8.4)", "b": "", "u": "lectures/08/pravila-differentsirovaniya.html#proverka"},{"k": "a", "a": "8.5 Производная сложной функции (лекция 8)", "b": "В лекции сказано, что центральное место в технике дифференцирования занимает сложная функция: почти любая функция из задач — это «функция от функции», например sin(3x + 1) , ln(x² + 4) , e −x² . Правило здесь одно: производная внешней функции, умноженная на производную внутренней. Ошибки возникают, когда внутреннюю функцию забывают или внешнюю производную берут не в той точке. В статье теорема с у", "u": "lectures/08/slozhnaya-funktsiya.html"},{"k": "a", "a": "Что такое сложная функция — Производная сложной функции (8.5)", "b": "", "u": "lectures/08/slozhnaya-funktsiya.html#chto"},{"k": "a", "a": "Теорема — Производная сложной функции (8.5)", "b": "", "u": "lectures/08/slozhnaya-funktsiya.html#teorema"},{"k": "a", "a": "Таблица 6.1 — Производная сложной функции (8.5)", "b": "", "u": "lectures/08/slozhnaya-funktsiya.html#tablitsa"},{"k": "a", "a": "Алгоритм «снаружи внутрь» — Производная сложной функции (8.5)", "b": "", "u": "lectures/08/slozhnaya-funktsiya.html#alg"},{"k": "a", "a": "Примеры лекции — Производная сложной функции (8.5)", "b": "", "u": "lectures/08/slozhnaya-funktsiya.html#primery"},{"k": "a", "a": "Дополнительные примеры — Производная сложной функции (8.5)", "b": "", "u": "lectures/08/slozhnaya-funktsiya.html#dop"},{"k": "a", "a": "Проверка в Octave — Производная сложной функции (8.5)", "b": "", "u": "lectures/08/slozhnaya-funktsiya.html#octave"},{"k": "a", "a": "Частые ошибки — Производная сложной функции (8.5)", "b": "", "u": "lectures/08/slozhnaya-funktsiya.html#oshibki"},{"k": "a", "a": "Кратко — Производная сложной функции (8.5)", "b": "", "u": "lectures/08/slozhnaya-funktsiya.html#kratko"},{"k": "a", "a": "Проверь себя — Производная сложной функции (8.5)", "b": "", "u": "lectures/08/slozhnaya-funktsiya.html#proverka"},{"k": "a", "a": "8.6 Обратная функция и её производная (лекция 8)", "b": "Обратная функция — это «функция наоборот»: по значению y она возвращает тот x , из которого y получилось. Логарифм обратен показательной функции, арксинус — синусу, корень — квадрату. Производную обратной функции не обязательно искать заново: она выражается через производную исходной функции, причём очень просто — это обратное число. На этом выводятся производные арксинуса, арктангенса и других фу", "u": "lectures/08/obratnaya-funktsiya.html"},{"k": "a", "a": "Обратная функция — Обратная функция и её производная (8.6)", "b": "", "u": "lectures/08/obratnaya-funktsiya.html#opred"},{"k": "a", "a": "Когда она существует — Обратная функция и её производная (8.6)", "b": "", "u": "lectures/08/obratnaya-funktsiya.html#monot"},{"k": "a", "a": "Производная обратной функции — Обратная функция и её производная (8.6)", "b": "", "u": "lectures/08/obratnaya-funktsiya.html#proizv"},{"k": "a", "a": "Как решать — Обратная функция и её производная (8.6)", "b": "", "u": "lectures/08/obratnaya-funktsiya.html#alg"},{"k": "a", "a": "Примеры — Обратная функция и её производная (8.6)", "b": "", "u": "lectures/08/obratnaya-funktsiya.html#primery"},{"k": "a", "a": "Частые ошибки — Обратная функция и её производная (8.6)", "b": "", "u": "lectures/08/obratnaya-funktsiya.html#oshibki"},{"k": "a", "a": "Кратко — Обратная функция и её производная (8.6)", "b": "", "u": "lectures/08/obratnaya-funktsiya.html#kratko"},{"k": "a", "a": "Проверь себя — Обратная функция и её производная (8.6)", "b": "", "u": "lectures/08/obratnaya-funktsiya.html#proverka"},{"k": "a", "a": "8.7 Геометрический и механический смысл производной (лекция 8)", "b": "Производная — это не только число из таблицы. Геометрически она равна угловому коэффициенту касательной к графику, а физически — скорости изменения величины. В статье примеры 4.1–4.3 и 5.1–5.2 лекции со всеми шагами (в примерах 4.3 и 5.1 числовые ответы в лекции неверны: они исправлены), условие существования касательной, вертикальная касательная и типы задач из задачника: касательная параллельна ", "u": "lectures/08/geometricheskiy-smysl.html"},{"k": "a", "a": "Касательная и нормаль — Геометрический и механический смысл производной (8.7)", "b": "", "u": "lectures/08/geometricheskiy-smysl.html#kasat"},{"k": "a", "a": "Алгоритм — Геометрический и механический смысл производной (8.7)", "b": "", "u": "lectures/08/geometricheskiy-smysl.html#alg"},{"k": "a", "a": "Вертикальная касательная — Геометрический и механический смысл производной (8.7)", "b": "", "u": "lectures/08/geometricheskiy-smysl.html#vert"},{"k": "a", "a": "Углы — Геометрический и механический смысл производной (8.7)", "b": "", "u": "lectures/08/geometricheskiy-smysl.html#ugly"},{"k": "a", "a": "Типовые задачи — Геометрический и механический смысл производной (8.7)", "b": "", "u": "lectures/08/geometricheskiy-smysl.html#tipy"},{"k": "a", "a": "График производной — Геометрический и механический смысл производной (8.7)", "b": "", "u": "lectures/08/geometricheskiy-smysl.html#grafik"},{"k": "a", "a": "Механический смысл — Геометрический и механический смысл производной (8.7)", "b": "", "u": "lectures/08/geometricheskiy-smysl.html#mekh"},{"k": "a", "a": "Частые ошибки — Геометрический и механический смысл производной (8.7)", "b": "", "u": "lectures/08/geometricheskiy-smysl.html#oshibki"},{"k": "a", "a": "Кратко — Геометрический и механический смысл производной (8.7)", "b": "", "u": "lectures/08/geometricheskiy-smysl.html#kratko"},{"k": "a", "a": "Проверь себя — Геометрический и механический смысл производной (8.7)", "b": "", "u": "lectures/08/geometricheskiy-smysl.html#proverka"},{"k": "a", "a": "8.8 Дифференциал функции (лекция 8)", "b": "Приращение функции Δy обычно трудно подсчитать точно, а главная его часть — линейная по Δx — находится просто: это f′(x)·Δx . Её называют дифференциалом. Дифференциал объясняет запись dy/dx , даёт способ приближённо вычислять значения функций и оценивать погрешности. В лекции дифференциал не определяется явно (мелькает на стр. 6 и 9 части 2), поэтому изложение здесь опирается на практику № 12 и до", "u": "lectures/08/differentsial.html"},{"k": "a", "a": "Определение — Дифференциал функции (8.8)", "b": "", "u": "lectures/08/differentsial.html#opred"},{"k": "a", "a": "Геометрический смысл — Дифференциал функции (8.8)", "b": "", "u": "lectures/08/differentsial.html#geom"},{"k": "a", "a": "Свойства — Дифференциал функции (8.8)", "b": "", "u": "lectures/08/differentsial.html#svoistva"},{"k": "a", "a": "Инвариантность формы — Дифференциал функции (8.8)", "b": "", "u": "lectures/08/differentsial.html#invar"},{"k": "a", "a": "Как найти дифференциал — Дифференциал функции (8.8)", "b": "", "u": "lectures/08/differentsial.html#alg"},{"k": "a", "a": "Приближённые вычисления — Дифференциал функции (8.8)", "b": "", "u": "lectures/08/differentsial.html#pribl"},{"k": "a", "a": "Частые ошибки — Дифференциал функции (8.8)", "b": "", "u": "lectures/08/differentsial.html#oshibki"},{"k": "a", "a": "Кратко — Дифференциал функции (8.8)", "b": "", "u": "lectures/08/differentsial.html#kratko"},{"k": "a", "a": "Проверь себя — Дифференциал функции (8.8)", "b": "", "u": "lectures/08/differentsial.html#proverka"},{"k": "a", "a": "8.9 Неявные и параметрические функции. Логарифмическая производная (лекция 8)", "b": "До сих пор функция была задана явно, формулой y = f(x) . Но кривая может быть задана уравнением, связывающим x и y , например x² + y² = 1 , или двумя формулами через параметр, как траектория точки. Решать такое уравнение относительно y часто невозможно или невыгодно, а производная при этом находится. В статье три приёма: дифференцирование неявной функции, параметрической и логарифмическая производ", "u": "lectures/08/neyavnye-parametricheskie.html"},{"k": "a", "a": "Три способа задать функцию — Неявные и параметрические функции. Логарифмическая производная (8.9)", "b": "", "u": "lectures/08/neyavnye-parametricheskie.html#sposoby"},{"k": "a", "a": "Неявная функция — Неявные и параметрические функции. Логарифмическая производная (8.9)", "b": "", "u": "lectures/08/neyavnye-parametricheskie.html#neyav"},{"k": "a", "a": "Логарифмическая производная — Неявные и параметрические функции. Логарифмическая производная (8.9)", "b": "", "u": "lectures/08/neyavnye-parametricheskie.html#log"},{"k": "a", "a": "Типы 12.x практики — Неявные и параметрические функции. Логарифмическая производная (8.9)", "b": "", "u": "lectures/08/neyavnye-parametricheskie.html#typy12"},{"k": "a", "a": "Параметрическая функция — Неявные и параметрические функции. Логарифмическая производная (8.9)", "b": "", "u": "lectures/08/neyavnye-parametricheskie.html#param"},{"k": "a", "a": "Частые ошибки — Неявные и параметрические функции. Логарифмическая производная (8.9)", "b": "", "u": "lectures/08/neyavnye-parametricheskie.html#oshibki"},{"k": "a", "a": "Кратко — Неявные и параметрические функции. Логарифмическая производная (8.9)", "b": "", "u": "lectures/08/neyavnye-parametricheskie.html#kratko"},{"k": "a", "a": "Проверь себя — Неявные и параметрические функции. Логарифмическая производная (8.9)", "b": "", "u": "lectures/08/neyavnye-parametricheskie.html#proverka"},{"k": "a", "a": "8.10 Производные и дифференциалы высших порядков (лекция 8)", "b": "Производная f′(x) сама является функцией от x , и её тоже можно дифференцировать. Получается вторая производная, затем третья и так далее. Вторая производная нужна для ускорения в механике, для исследования выпуклости графика и экстремумов (лекции 9 и 10). Для производных высших порядков есть формула Лейбница для произведения, а для дифференциалов — неожиданный факт: у второго дифференциала нет св", "u": "lectures/08/vysshie-poryadki.html"},{"k": "a", "a": "Определение — Производные и дифференциалы высших порядков (8.10)", "b": "", "u": "lectures/08/vysshie-poryadki.html#opred"},{"k": "a", "a": "Свойства и формула Лейбница — Производные и дифференциалы высших порядков (8.10)", "b": "", "u": "lectures/08/vysshie-poryadki.html#svoistva"},{"k": "a", "a": "Формулы n-й производной — Производные и дифференциалы высших порядков (8.10)", "b": "", "u": "lectures/08/vysshie-poryadki.html#formuly"},{"k": "a", "a": "Неявные и параметрические функции — Производные и дифференциалы высших порядков (8.10)", "b": "", "u": "lectures/08/vysshie-poryadki.html#neyav"},{"k": "a", "a": "Дифференциалы высших порядков — Производные и дифференциалы высших порядков (8.10)", "b": "", "u": "lectures/08/vysshie-poryadki.html#diff"},{"k": "a", "a": "Частые ошибки — Производные и дифференциалы высших порядков (8.10)", "b": "", "u": "lectures/08/vysshie-poryadki.html#oshibki"},{"k": "a", "a": "Кратко — Производные и дифференциалы высших порядков (8.10)", "b": "", "u": "lectures/08/vysshie-poryadki.html#kratko"},{"k": "a", "a": "Проверь себя — Производные и дифференциалы высших порядков (8.10)", "b": "", "u": "lectures/08/vysshie-poryadki.html#proverka"},{"k": "a", "a": "9.1 Производные высших порядков и формула Лейбница (лекция 9)", "b": "Производная — тоже функция, поэтому её можно дифференцировать ещё раз. Так получаются производные второго, третьего и вообще n -го порядка. Вторая производная нужна для выпуклости и исследования экстремумов (лекция 10), n -я — для формулы Тейлора (статья 9.4). В этой статье: определение со всеми условиями, таблица n -х производных основных функций, формула Лейбница для n -й производной произведени", "u": "lectures/09/vysshie-proizvodnye.html"},{"k": "a", "a": "Определение и обозначения — Производные высших порядков и формула Лейбница (9.1)", "b": "", "u": "lectures/09/vysshie-proizvodnye.html#opr"},{"k": "a", "a": "n-е производные основных функций — Производные высших порядков и формула Лейбница (9.1)", "b": "", "u": "lectures/09/vysshie-proizvodnye.html#tablica"},{"k": "a", "a": "Теорема и формула Лейбница — Производные высших порядков и формула Лейбница (9.1)", "b": "", "u": "lectures/09/vysshie-proizvodnye.html#teorema"},{"k": "a", "a": "Доказательство — Производные высших порядков и формула Лейбница (9.1)", "b": "", "u": "lectures/09/vysshie-proizvodnye.html#dokaz"},{"k": "a", "a": "Как применять Лейбница — Производные высших порядков и формула Лейбница (9.1)", "b": "", "u": "lectures/09/vysshie-proizvodnye.html#kak"},{"k": "a", "a": "Разобранные примеры — Производные высших порядков и формула Лейбница (9.1)", "b": "", "u": "lectures/09/vysshie-proizvodnye.html#primery"},{"k": "a", "a": "Частые ошибки — Производные высших порядков и формула Лейбница (9.1)", "b": "", "u": "lectures/09/vysshie-proizvodnye.html#oshibki"},{"k": "a", "a": "Кратко — Производные высших порядков и формула Лейбница (9.1)", "b": "", "u": "lectures/09/vysshie-proizvodnye.html#kratko"},{"k": "a", "a": "Проверь себя — Производные высших порядков и формула Лейбница (9.1)", "b": "", "u": "lectures/09/vysshie-proizvodnye.html#proverka"},{"k": "a", "a": "9.2 Дифференциалы высших порядков; вторая производная неявной и параметрической функций (лекция 9)", "b": "Дифференциал df = f′(x)dx — главная линейная часть приращения функции. У него есть «высшие» аналоги: второй дифференциал d²f , третий d³f и так далее. Лекция утверждает формулу dⁿf = f (n) (x)(dx)ⁿ (индукцию оставляет читателю) и тут же предупреждает: при n ≥ 2 она верна только для независимой переменной x . Если же x сама зависит от другой переменной t , у второго дифференциала появляется добавка", "u": "lectures/09/differencialy-vysshih-poryadkov.html"},{"k": "a", "a": "Первый дифференциал — Дифференциалы высших порядков; вторая производная неявной и параметрической функций (9.2)", "b": "", "u": "lectures/09/differencialy-vysshih-poryadkov.html#d1"},{"k": "a", "a": "Второй и n-й дифференциалы — Дифференциалы высших порядков; вторая производная неявной и параметрической функций (9.2)", "b": "", "u": "lectures/09/differencialy-vysshih-poryadkov.html#d2"},{"k": "a", "a": "Нет инвариантности формы — Дифференциалы высших порядков; вторая производная неявной и параметрической функций (9.2)", "b": "", "u": "lectures/09/differencialy-vysshih-poryadkov.html#neinv"},{"k": "a", "a": "Параметрическая функция — Дифференциалы высших порядков; вторая производная неявной и параметрической функций (9.2)", "b": "", "u": "lectures/09/differencialy-vysshih-poryadkov.html#param"},{"k": "a", "a": "Неявная функция — Дифференциалы высших порядков; вторая производная неявной и параметрической функций (9.2)", "b": "", "u": "lectures/09/differencialy-vysshih-poryadkov.html#neyavn"},{"k": "a", "a": "Частые ошибки — Дифференциалы высших порядков; вторая производная неявной и параметрической функций (9.2)", "b": "", "u": "lectures/09/differencialy-vysshih-poryadkov.html#oshibki"},{"k": "a", "a": "Кратко — Дифференциалы высших порядков; вторая производная неявной и параметрической функций (9.2)", "b": "", "u": "lectures/09/differencialy-vysshih-poryadkov.html#kratko"},{"k": "a", "a": "Проверь себя — Дифференциалы высших порядков; вторая производная неявной и параметрической функций (9.2)", "b": "", "u": "lectures/09/differencialy-vysshih-poryadkov.html#proverka"},{"k": "a", "a": "9.3 Теоремы о среднем: Ферма, Ролль, Лагранж, Коши (лекция 9)", "b": "Четыре теоремы этой статьи говорят об одном: у «хорошей» функции (непрерывной на отрезке и дифференцируемой внутри него) есть точка, в которой производная принимает нужное значение: нуль (Ферма, Ролль), среднюю скорость изменения (Лагранж) или отношение скоростей двух функций (Коши). Ферма — утверждение об одной точке (точке экстремума); Ролль, Лагранж и Коши — о точке между двумя концами отрезка.", "u": "lectures/09/teoremy-o-srednem.html"},{"k": "a", "a": "Теорема Ферма — Теоремы о среднем: Ферма, Ролль, Лагранж, Коши (9.3)", "b": "", "u": "lectures/09/teoremy-o-srednem.html#fermat"},{"k": "a", "a": "Теорема Ролля — Теоремы о среднем: Ферма, Ролль, Лагранж, Коши (9.3)", "b": "", "u": "lectures/09/teoremy-o-srednem.html#rolle"},{"k": "a", "a": "Теорема Лагранжа — Теоремы о среднем: Ферма, Ролль, Лагранж, Коши (9.3)", "b": "", "u": "lectures/09/teoremy-o-srednem.html#lagrange"},{"k": "a", "a": "Теорема Коши — Теоремы о среднем: Ферма, Ролль, Лагранж, Коши (9.3)", "b": "", "u": "lectures/09/teoremy-o-srednem.html#koshi"},{"k": "a", "a": "Сводка условий — Теоремы о среднем: Ферма, Ролль, Лагранж, Коши (9.3)", "b": "", "u": "lectures/09/teoremy-o-srednem.html#svodka"},{"k": "a", "a": "Как проверять и применять — Теоремы о среднем: Ферма, Ролль, Лагранж, Коши (9.3)", "b": "", "u": "lectures/09/teoremy-o-srednem.html#kak"},{"k": "a", "a": "Разобранные примеры — Теоремы о среднем: Ферма, Ролль, Лагранж, Коши (9.3)", "b": "", "u": "lectures/09/teoremy-o-srednem.html#primery"},{"k": "a", "a": "Упражнения лекции — Теоремы о среднем: Ферма, Ролль, Лагранж, Коши (9.3)", "b": "", "u": "lectures/09/teoremy-o-srednem.html#uprazhneniya"},{"k": "a", "a": "Частые ошибки — Теоремы о среднем: Ферма, Ролль, Лагранж, Коши (9.3)", "b": "", "u": "lectures/09/teoremy-o-srednem.html#oshibki"},{"k": "a", "a": "Кратко — Теоремы о среднем: Ферма, Ролль, Лагранж, Коши (9.3)", "b": "", "u": "lectures/09/teoremy-o-srednem.html#kratko"},{"k": "a", "a": "Проверь себя — Теоремы о среднем: Ферма, Ролль, Лагранж, Коши (9.3)", "b": "", "u": "lectures/09/teoremy-o-srednem.html#proverka"},{"k": "a", "a": "9.4 Формула Тейлора: многочлен и остаточный член (лекция 9)", "b": "Касательная — это первое приближение функции многочленом: степени один, с общим значением и общей производной в точке. Формула Тейлора идёт дальше: она приближает функцию вблизи точки многочленом любой степени n , коэффициенты которого — производные функции в этой точке, и точно описывает ошибку («остаточный член»). Это главный инструмент для пределов (статьи 9.5, 9.7) и приближённых вычислений. В", "u": "lectures/09/formula-tejlora.html"},{"k": "a", "a": "Формула Тейлора и её части — Формула Тейлора: многочлен и остаточный член (9.4)", "b": "", "u": "lectures/09/formula-tejlora.html#formula"},{"k": "a", "a": "Что приближает каждый член — Формула Тейлора: многочлен и остаточный член (9.4)", "b": "", "u": "lectures/09/formula-tejlora.html#geom"},{"k": "a", "a": "Лемма об остатке — Формула Тейлора: многочлен и остаточный член (9.4)", "b": "", "u": "lectures/09/formula-tejlora.html#lemma"},{"k": "a", "a": "Остаток в форме Пеано — Формула Тейлора: многочлен и остаточный член (9.4)", "b": "", "u": "lectures/09/formula-tejlora.html#peano"},{"k": "a", "a": "Остаток в форме Лагранжа — Формула Тейлора: многочлен и остаточный член (9.4)", "b": "", "u": "lectures/09/formula-tejlora.html#lagrange"},{"k": "a", "a": "Пеано и Лагранж: когда что — Формула Тейлора: многочлен и остаточный член (9.4)", "b": "", "u": "lectures/09/formula-tejlora.html#sravn"},{"k": "a", "a": "Разобранные примеры — Формула Тейлора: многочлен и остаточный член (9.4)", "b": "", "u": "lectures/09/formula-tejlora.html#primery"},{"k": "a", "a": "Частые ошибки — Формула Тейлора: многочлен и остаточный член (9.4)", "b": "", "u": "lectures/09/formula-tejlora.html#oshibki"},{"k": "a", "a": "Кратко — Формула Тейлора: многочлен и остаточный член (9.4)", "b": "", "u": "lectures/09/formula-tejlora.html#kratko"},{"k": "a", "a": "Проверь себя — Формула Тейлора: многочлен и остаточный член (9.4)", "b": "", "u": "lectures/09/formula-tejlora.html#proverka"},{"k": "a", "a": "9.5 Единственность разложения и разложения основных функций (лекция 9)", "b": "Формулу Тейлора можно получить дифференцированием, но чаще её получают быстрее — алгеброй: подстановкой, умножением, готовой геометрической прогрессией. Гарантирует, что при этом получится та же формула, теорема единственности: любое представление функции в виде «многочлен степени не выше n плюс o((x − x₀) n ) » единственно, а если существует f (n) (x₀) , то оно и есть формула Тейлора. В статье: т", "u": "lectures/09/razlozheniya-tejlora.html"},{"k": "a", "a": "Теорема единственности — Единственность разложения и разложения основных функций (9.5)", "b": "", "u": "lectures/09/razlozheniya-tejlora.html#edinstv"},{"k": "a", "a": "Следствие и как им пользоваться — Единственность разложения и разложения основных функций (9.5)", "b": "", "u": "lectures/09/razlozheniya-tejlora.html#sled"},{"k": "a", "a": "Пример: 1/(1 − x) — Единственность разложения и разложения основных функций (9.5)", "b": "", "u": "lectures/09/razlozheniya-tejlora.html#primer"},{"k": "a", "a": "Разложения основных функций — Единственность разложения и разложения основных функций (9.5)", "b": "", "u": "lectures/09/razlozheniya-tejlora.html#tablica"},{"k": "a", "a": "Арифметика с o(…) — Единственность разложения и разложения основных функций (9.5)", "b": "", "u": "lectures/09/razlozheniya-tejlora.html#arifm"},{"k": "a", "a": "Как получать разложения — Единственность разложения и разложения основных функций (9.5)", "b": "", "u": "lectures/09/razlozheniya-tejlora.html#kak"},{"k": "a", "a": "Пределы по Тейлору — Единственность разложения и разложения основных функций (9.5)", "b": "", "u": "lectures/09/razlozheniya-tejlora.html#predely"},{"k": "a", "a": "Приближённые вычисления — Единственность разложения и разложения основных функций (9.5)", "b": "", "u": "lectures/09/razlozheniya-tejlora.html#pribl"},{"k": "a", "a": "Упражнения лекции — Единственность разложения и разложения основных функций (9.5)", "b": "", "u": "lectures/09/razlozheniya-tejlora.html#uprazhneniya"},{"k": "a", "a": "Частые ошибки — Единственность разложения и разложения основных функций (9.5)", "b": "", "u": "lectures/09/razlozheniya-tejlora.html#oshibki"},{"k": "a", "a": "Кратко — Единственность разложения и разложения основных функций (9.5)", "b": "", "u": "lectures/09/razlozheniya-tejlora.html#kratko"},{"k": "a", "a": "Проверь себя — Единственность разложения и разложения основных функций (9.5)", "b": "", "u": "lectures/09/razlozheniya-tejlora.html#proverka"},{"k": "a", "a": "9.6 Правило Лопиталя (лекция 9)", "b": "Правило Лопиталя раскрывает неопределённости 0/0 и ∞/∞ : вместо предела отношения функций берут предел отношения их производных. Правилу слишком часто верят вслепую, а оно работает только при выполнении условий: нужный вид неопределённости, дифференцируемость, g′ ≠ 0 и — самое забываемое — существование предела отношения производных. В статье: три теоремы лекции со всеми условиями, доказательство ", "u": "lectures/09/pravilo-lopitalya.html"},{"k": "a", "a": "Идея правила — Правило Лопиталя (9.6)", "b": "", "u": "lectures/09/pravilo-lopitalya.html#idea"},{"k": "a", "a": "Теорема 1: неопределённость 0/0 — Правило Лопиталя (9.6)", "b": "", "u": "lectures/09/pravilo-lopitalya.html#t1"},{"k": "a", "a": "Доказательство — Правило Лопиталя (9.6)", "b": "", "u": "lectures/09/pravilo-lopitalya.html#dok"},{"k": "a", "a": "Теоремы 2 и 3 — Правило Лопиталя (9.6)", "b": "", "u": "lectures/09/pravilo-lopitalya.html#t23"},{"k": "a", "a": "Зачем нужны условия — Правило Лопиталя (9.6)", "b": "", "u": "lectures/09/pravilo-lopitalya.html#usl"},{"k": "a", "a": "Алгоритм — Правило Лопиталя (9.6)", "b": "", "u": "lectures/09/pravilo-lopitalya.html#kak"},{"k": "a", "a": "Разобранные примеры — Правило Лопиталя (9.6)", "b": "", "u": "lectures/09/pravilo-lopitalya.html#primery"},{"k": "a", "a": "Частые ошибки — Правило Лопиталя (9.6)", "b": "", "u": "lectures/09/pravilo-lopitalya.html#oshibki"},{"k": "a", "a": "Кратко — Правило Лопиталя (9.6)", "b": "", "u": "lectures/09/pravilo-lopitalya.html#kratko"},{"k": "a", "a": "Проверь себя — Правило Лопиталя (9.6)", "b": "", "u": "lectures/09/pravilo-lopitalya.html#proverka"},{"k": "a", "a": "9.7 Неопределённости других видов и выбор метода (лекция 9)", "b": "Правило Лопиталя работает только с дробями 0/0 и ∞/∞ . Но неопределённостей больше: на стр. 13 лекция называет ещё пять — 0·∞ , ∞ − ∞ , 0⁰ , ∞⁰ , 1^∞ — и объясняет идею: первые две приводят преобразованием к дроби, выражения для последних трёх логарифмируют. В статье: рецепт для каждого вида, разобранные примеры (в том числе упражнение лекции lim x^x ), сравнение трёх инструментов (правило Лопитал", "u": "lectures/09/neopredelennosti-vidy.html"},{"k": "a", "a": "Какие бывают неопределённости — Неопределённости других видов и выбор метода (9.7)", "b": "", "u": "lectures/09/neopredelennosti-vidy.html#vidy"},{"k": "a", "a": "0·∞ и ∞ − ∞: свести к дроби — Неопределённости других видов и выбор метода (9.7)", "b": "", "u": "lectures/09/neopredelennosti-vidy.html#drob"},{"k": "a", "a": "0⁰, ∞⁰, 1^∞: логарифм — Неопределённости других видов и выбор метода (9.7)", "b": "", "u": "lectures/09/neopredelennosti-vidy.html#log"},{"k": "a", "a": "Разобранные примеры — Неопределённости других видов и выбор метода (9.7)", "b": "", "u": "lectures/09/neopredelennosti-vidy.html#primery"},{"k": "a", "a": "Выбор метода — Неопределённости других видов и выбор метода (9.7)", "b": "", "u": "lectures/09/neopredelennosti-vidy.html#metod"},{"k": "a", "a": "Частые ошибки — Неопределённости других видов и выбор метода (9.7)", "b": "", "u": "lectures/09/neopredelennosti-vidy.html#oshibki"},{"k": "a", "a": "Кратко — Неопределённости других видов и выбор метода (9.7)", "b": "", "u": "lectures/09/neopredelennosti-vidy.html#kratko"},{"k": "a", "a": "Проверь себя — Неопределённости других видов и выбор метода (9.7)", "b": "", "u": "lectures/09/neopredelennosti-vidy.html#proverka"},{"k": "a", "a": "10.1 Монотонность функции и критические точки (лекция 10)", "b": "Первый вопрос исследования функции: на каких промежутках график идёт вверх, а на каких вниз. Отвечает знак производной. В статье — теорема 4.7.1 с доказательством и три замечания к ней, критические точки, алгоритм «область определения → производная → знаки» и полный разбор примера 1 лекции. Дополнительно: два типовых примера и применение монотонности к неравенствам. Что значит «возрастает» Функция", "u": "lectures/10/monotonnost.html"},{"k": "a", "a": "Что значит «возрастает» — Монотонность функции и критические точки (10.1)", "b": "", "u": "lectures/10/monotonnost.html#opr"},{"k": "a", "a": "Теорема 4.7.1 — Монотонность функции и критические точки (10.1)", "b": "", "u": "lectures/10/monotonnost.html#teor"},{"k": "a", "a": "Три замечания — Монотонность функции и критические точки (10.1)", "b": "", "u": "lectures/10/monotonnost.html#zamech"},{"k": "a", "a": "Критические точки — Монотонность функции и критические точки (10.1)", "b": "", "u": "lectures/10/monotonnost.html#krit"},{"k": "a", "a": "Алгоритм — Монотонность функции и критические точки (10.1)", "b": "", "u": "lectures/10/monotonnost.html#alg"},{"k": "a", "a": "Разобранные примеры — Монотонность функции и критические точки (10.1)", "b": "", "u": "lectures/10/monotonnost.html#primery"},{"k": "a", "a": "Неравенства — Монотонность функции и критические точки (10.1)", "b": "", "u": "lectures/10/monotonnost.html#neravenstva"},{"k": "a", "a": "Частые ошибки — Монотонность функции и критические точки (10.1)", "b": "", "u": "lectures/10/monotonnost.html#oshibki"},{"k": "a", "a": "Кратко — Монотонность функции и критические точки (10.1)", "b": "", "u": "lectures/10/monotonnost.html#kratko"},{"k": "a", "a": "Проверь себя — Монотонность функции и критические точки (10.1)", "b": "", "u": "lectures/10/monotonnost.html#proverka"},{"k": "a", "a": "10.2 Экстремумы: условие Ферма и два достаточных признака (лекция 10)", "b": "Экстремум — это вершина холма или дно впадины на графике. Найти их помогает производная: вершины и впадины ищут среди критических точек (условие Ферма), а потом проверяют двумя признаками — по смене знака f′ и по знаку f″ . Главное в статье — условия: у каждого признака они свои, и без них вывод ложен. Разберём контрпримеры лекции (экстремум без смены монотонности, функция x²(2 + cos(1/x)) ), глад", "u": "lectures/10/ekstremumy.html"},{"k": "a", "a": "Определение экстремума — Экстремумы: условие Ферма и два достаточных признака (10.2)", "b": "", "u": "lectures/10/ekstremumy.html#opr"},{"k": "a", "a": "Необходимое условие — Экстремумы: условие Ферма и два достаточных признака (10.2)", "b": "", "u": "lectures/10/ekstremumy.html#ferma"},{"k": "a", "a": "Первый признак — Экстремумы: условие Ферма и два достаточных признака (10.2)", "b": "", "u": "lectures/10/ekstremumy.html#first"},{"k": "a", "a": "Условия и контрпримеры — Экстремумы: условие Ферма и два достаточных признака (10.2)", "b": "", "u": "lectures/10/ekstremumy.html#uslovia"},{"k": "a", "a": "Гладкие и острые — Экстремумы: условие Ферма и два достаточных признака (10.2)", "b": "", "u": "lectures/10/ekstremumy.html#gladk"},{"k": "a", "a": "Второй признак — Экстремумы: условие Ферма и два достаточных признака (10.2)", "b": "", "u": "lectures/10/ekstremumy.html#second"},{"k": "a", "a": "Какой признак применять — Экстремумы: условие Ферма и два достаточных признака (10.2)", "b": "", "u": "lectures/10/ekstremumy.html#vybor"},{"k": "a", "a": "Разобранные примеры — Экстремумы: условие Ферма и два достаточных признака (10.2)", "b": "", "u": "lectures/10/ekstremumy.html#primery"},{"k": "a", "a": "Частые ошибки — Экстремумы: условие Ферма и два достаточных признака (10.2)", "b": "", "u": "lectures/10/ekstremumy.html#oshibki"},{"k": "a", "a": "Кратко — Экстремумы: условие Ферма и два достаточных признака (10.2)", "b": "", "u": "lectures/10/ekstremumy.html#kratko"},{"k": "a", "a": "Проверь себя — Экстремумы: условие Ферма и два достаточных признака (10.2)", "b": "", "u": "lectures/10/ekstremumy.html#proverka"},{"k": "a", "a": "10.3 Наибольшее и наименьшее значения; задачи на оптимум (лекция 10)", "b": "Экстремум — понятие локальное, а в задачах спрашивают другое: какое значение функции наибольшее (наименьшее) на данном промежутке. Для непрерывной функции на отрезке ответ даёт короткое правило: посчитать значения в критических точках и на концах и сравнить числа. В статье — правило со всеми условиями и обоснованием, пример 4 лекции (прямоугольник в треугольнике) с проверкой концов, числовые приме", "u": "lectures/10/naibolshee-naimenshee.html"},{"k": "a", "a": "Локальное и наибольшее — Наибольшее и наименьшее значения; задачи на оптимум (10.3)", "b": "", "u": "lectures/10/naibolshee-naimenshee.html#otlichie"},{"k": "a", "a": "Правило и алгоритм — Наибольшее и наименьшее значения; задачи на оптимум (10.3)", "b": "", "u": "lectures/10/naibolshee-naimenshee.html#pravilo"},{"k": "a", "a": "Пример 4 лекции — Наибольшее и наименьшее значения; задачи на оптимум (10.3)", "b": "", "u": "lectures/10/naibolshee-naimenshee.html#primer4"},{"k": "a", "a": "Числовые примеры — Наибольшее и наименьшее значения; задачи на оптимум (10.3)", "b": "", "u": "lectures/10/naibolshee-naimenshee.html#primery"},{"k": "a", "a": "Задачи на оптимум — Наибольшее и наименьшее значения; задачи на оптимум (10.3)", "b": "", "u": "lectures/10/naibolshee-naimenshee.html#optimum"},{"k": "a", "a": "Частые ошибки — Наибольшее и наименьшее значения; задачи на оптимум (10.3)", "b": "", "u": "lectures/10/naibolshee-naimenshee.html#oshibki"},{"k": "a", "a": "Кратко — Наибольшее и наименьшее значения; задачи на оптимум (10.3)", "b": "", "u": "lectures/10/naibolshee-naimenshee.html#kratko"},{"k": "a", "a": "Проверь себя — Наибольшее и наименьшее значения; задачи на оптимум (10.3)", "b": "", "u": "lectures/10/naibolshee-naimenshee.html#proverka"},{"k": "a", "a": "10.4 Выпуклость, вогнутость и точки перегиба (лекция 10)", "b": "Выпуклость говорит, куда изгибается график: чашей (улыбка ∪ ) или горкой (шапка ∩ ). Читается она по знаку второй производной, а точки, где изгиб меняет направление, называют точками перегиба. В статье: определение через середину хорды, теорема 4.7.4 с доказательством, свойство «график лежит по одну сторону от касательной», определение перегиба и его условия (первая производная должна существовать", "u": "lectures/10/vypuklost-peregib.html"},{"k": "a", "a": "Определение выпуклости — Выпуклость, вогнутость и точки перегиба (10.4)", "b": "", "u": "lectures/10/vypuklost-peregib.html#opr"},{"k": "a", "a": "Теорема 4.7.4 — Выпуклость, вогнутость и точки перегиба (10.4)", "b": "", "u": "lectures/10/vypuklost-peregib.html#teor"},{"k": "a", "a": "График и касательная — Выпуклость, вогнутость и точки перегиба (10.4)", "b": "", "u": "lectures/10/vypuklost-peregib.html#kasat"},{"k": "a", "a": "Точки перегиба — Выпуклость, вогнутость и точки перегиба (10.4)", "b": "", "u": "lectures/10/vypuklost-peregib.html#peregib"},{"k": "a", "a": "Алгоритм — Выпуклость, вогнутость и точки перегиба (10.4)", "b": "", "u": "lectures/10/vypuklost-peregib.html#alg"},{"k": "a", "a": "Разобранные примеры — Выпуклость, вогнутость и точки перегиба (10.4)", "b": "", "u": "lectures/10/vypuklost-peregib.html#primery"},{"k": "a", "a": "Частые ошибки — Выпуклость, вогнутость и точки перегиба (10.4)", "b": "", "u": "lectures/10/vypuklost-peregib.html#oshibki"},{"k": "a", "a": "Кратко — Выпуклость, вогнутость и точки перегиба (10.4)", "b": "", "u": "lectures/10/vypuklost-peregib.html#kratko"},{"k": "a", "a": "Проверь себя — Выпуклость, вогнутость и точки перегиба (10.4)", "b": "", "u": "lectures/10/vypuklost-peregib.html#proverka"},{"k": "a", "a": "10.5 Асимптоты графика функции (лекция 10)", "b": "Асимптота — прямая, к которой график неограниченно приближается, когда точка графика уходит в бесконечность. Бывают вертикальные, наклонные и горизонтальные. Главное, что нужно усвоить: наклонную асимптоту ищут формулами k = lim f(x)/x и b = lim (f(x) − kx) , причём отдельно при x → +∞ и при x → −∞ (у сторон они разные, а с одной стороны её может не быть), а вертикальные ищут в точках разрыва по о", "u": "lectures/10/asimptoty.html"},{"k": "a", "a": "Определения — Асимптоты графика функции (10.5)", "b": "", "u": "lectures/10/asimptoty.html#opr"},{"k": "a", "a": "Вертикальные — Асимптоты графика функции (10.5)", "b": "", "u": "lectures/10/asimptoty.html#vert"},{"k": "a", "a": "Наклонные: k и b — Асимптоты графика функции (10.5)", "b": "", "u": "lectures/10/asimptoty.html#nakl"},{"k": "a", "a": "Горизонтальные и рациональные — Асимптоты графика функции (10.5)", "b": "", "u": "lectures/10/asimptoty.html#gor"},{"k": "a", "a": "Разобранные примеры — Асимптоты графика функции (10.5)", "b": "", "u": "lectures/10/asimptoty.html#primery"},{"k": "a", "a": "Алгоритм — Асимптоты графика функции (10.5)", "b": "", "u": "lectures/10/asimptoty.html#alg"},{"k": "a", "a": "Частые ошибки — Асимптоты графика функции (10.5)", "b": "", "u": "lectures/10/asimptoty.html#oshibki"},{"k": "a", "a": "Кратко — Асимптоты графика функции (10.5)", "b": "", "u": "lectures/10/asimptoty.html#kratko"},{"k": "a", "a": "Проверь себя — Асимптоты графика функции (10.5)", "b": "", "u": "lectures/10/asimptoty.html#proverka"},{"k": "a", "a": "10.6 Схема исследования функции и построение графика (лекция 10)", "b": "Полное исследование функции — это сборка предыдущих статей в один план: область определения, симметрия, монотонность и экстремумы, выпуклость и перегибы, асимптоты, точки пересечения с осями, график. План лекции состоит из семи пунктов (стр. 13). В статье: что писать в каждом пункте и зачем он нужен, сквозной пример 9 лекции с графиком (в нём две опечатки, они исправлены), ещё один пример с нечётн", "u": "lectures/10/polnoe-issledovanie.html"},{"k": "a", "a": "Схема исследования — Схема исследования функции и построение графика (10.6)", "b": "", "u": "lectures/10/polnoe-issledovanie.html#plan"},{"k": "a", "a": "Как выполнять пункты — Схема исследования функции и построение графика (10.6)", "b": "", "u": "lectures/10/polnoe-issledovanie.html#kak"},{"k": "a", "a": "Пример 9 лекции — Схема исследования функции и построение графика (10.6)", "b": "", "u": "lectures/10/polnoe-issledovanie.html#primer9"},{"k": "a", "a": "Ещё один пример — Схема исследования функции и построение графика (10.6)", "b": "", "u": "lectures/10/polnoe-issledovanie.html#primer12"},{"k": "a", "a": "Частые ошибки — Схема исследования функции и построение графика (10.6)", "b": "", "u": "lectures/10/polnoe-issledovanie.html#oshibki"},{"k": "a", "a": "Кратко — Схема исследования функции и построение графика (10.6)", "b": "", "u": "lectures/10/polnoe-issledovanie.html#kratko"},{"k": "a", "a": "Проверь себя — Схема исследования функции и построение графика (10.6)", "b": "", "u": "lectures/10/polnoe-issledovanie.html#proverka"},{"k": "a", "a": "10.7 Исследование функции с корнями: острые точки (лекция 10)", "b": "Функции с корнями нечётной степени и дробными степенями ведут себя иначе, чем многочлены и дроби: у них есть особые точки, где производная бесконечна, а сама функция определена (экстремум в такой точке называют острым). В статье — что нужно знать при работе с такими функциями (область определения, знак кубического корня, критические точки с бесконечной производной), полный разбор примера 10 лекции", "u": "lectures/10/ostrye-tochki.html"},{"k": "a", "a": "Особенности корней — Исследование функции с корнями: острые точки (10.7)", "b": "", "u": "lectures/10/ostrye-tochki.html#osob"},{"k": "a", "a": "Пример 10 лекции — Исследование функции с корнями: острые точки (10.7)", "b": "", "u": "lectures/10/ostrye-tochki.html#primer10"},{"k": "a", "a": "Ещё пример: ln x / x — Исследование функции с корнями: острые точки (10.7)", "b": "", "u": "lectures/10/ostrye-tochki.html#lnx"},{"k": "a", "a": "Частые ошибки — Исследование функции с корнями: острые точки (10.7)", "b": "", "u": "lectures/10/ostrye-tochki.html#oshibki"},{"k": "a", "a": "Кратко — Исследование функции с корнями: острые точки (10.7)", "b": "", "u": "lectures/10/ostrye-tochki.html#kratko"},{"k": "a", "a": "Проверь себя — Исследование функции с корнями: острые точки (10.7)", "b": "", "u": "lectures/10/ostrye-tochki.html#proverka"},{"k": "a", "a": "10.8 Кривая, заданная параметрически (лекция 10)", "b": "Кривая x = x(t) , y = y(t) не всегда является графиком одной функции y(x) : она может состоять из нескольких ветвей, возвращаться и пересекать сама себя. Поэтому исследование идёт по параметру t : область t и ветви, асимптоты по предельным значениям x и y , знаки x′(t) и y′(t) , затем y′ₓ и y″ₓₓ (лекция 8, статьи 8.9 и 8.10; лекция 9, статья 9.2), сводная таблица и график с подписями значений пара", "u": "lectures/10/parametricheskaya-krivaya.html"},{"k": "a", "a": "Схема исследования — Кривая, заданная параметрически (10.8)", "b": "", "u": "lectures/10/parametricheskaya-krivaya.html#shema"},{"k": "a", "a": "Пример 11 лекции — Кривая, заданная параметрически (10.8)", "b": "", "u": "lectures/10/parametricheskaya-krivaya.html#primer11"},{"k": "a", "a": "Сводная таблица и график — Кривая, заданная параметрически (10.8)", "b": "", "u": "lectures/10/parametricheskaya-krivaya.html#tabl"},{"k": "a", "a": "Частые ошибки — Кривая, заданная параметрически (10.8)", "b": "", "u": "lectures/10/parametricheskaya-krivaya.html#oshibki"},{"k": "a", "a": "Кратко — Кривая, заданная параметрически (10.8)", "b": "", "u": "lectures/10/parametricheskaya-krivaya.html#kratko"},{"k": "a", "a": "Проверь себя — Кривая, заданная параметрически (10.8)", "b": "", "u": "lectures/10/parametricheskaya-krivaya.html#proverka"},{"k": "a", "a": "11.1 Первообразная и неопределённый интеграл (лекция 11)", "b": "Дифференцирование по заданной функции находит её производную. Интегрирование решает обратную задачу: дана производная f , найти функцию F , у которой F′ = f . Так по скорости восстанавливают путь, а по угловому коэффициенту касательной — кривую. У обратной задачи есть особенность: ответ не один, а целое семейство функций, отличающихся на постоянную. В статье: точное определение первообразной (где ", "u": "lectures/11/pervoobraznaya.html"},{"k": "a", "a": "Обратная задача — Первообразная и неопределённый интеграл (11.1)", "b": "", "u": "lectures/11/pervoobraznaya.html#zadacha"},{"k": "a", "a": "Определение первообразной — Первообразная и неопределённый интеграл (11.1)", "b": "", "u": "lectures/11/pervoobraznaya.html#opr"},{"k": "a", "a": "Почему «+ C» — Первообразная и неопределённый интеграл (11.1)", "b": "", "u": "lectures/11/pervoobraznaya.html#const"},{"k": "a", "a": "Семейство на графике — Первообразная и неопределённый интеграл (11.1)", "b": "", "u": "lectures/11/pervoobraznaya.html#geom"},{"k": "a", "a": "Неопределённый интеграл — Первообразная и неопределённый интеграл (11.1)", "b": "", "u": "lectures/11/pervoobraznaya.html#integral"},{"k": "a", "a": "Зачем нужно dx — Первообразная и неопределённый интеграл (11.1)", "b": "", "u": "lectures/11/pervoobraznaya.html#dx"},{"k": "a", "a": "Всегда ли есть первообразная — Первообразная и неопределённый интеграл (11.1)", "b": "", "u": "lectures/11/pervoobraznaya.html#sushch"},{"k": "a", "a": "Как проверить первообразную — Первообразная и неопределённый интеграл (11.1)", "b": "", "u": "lectures/11/pervoobraznaya.html#proverka"},{"k": "a", "a": "Частые ошибки — Первообразная и неопределённый интеграл (11.1)", "b": "", "u": "lectures/11/pervoobraznaya.html#oshibki"},{"k": "a", "a": "Кратко — Первообразная и неопределённый интеграл (11.1)", "b": "", "u": "lectures/11/pervoobraznaya.html#kratko"},{"k": "a", "a": "Проверь себя — Первообразная и неопределённый интеграл (11.1)", "b": "", "u": "lectures/11/pervoobraznaya.html#zadaniya"},{"k": "a", "a": "11.2 Свойства неопределённого интеграла (лекция 11)", "b": "Интегрирование и дифференцирование — взаимно обратные действия, и из этого вытекают все свойства интеграла. Лекция выделяет четыре: ∫ dF = F + C , d ∫ f dx = f dx , интеграл суммы и вынесение постоянного множителя. Последние два позволяют разбить сложный интеграл на простые слагаемые, а свойство 2° объясняет, почему любой ответ можно проверить дифференцированием. В статье: каждое свойство с услови", "u": "lectures/11/svojstva.html"},{"k": "a", "a": "Интеграл и дифференциал обратны — Свойства неопределённого интеграла (11.2)", "b": "", "u": "lectures/11/svojstva.html#obratn"},{"k": "a", "a": "Интеграл суммы — Свойства неопределённого интеграла (11.2)", "b": "", "u": "lectures/11/svojstva.html#summa"},{"k": "a", "a": "Постоянный множитель — Свойства неопределённого интеграла (11.2)", "b": "", "u": "lectures/11/svojstva.html#mnozh"},{"k": "a", "a": "Многочлены: формула (22.8) — Свойства неопределённого интеграла (11.2)", "b": "", "u": "lectures/11/svojstva.html#mnogochlen"},{"k": "a", "a": "Интеграл произведения — Свойства неопределённого интеграла (11.2)", "b": "", "u": "lectures/11/svojstva.html#proizv"},{"k": "a", "a": "Частые ошибки — Свойства неопределённого интеграла (11.2)", "b": "", "u": "lectures/11/svojstva.html#oshibki"},{"k": "a", "a": "Кратко — Свойства неопределённого интеграла (11.2)", "b": "", "u": "lectures/11/svojstva.html#kratko"},{"k": "a", "a": "Проверь себя — Свойства неопределённого интеграла (11.2)", "b": "", "u": "lectures/11/svojstva.html#zadaniya"},{"k": "a", "a": "11.3 Таблица основных интегралов (лекция 11)", "b": "Интегрирование — действие, обратное дифференцированию, поэтому каждая строка таблицы производных читается справа налево и даёт строку таблицы интегралов. Лекция составляет таблицу из 15 формул и называет их табличными интегралами ; с помощью свойств из статьи 11.2 к ним сводятся интегралы суммы и разности функций. В статье вся таблица с условиями (где формула верна), способы её запомнить, проверка", "u": "lectures/11/tablitsa.html"},{"k": "a", "a": "Таблица производных наоборот — Таблица основных интегралов (11.3)", "b": "", "u": "lectures/11/tablitsa.html#idea"},{"k": "a", "a": "Таблица 1–15 — Таблица основных интегралов (11.3)", "b": "", "u": "lectures/11/tablitsa.html#tablitsa"},{"k": "a", "a": "Как выучить — Таблица основных интегралов (11.3)", "b": "", "u": "lectures/11/tablitsa.html#pomni"},{"k": "a", "a": "Промежутки — Таблица основных интегралов (11.3)", "b": "", "u": "lectures/11/tablitsa.html#promezhutki"},{"k": "a", "a": "Проверка формул 12–15 — Таблица основных интегралов (11.3)", "b": "", "u": "lectures/11/tablitsa.html#vyvod"},{"k": "a", "a": "Как решать — Таблица основных интегралов (11.3)", "b": "", "u": "lectures/11/tablitsa.html#algoritm"},{"k": "a", "a": "Примеры — Таблица основных интегралов (11.3)", "b": "", "u": "lectures/11/tablitsa.html#primery"},{"k": "a", "a": "Не всё вычисляется — Таблица основных интегралов (11.3)", "b": "", "u": "lectures/11/tablitsa.html#elem"},{"k": "a", "a": "Частые ошибки — Таблица основных интегралов (11.3)", "b": "", "u": "lectures/11/tablitsa.html#oshibki"},{"k": "a", "a": "Кратко — Таблица основных интегралов (11.3)", "b": "", "u": "lectures/11/tablitsa.html#kratko"},{"k": "a", "a": "Проверь себя — Таблица основных интегралов (11.3)", "b": "", "u": "lectures/11/tablitsa.html#zadaniya"},{"k": "a", "a": "11.4 Интегрирование подстановкой: подведение под знак дифференциала (лекция 11)", "b": "Таблица умеет интегрировать cos x , но не cos 5x , и не x/(x² + 4) . Правило дифференцирования сложной функции, прочитанное наоборот, даёт для этого метод: если в подынтегральном выражении есть функция φ(x) и её производная φ′(x) dx , то под знаком интеграла можно перейти к новой переменной u = φ(x) , и интеграл станет табличным. В статье теорема 1 лекции с условиями и доказательством, формулы (22", "u": "lectures/11/podvedenie.html"},{"k": "a", "a": "Теорема 1 и формула (22.10) — Интегрирование подстановкой: подведение под знак дифференциала (11.4)", "b": "", "u": "lectures/11/podvedenie.html#teorema"},{"k": "a", "a": "Алгоритм подведения — Интегрирование подстановкой: подведение под знак дифференциала (11.4)", "b": "", "u": "lectures/11/podvedenie.html#algoritm"},{"k": "a", "a": "Что подводить под d — Интегрирование подстановкой: подведение под знак дифференциала (11.4)", "b": "", "u": "lectures/11/podvedenie.html#diff"},{"k": "a", "a": "Линейная подстановка — Интегрирование подстановкой: подведение под знак дифференциала (11.4)", "b": "", "u": "lectures/11/podvedenie.html#linein"},{"k": "a", "a": "Примеры 2 и 3 лекции — Интегрирование подстановкой: подведение под знак дифференциала (11.4)", "b": "", "u": "lectures/11/podvedenie.html#lekciya"},{"k": "a", "a": "Ещё типы — Интегрирование подстановкой: подведение под знак дифференциала (11.4)", "b": "", "u": "lectures/11/podvedenie.html#dop"},{"k": "a", "a": "Что можно компенсировать — Интегрирование подстановкой: подведение под знак дифференциала (11.4)", "b": "", "u": "lectures/11/podvedenie.html#tolko"},{"k": "a", "a": "Частые ошибки — Интегрирование подстановкой: подведение под знак дифференциала (11.4)", "b": "", "u": "lectures/11/podvedenie.html#oshibki"},{"k": "a", "a": "Кратко — Интегрирование подстановкой: подведение под знак дифференциала (11.4)", "b": "", "u": "lectures/11/podvedenie.html#kratko"},{"k": "a", "a": "Проверь себя — Интегрирование подстановкой: подведение под знак дифференциала (11.4)", "b": "", "u": "lectures/11/podvedenie.html#zadaniya"},{"k": "a", "a": "11.5 Замена переменной: корни и квадратный трёхчлен (лекция 11)", "b": "Подведение под знак дифференциала (статья 11.4) работает, когда в интеграле уже есть множитель φ′(x) dx . Если же мешает корень √(a² − x²) или √(ax² + bx + c) , которого нет в таблице, поступают наоборот: сами выбирают, чему равен x , то есть x = φ(t) , переходят к интегралу по t и в конце возвращаются к x обратной функцией t = φ⁻¹(x) . В статье формула (22.11) с условием строгой монотонности, алг", "u": "lectures/11/zamena.html"},{"k": "a", "a": "Формула (22.11) — Замена переменной: корни и квадратный трёхчлен (11.5)", "b": "", "u": "lectures/11/zamena.html#formula"},{"k": "a", "a": "Алгоритм — Замена переменной: корни и квадратный трёхчлен (11.5)", "b": "", "u": "lectures/11/zamena.html#algoritm"},{"k": "a", "a": "Пример 4: квадратный трёхчлен — Замена переменной: корни и квадратный трёхчлен (11.5)", "b": "", "u": "lectures/11/zamena.html#trehchlen"},{"k": "a", "a": "Пример 5: x = a sin t — Замена переменной: корни и квадратный трёхчлен (11.5)", "b": "", "u": "lectures/11/zamena.html#sin"},{"k": "a", "a": "Другие замены — Замена переменной: корни и квадратный трёхчлен (11.5)", "b": "", "u": "lectures/11/zamena.html#drugie"},{"k": "a", "a": "Какую замену выбрать — Замена переменной: корни и квадратный трёхчлен (11.5)", "b": "", "u": "lectures/11/zamena.html#vybor"},{"k": "a", "a": "Частые ошибки — Замена переменной: корни и квадратный трёхчлен (11.5)", "b": "", "u": "lectures/11/zamena.html#oshibki"},{"k": "a", "a": "Кратко — Замена переменной: корни и квадратный трёхчлен (11.5)", "b": "", "u": "lectures/11/zamena.html#kratko"},{"k": "a", "a": "Проверь себя — Замена переменной: корни и квадратный трёхчлен (11.5)", "b": "", "u": "lectures/11/zamena.html#zadaniya"},{"k": "a", "a": "11.6 Интегрирование по частям: формула и выбор u и dv (лекция 11)", "b": "Интегралы ∫ x eˣ dx , ∫ x sin x dx , ∫ ln x dx не табличные, а подведение под знак дифференциала и замена здесь не помогают: подынтегральная функция — произведение разнородных множителей. Нужен другой приём — формула интегрирования по частям. Это правило дифференцирования произведения, прочитанное наоборот. Всё искусство в том, что взять за u , а что за dv : неудачный выбор делает интеграл сложнее", "u": "lectures/11/po-chastyam.html"},{"k": "a", "a": "Теорема 2 и формула (22.12) — Интегрирование по частям: формула и выбор u и dv (11.6)", "b": "", "u": "lectures/11/po-chastyam.html#formula"},{"k": "a", "a": "Что взять за u и dv — Интегрирование по частям: формула и выбор u и dv (11.6)", "b": "", "u": "lectures/11/po-chastyam.html#vybor"},{"k": "a", "a": "Алгоритм — Интегрирование по частям: формула и выбор u и dv (11.6)", "b": "", "u": "lectures/11/po-chastyam.html#algoritm"},{"k": "a", "a": "Разобранные примеры — Интегрирование по частям: формула и выбор u и dv (11.6)", "b": "", "u": "lectures/11/po-chastyam.html#primery"},{"k": "a", "a": "Частые ошибки — Интегрирование по частям: формула и выбор u и dv (11.6)", "b": "", "u": "lectures/11/po-chastyam.html#oshibki"},{"k": "a", "a": "Кратко — Интегрирование по частям: формула и выбор u и dv (11.6)", "b": "", "u": "lectures/11/po-chastyam.html#kratko"},{"k": "a", "a": "Проверь себя — Интегрирование по частям: формула и выбор u и dv (11.6)", "b": "", "u": "lectures/11/po-chastyam.html#zadaniya"},{"k": "a", "a": "11.7 Повторное и «циклическое» интегрирование по частям (лекция 11)", "b": "Одного применения формулы по частям иногда не хватает: новый интеграл ∫ v du снова оказывается «по частям», и приём применяют ещё раз. А бывает хитрее: после двух шагов в правой части появляется тот же самый интеграл , и тогда его находят из уравнения. В статье примеры 2, 3 и 4 лекции ( ∫ √(a² − x²) dx , ∫ arcsin²x dx , ∫ Pₙ(x) e αx dx ) со всеми шагами и доказательством формулы, интегралы eˣ sin ", "u": "lectures/11/povtornoe.html"},{"k": "a", "a": "Повторное применение — Повторное и «циклическое» интегрирование по частям (11.7)", "b": "", "u": "lectures/11/povtornoe.html#povtor"},{"k": "a", "a": "Многочлен на экспоненту — Повторное и «циклическое» интегрирование по частям (11.7)", "b": "", "u": "lectures/11/povtornoe.html#pn"},{"k": "a", "a": "Интеграл возвращается — Повторное и «циклическое» интегрирование по частям (11.7)", "b": "", "u": "lectures/11/povtornoe.html#cikl"},{"k": "a", "a": "Как узнать цикл — Повторное и «циклическое» интегрирование по частям (11.7)", "b": "", "u": "lectures/11/povtornoe.html#priznaki"},{"k": "a", "a": "Частые ошибки — Повторное и «циклическое» интегрирование по частям (11.7)", "b": "", "u": "lectures/11/povtornoe.html#oshibki"},{"k": "a", "a": "Кратко — Повторное и «циклическое» интегрирование по частям (11.7)", "b": "", "u": "lectures/11/povtornoe.html#kratko"},{"k": "a", "a": "Проверь себя — Повторное и «циклическое» интегрирование по частям (11.7)", "b": "", "u": "lectures/11/povtornoe.html#zadaniya"},{"k": "a", "a": "11.8 Тригонометрические интегралы и проверка ответа (лекция 11)", "b": "Интегралы с sin , cos , tg — самая частая добавка к теории на практике. В лекции для них три опоры: ∫ tg x dx и ∫ dx/sin x (пример 3, стр. 9), приём cos²t = (1 + cos 2t)/2 из примера 5 (стр. 10) и правило проверки: «достаточно продифференцировать результат» (стр. 10, 13). В статье формулы-помощники, четыре типа тригонометрических интегралов, таблица выбора метода для всей темы и подробный разбор п", "u": "lectures/11/trigonometriya.html"},{"k": "a", "a": "Формулы-помощники — Тригонометрические интегралы и проверка ответа (11.8)", "b": "", "u": "lectures/11/trigonometriya.html#formuly"},{"k": "a", "a": "Чётные степени — Тригонометрические интегралы и проверка ответа (11.8)", "b": "", "u": "lectures/11/trigonometriya.html#chet"},{"k": "a", "a": "Нечётные степени — Тригонометрические интегралы и проверка ответа (11.8)", "b": "", "u": "lectures/11/trigonometriya.html#nechet"},{"k": "a", "a": "Произведения — Тригонометрические интегралы и проверка ответа (11.8)", "b": "", "u": "lectures/11/trigonometriya.html#proizv"},{"k": "a", "a": "tg, ctg и 1/sin — Тригонометрические интегралы и проверка ответа (11.8)", "b": "", "u": "lectures/11/trigonometriya.html#tg"},{"k": "a", "a": "Выбор метода — Тригонометрические интегралы и проверка ответа (11.8)", "b": "", "u": "lectures/11/trigonometriya.html#metod"},{"k": "a", "a": "Проверка ответа — Тригонометрические интегралы и проверка ответа (11.8)", "b": "", "u": "lectures/11/trigonometriya.html#proverka"},{"k": "a", "a": "Частые ошибки — Тригонометрические интегралы и проверка ответа (11.8)", "b": "", "u": "lectures/11/trigonometriya.html#oshibki"},{"k": "a", "a": "Кратко — Тригонометрические интегралы и проверка ответа (11.8)", "b": "", "u": "lectures/11/trigonometriya.html#kratko"},{"k": "a", "a": "Проверь себя — Тригонометрические интегралы и проверка ответа (11.8)", "b": "", "u": "lectures/11/trigonometriya.html#zadaniya"},{"k": "a", "a": "12.1 Рациональная дробь: правильная и неправильная, целая часть (лекция 12)", "b": "Интегрировать многочлен умеет каждый: это сумма степеней. Интегрировать «многочлен на многочлен» напрямую нельзя, дробь сначала нужно привести к удобному виду. Первый шаг всегда один и тот же: выяснить, правильная дробь или нет, и, если нет, выделить целую часть делением. Так же, как 7/2 = 3 + 1/2 : неправильная дробь равна целой части плюс правильная. В статье: определения, формула (23.24) лекции", "u": "lectures/12/ratsionalnaya-drob.html"},{"k": "a", "a": "Рациональная дробь — Рациональная дробь: правильная и неправильная, целая часть (12.1)", "b": "", "u": "lectures/12/ratsionalnaya-drob.html#opred"},{"k": "a", "a": "Правильная и неправильная — Рациональная дробь: правильная и неправильная, целая часть (12.1)", "b": "", "u": "lectures/12/ratsionalnaya-drob.html#pravilnaya"},{"k": "a", "a": "Формула (23.24): целая часть и остаток — Рациональная дробь: правильная и неправильная, целая часть (12.1)", "b": "", "u": "lectures/12/ratsionalnaya-drob.html#delenie"},{"k": "a", "a": "Деление уголком по шагам — Рациональная дробь: правильная и неправильная, целая часть (12.1)", "b": "", "u": "lectures/12/ratsionalnaya-drob.html#ugolok"},{"k": "a", "a": "Разобранные примеры — Рациональная дробь: правильная и неправильная, целая часть (12.1)", "b": "", "u": "lectures/12/ratsionalnaya-drob.html#primery"},{"k": "a", "a": "Целая часть на графике — Рациональная дробь: правильная и неправильная, целая часть (12.1)", "b": "", "u": "lectures/12/ratsionalnaya-drob.html#geom"},{"k": "a", "a": "Частые ошибки — Рациональная дробь: правильная и неправильная, целая часть (12.1)", "b": "", "u": "lectures/12/ratsionalnaya-drob.html#oshibki"},{"k": "a", "a": "Кратко — Рациональная дробь: правильная и неправильная, целая часть (12.1)", "b": "", "u": "lectures/12/ratsionalnaya-drob.html#kratko"},{"k": "a", "a": "Проверь себя — Рациональная дробь: правильная и неправильная, целая часть (12.1)", "b": "", "u": "lectures/12/ratsionalnaya-drob.html#proverka"},{"k": "a", "a": "12.2 Разложение знаменателя на множители (лекция 12)", "b": "Чтобы разложить правильную дробь на простейшие, нужно знать, из каких множителей состоит знаменатель: в теореме лекции он записан как (x − a₁) α₁ … (x² + p₁x + q₁) β₁ … (формула 23.29). Сама лекция эту разбивку не выводит: на стр. 7 она лишь оговаривает, что метод применим, когда знаменатель удалось разложить на множители. Получать это разложение придётся тебе, и ошибка здесь портит всё дальнейшее", "u": "lectures/12/razlozhenie-znamenatelya.html"},{"k": "a", "a": "Что утверждает теорема — Разложение знаменателя на множители (12.2)", "b": "", "u": "lectures/12/razlozhenie-znamenatelya.html#teorema"},{"k": "a", "a": "Теорема Безу и схема Горнера — Разложение знаменателя на множители (12.2)", "b": "", "u": "lectures/12/razlozhenie-znamenatelya.html#bezu"},{"k": "a", "a": "Алгоритм разложения — Разложение знаменателя на множители (12.2)", "b": "", "u": "lectures/12/razlozhenie-znamenatelya.html#algoritm"},{"k": "a", "a": "Разобранные примеры — Разложение знаменателя на множители (12.2)", "b": "", "u": "lectures/12/razlozhenie-znamenatelya.html#primery"},{"k": "a", "a": "Корни на графике — Разложение знаменателя на множители (12.2)", "b": "", "u": "lectures/12/razlozhenie-znamenatelya.html#geom"},{"k": "a", "a": "Частые ошибки — Разложение знаменателя на множители (12.2)", "b": "", "u": "lectures/12/razlozhenie-znamenatelya.html#oshibki"},{"k": "a", "a": "Кратко — Разложение знаменателя на множители (12.2)", "b": "", "u": "lectures/12/razlozhenie-znamenatelya.html#kratko"},{"k": "a", "a": "Проверь себя — Разложение знаменателя на множители (12.2)", "b": "", "u": "lectures/12/razlozhenie-znamenatelya.html#proverka"},{"k": "a", "a": "12.3 Теорема о разложении правильной дроби на простейшие (лекция 12)", "b": "Теорема этой статьи — основа всего метода: любая правильная дробь раскладывается в сумму простейших, а интегралы простейших дробей мы умеем брать (статьи 12.5–12.6). Сначала нужно понять, как оно выглядит: какие слагаемые в него входят, сколько их, что стоит в числителях. Сами числа ищут в статье 12.4. Здесь: простейшие дроби, леммы лекции с доказательствами, теорема 1, шаблон, подсчёт неизвестных", "u": "lectures/12/teorema-o-razlozhenii.html"},{"k": "a", "a": "Простейшие дроби — Теорема о разложении правильной дроби на простейшие (12.3)", "b": "", "u": "lectures/12/teorema-o-razlozhenii.html#prostejshie"},{"k": "a", "a": "Две леммы: как «отрывается» слагаемое — Теорема о разложении правильной дроби на простейшие (12.3)", "b": "", "u": "lectures/12/teorema-o-razlozhenii.html#lemmy"},{"k": "a", "a": "Теорема 1 — Теорема о разложении правильной дроби на простейшие (12.3)", "b": "", "u": "lectures/12/teorema-o-razlozhenii.html#teorema"},{"k": "a", "a": "Как составить шаблон — Теорема о разложении правильной дроби на простейшие (12.3)", "b": "", "u": "lectures/12/teorema-o-razlozhenii.html#shablon"},{"k": "a", "a": "Сколько неизвестных — Теорема о разложении правильной дроби на простейшие (12.3)", "b": "", "u": "lectures/12/teorema-o-razlozhenii.html#schet"},{"k": "a", "a": "Единственность (упражнение 3) — Теорема о разложении правильной дроби на простейшие (12.3)", "b": "", "u": "lectures/12/teorema-o-razlozhenii.html#edinstv"},{"k": "a", "a": "Примеры шаблонов — Теорема о разложении правильной дроби на простейшие (12.3)", "b": "", "u": "lectures/12/teorema-o-razlozhenii.html#primery"},{"k": "a", "a": "Частые ошибки — Теорема о разложении правильной дроби на простейшие (12.3)", "b": "", "u": "lectures/12/teorema-o-razlozhenii.html#oshibki"},{"k": "a", "a": "Кратко — Теорема о разложении правильной дроби на простейшие (12.3)", "b": "", "u": "lectures/12/teorema-o-razlozhenii.html#kratko"},{"k": "a", "a": "Проверь себя — Теорема о разложении правильной дроби на простейшие (12.3)", "b": "", "u": "lectures/12/teorema-o-razlozhenii.html#proverka"},{"k": "a", "a": "12.4 Неопределённые коэффициенты и подстановка корней (лекция 12)", "b": "Шаблон разложения готов (статья 12.3), осталось найти в нём числа. Лекция предлагает метод неопределённых коэффициентов : привести шаблон к общему знаменателю, отбросить его и получить равенство двух многочленов; дальше либо приравнять коэффициенты при одинаковых степенях x (система n уравнений с n неизвестными), либо подставлять корни знаменателя. В статье оба способа на примерах лекции (стр. 3–4", "u": "lectures/12/neopredelennye-koeffitsienty.html"},{"k": "a", "a": "Идея: тождество многочленов — Неопределённые коэффициенты и подстановка корней (12.4)", "b": "", "u": "lectures/12/neopredelennye-koeffitsienty.html#tozhdestvo"},{"k": "a", "a": "Способ 1: подставить корни — Неопределённые коэффициенты и подстановка корней (12.4)", "b": "", "u": "lectures/12/neopredelennye-koeffitsienty.html#podstanovka"},{"k": "a", "a": "Способ 2: приравнять коэффициенты — Неопределённые коэффициенты и подстановка корней (12.4)", "b": "", "u": "lectures/12/neopredelennye-koeffitsienty.html#sravnenie"},{"k": "a", "a": "Как сочетать способы — Неопределённые коэффициенты и подстановка корней (12.4)", "b": "", "u": "lectures/12/neopredelennye-koeffitsienty.html#sovmestno"},{"k": "a", "a": "Разобранные примеры — Неопределённые коэффициенты и подстановка корней (12.4)", "b": "", "u": "lectures/12/neopredelennye-koeffitsienty.html#primery"},{"k": "a", "a": "Приём «прибавить и вычесть» — Неопределённые коэффициенты и подстановка корней (12.4)", "b": "", "u": "lectures/12/neopredelennye-koeffitsienty.html#priem"},{"k": "a", "a": "Как проверить разложение — Неопределённые коэффициенты и подстановка корней (12.4)", "b": "", "u": "lectures/12/neopredelennye-koeffitsienty.html#kontrol"},{"k": "a", "a": "Частые ошибки — Неопределённые коэффициенты и подстановка корней (12.4)", "b": "", "u": "lectures/12/neopredelennye-koeffitsienty.html#oshibki"},{"k": "a", "a": "Кратко — Неопределённые коэффициенты и подстановка корней (12.4)", "b": "", "u": "lectures/12/neopredelennye-koeffitsienty.html#kratko"},{"k": "a", "a": "Проверь себя — Неопределённые коэффициенты и подстановка корней (12.4)", "b": "", "u": "lectures/12/neopredelennye-koeffitsienty.html#proverka"},{"k": "a", "a": "12.5 Интегралы простейших дробей I–III типов (лекция 12)", "b": "После разложения (статьи 12.3–12.4) от рациональной функции остаются слагаемые четырёх типов, и интегрируют их по отдельности. Типы I и II берутся одной строкой, настоящая работа — в типе III, дроби (Mx + N)/(x² + px + q) с неприводимым трёхчленом. Лекция (стр. 4–5) решает её заменой t = x + p/2 , и в ответе появляются логарифм и арктангенс: формула (24.3). Разберём её вывод по шагам, чтобы пересч", "u": "lectures/12/integraly-prostejshikh-i-iii.html"},{"k": "a", "a": "Что предполагается — Интегралы простейших дробей I–III типов (12.5)", "b": "", "u": "lectures/12/integraly-prostejshikh-i-iii.html#uslovie"},{"k": "a", "a": "Типы I и II — Интегралы простейших дробей I–III типов (12.5)", "b": "", "u": "lectures/12/integraly-prostejshikh-i-iii.html#tip12"},{"k": "a", "a": "Тип III: полный квадрат — Интегралы простейших дробей I–III типов (12.5)", "b": "", "u": "lectures/12/integraly-prostejshikh-i-iii.html#tip3"},{"k": "a", "a": "Старший коэффициент не 1 — Интегралы простейших дробей I–III типов (12.5)", "b": "", "u": "lectures/12/integraly-prostejshikh-i-iii.html#variant"},{"k": "a", "a": "Разобранные примеры — Интегралы простейших дробей I–III типов (12.5)", "b": "", "u": "lectures/12/integraly-prostejshikh-i-iii.html#primery"},{"k": "a", "a": "Частые ошибки — Интегралы простейших дробей I–III типов (12.5)", "b": "", "u": "lectures/12/integraly-prostejshikh-i-iii.html#oshibki"},{"k": "a", "a": "Кратко — Интегралы простейших дробей I–III типов (12.5)", "b": "", "u": "lectures/12/integraly-prostejshikh-i-iii.html#kratko"},{"k": "a", "a": "Проверь себя — Интегралы простейших дробей I–III типов (12.5)", "b": "", "u": "lectures/12/integraly-prostejshikh-i-iii.html#proverka"},{"k": "a", "a": "12.6 Простейшая дробь IV типа и рекуррентная формула (лекция 12)", "b": "Дробь IV типа (Mx + N)/(x² + px + q) n с n ≥ 2 появляется, когда в знаменателе квадратный трёхчлен без действительных корней входит в степени 2 и выше, как (x² + 1)² в примере лекции. Здесь уже не обойтись одним арктангенсом: нужна рекуррентная формула (24.6), которая сводит интеграл с показателем n + 1 к интегралу с показателем n . Разберём вывод по шагам, применение формулы для n = 2 и n = 3 , с", "u": "lectures/12/prostejshaya-iv-tipa.html"},{"k": "a", "a": "Что нужно вычислить — Простейшая дробь IV типа и рекуррентная формула (12.6)", "b": "", "u": "lectures/12/prostejshaya-iv-tipa.html#zadacha"},{"k": "a", "a": "Два интеграла: (24.4) — Простейшая дробь IV типа и рекуррентная формула (12.6)", "b": "", "u": "lectures/12/prostejshaya-iv-tipa.html#raspad"},{"k": "a", "a": "Первый интеграл: (24.5) — Простейшая дробь IV типа и рекуррентная формула (12.6)", "b": "", "u": "lectures/12/prostejshaya-iv-tipa.html#pervyj"},{"k": "a", "a": "Второй интеграл: формула (24.6) — Простейшая дробь IV типа и рекуррентная формула (12.6)", "b": "", "u": "lectures/12/prostejshaya-iv-tipa.html#vtoroj"},{"k": "a", "a": "Алгоритм — Простейшая дробь IV типа и рекуррентная формула (12.6)", "b": "", "u": "lectures/12/prostejshaya-iv-tipa.html#algoritm"},{"k": "a", "a": "Разобранные примеры — Простейшая дробь IV типа и рекуррентная формула (12.6)", "b": "", "u": "lectures/12/prostejshaya-iv-tipa.html#primery"},{"k": "a", "a": "Частые ошибки — Простейшая дробь IV типа и рекуррентная формула (12.6)", "b": "", "u": "lectures/12/prostejshaya-iv-tipa.html#oshibki"},{"k": "a", "a": "Кратко — Простейшая дробь IV типа и рекуррентная формула (12.6)", "b": "", "u": "lectures/12/prostejshaya-iv-tipa.html#kratko"},{"k": "a", "a": "Проверь себя — Простейшая дробь IV типа и рекуррентная формула (12.6)", "b": "", "u": "lectures/12/prostejshaya-iv-tipa.html#proverka"},{"k": "a", "a": "12.7 Интегрирование рациональной функции: алгоритм и примеры (лекция 12)", "b": "Теперь у нас есть все части: целая часть (статья 12.1), разложение знаменателя (12.2), шаблон (12.3), коэффициенты (12.4) и интегралы простейших дробей (12.5–12.6). Лекция (стр. 6–7) собирает их в теорему и в общий алгоритм и разбирает два примера; в статье они выписаны полностью, добавлен пример, где все этапы собраны вместе (деление, группировка, система из четырёх уравнений), показано, когда ра", "u": "lectures/12/obshchij-algoritm.html"},{"k": "a", "a": "Теорема 1 §24.2 — Интегрирование рациональной функции: алгоритм и примеры (12.7)", "b": "", "u": "lectures/12/obshchij-algoritm.html#teorema"},{"k": "a", "a": "Алгоритм «шаг за шагом» — Интегрирование рациональной функции: алгоритм и примеры (12.7)", "b": "", "u": "lectures/12/obshchij-algoritm.html#algoritm"},{"k": "a", "a": "Разобранные примеры — Интегрирование рациональной функции: алгоритм и примеры (12.7)", "b": "", "u": "lectures/12/obshchij-algoritm.html#primery"},{"k": "a", "a": "Когда раскладывать не нужно — Интегрирование рациональной функции: алгоритм и примеры (12.7)", "b": "", "u": "lectures/12/obshchij-algoritm.html#inache"},{"k": "a", "a": "Как проверить ответ — Интегрирование рациональной функции: алгоритм и примеры (12.7)", "b": "", "u": "lectures/12/obshchij-algoritm.html#kontrol"},{"k": "a", "a": "Частые ошибки — Интегрирование рациональной функции: алгоритм и примеры (12.7)", "b": "", "u": "lectures/12/obshchij-algoritm.html#oshibki"},{"k": "a", "a": "Кратко — Интегрирование рациональной функции: алгоритм и примеры (12.7)", "b": "", "u": "lectures/12/obshchij-algoritm.html#kratko"},{"k": "a", "a": "Проверь себя — Интегрирование рациональной функции: алгоритм и примеры (12.7)", "b": "", "u": "lectures/12/obshchij-algoritm.html#proverka"},{"k":"l","a":"Лекция 1. Матрицы и определители","b":"Матрица — таблица чисел · Определитель · Обратная матрица · Ранг матрицы","u":"lectures/01.html"},{"k":"c","a":"Матрица — таблица чисел (л. 1)","b":"Матрица — это таблица из чисел: строки и столбцы. Как коробка конфет, где каждая на своём месте. Квадратная: строк столько же, сколько столбцов. Единичная E: единицы на диагонали, остальное нули. Умножать можно, если столбцов первой равно строкам второй. Порядок важен: AB и BA обычно разные.","u":"lectures/01.html#c1-1"},{"k":"f","a":"A = (aᵢⱼ), размер m × n","b":"л. 1 · Матрица — таблица чисел · aᵢⱼ — конфетка в строке i и столбце j. Строк m, столбцов n.","u":"lectures/01.html#c1-1"},{"k":"c","a":"Определитель (л. 1)","b":"Определитель — одно число, которое считаем из квадратной таблицы. Один итог за всю таблицу. Таблица 3 × 3 считается по правилу треугольников (Саррюса). Треугольная матрица: произведение чисел на главной диагонали. Строка или столбец из нулей — определитель равен нулю. Для квадратных A, B: det(AB) = det A · det B.","u":"lectures/01.html#c1-2"},{"k":"f","a":"det A = a₁₁·a₂₂ − a₁₂·a₂₁","b":"л. 1 · Определитель · Пример: |2 3; 5 7| = 2·7 − 3·5 = −1.","u":"lectures/01.html#c1-2"},{"k":"c","a":"Обратная матрица (л. 1)","b":"Обратная матрица — как шаг назад после шага вперёд. Она возвращает всё на место. Если det A = 0, обратной матрицы нет. Второй способ: приписать E справа и преобразовать строки. AX = B → X = A⁻¹·B. XA = B → X = B·A⁻¹. det(A⁻¹) = 1 / det A.","u":"lectures/01.html#c1-3"},{"k":"f","a":"A⁻¹ = (1 / det A) · A^∨","b":"л. 1 · Обратная матрица · A^∨ — присоединённая: из алгебраических дополнений, транспонированная. A · A⁻¹ = E.","u":"lectures/01.html#c1-3"},{"k":"c","a":"Ранг матрицы (л. 1)","b":"Ранг — сколько «главных» строк в таблице. Остальные строки получаются из них. Окаймляющие миноры: добавляй строку и столбец к ненулевому минору. Строки независимы, если ни одна не выражается через другие. Ранг не меняется при транспонировании и элементарных преобразованиях. Матрица из одних нулей: ранг равен нулю.","u":"lectures/01.html#c1-4"},{"k":"f","a":"r(A) — ранг: максимальный порядок ненулевого минора","b":"л. 1 · Ранг матрицы · Проще: сколько строк остаётся после упрощения.","u":"lectures/01.html#c1-4"},{"k":"l","a":"Лекция 2. Системы уравнений","b":"Что такое система уравнений · Крамер и матричный способ · Метод Гаусса и теорема Кронекера–Капелли · Однородные системы и ФСР","u":"lectures/02.html"},{"k":"c","a":"Что такое система уравнений (л. 2)","b":"Система уравнений — это несколько загадок про одни и те же числа. Ответ должен подходить ко всем сразу. Решение — набор чисел, при котором все уравнения верны. Единственное решение — определённая система. Решений много — неопределённая система. Расширенная матрица Ā — A с приписанным столбцом B.","u":"lectures/02.html#c2-1"},{"k":"f","a":"A · X = B","b":"л. 2 · Что такое система уравнений · A — таблица коэффициентов, X — столбец неизвестных, B — столбец свободных членов.","u":"lectures/02.html#c2-1"},{"k":"c","a":"Крамер и матричный способ (л. 2)","b":"Если уравнений и неизвестных поровну и определитель не ноль, ответы находятся сразу. Два способа: матричный и Крамера. Матричный способ: X = A⁻¹ · B. Если Δ = 0, формулы Крамера не подходят — нужен Гаусс. Невырожденная система имеет ровно одно решение.","u":"lectures/02.html#c2-2"},{"k":"f","a":"xᵢ = Δᵢ / Δ","b":"л. 2 · Крамер и матричный способ · Δ — определитель системы. Δᵢ — он же с заменённым i-м столбцом. Нужно: n уравнений, n неизвестных и Δ ≠ 0.","u":"lectures/02.html#c2-2"},{"k":"c","a":"Метод Гаусса и теорема Кронекера–Капелли (л. 2)","b":"Метод Гаусса убирает неизвестные по одному. Сначала строим ступеньки, потом спускаемся и находим ответы. Ступенчатый вид: в каждом следующем уравнении первая неизвестная стоит правее. Строка вида 0 = b, где b не ноль — решений нет. Если совместна: r = n — определённая; r < n — неопределённая. Жордан–Гаусс: у базисных неизвестных получаем единичный блок — ответ виден сразу.","u":"lectures/02.html#c2-3"},{"k":"f","a":"r(A) = r(Ā)","b":"л. 2 · Метод Гаусса и теорема Кронекера–Капелли · Система совместна тогда и только тогда, когда ранг A равен рангу расширенной матрицы Ā (Кронекер–Капелли).","u":"lectures/02.html#c2-3"},{"k":"c","a":"Однородные системы и ФСР (л. 2)","b":"Однородная система — все справа нули. Ноль-решение всегда подходит, но бывают и другие ответы. Ненулевые решения есть тогда и только тогда, когда r < n. n уравнений, n неизвестных: Δ ≠ 0 — только нулевое решение, Δ = 0 — есть другие. ФСР — линейно независимые решения; остальные — их линейные комбинации. Совместная неоднородная: общее решение = частное + общее решение её однородной.","u":"lectures/02.html#c2-4"},{"k":"f","a":"X = c₁e₁ + c₂e₂ + … + cₖeₖ,  k = n − r","b":"л. 2 · Однородные системы и ФСР · e₁…eₖ — фундаментальная система решений (ФСР). c₁…cₖ — любые числа. n — число неизвестных.","u":"lectures/02.html#c2-4"},{"k":"l","a":"Лекция 3. Векторные пространства","b":"Линейное пространство · Линейная зависимость · Базис и координаты · Переход к другому базису · Аффинное пространство","u":"lectures/03.html"},{"k":"c","a":"Линейное пространство (л. 3)","b":"Линейное пространство — это набор «штук», которые можно складывать и умножать на число. Сумма двух элементов тоже элемент пространства. Элемент, умноженный на число, тоже в пространстве. Подпространство — часть пространства, где сумма и умножение на число не выходят за её пределы.","u":"lectures/03.html#c3-1"},{"k":"f","a":"x + y = y + x;   α(x + y) = αx + αy","b":"л. 3 · Линейное пространство · Первое: порядок сложения не важен. Второе: число «раскрывает скобки».","u":"lectures/03.html#c3-1"},{"k":"c","a":"Линейная зависимость (л. 3)","b":"Если из одних векторов можно собрать другой, набор лишний. Такой набор зависимый. Набор зависим тогда и только тогда, когда один вектор — сумма остальных с числами. Нулевой вектор в наборе делает его зависимым. Если часть набора зависима, весь набор тоже зависим.","u":"lectures/03.html#c3-2"},{"k":"f","a":"λ₁a₁ + λ₂a₂ + … + λₙaₙ = 0","b":"л. 3 · Линейная зависимость · Зависимый: сумма = 0 при каких-то λ, не все нули. Независимый: сумма = 0 лишь при всех λ = 0.","u":"lectures/03.html#c3-2"},{"k":"c","a":"Базис и координаты (л. 3)","b":"Базис — это главные «кубики» пространства. Любой вектор собирается из них ровно одним способом. Базис в n-мерном пространстве — n независимых векторов. Складываются векторы — складываются и их координаты. Координаты зависят от базиса: другой базис — другие числа.","u":"lectures/03.html#c3-3"},{"k":"f","a":"x = x₁f₁ + x₂f₂ + … + xₙfₙ","b":"л. 3 · Базис и координаты · Читается: «икс равно икс-один эф-один плюс…». Числа x₁…xₙ — координаты x.","u":"lectures/03.html#c3-3"},{"k":"c","a":"Переход к другому базису (л. 3)","b":"Один и тот же вектор можно описать разными базисами. Есть правило, как пересчитать числа. В столбцах C записаны новые базисные векторы в старом базисе. Матрица перехода Q между ортонормированными базисами: Q⁻¹ = Qᵀ (обратная равна транспонированной).","u":"lectures/03.html#c3-4"},{"k":"f","a":"ξ = C·η;   η = C⁻¹·ξ","b":"л. 3 · Переход к другому базису · Старые координаты получаем умножением на C. Обратно — на обратную матрицу C⁻¹.","u":"lectures/03.html#c3-4"},{"k":"c","a":"Аффинное пространство (л. 3)","b":"Аффинное пространство — это точки, между которыми можно проводить стрелки-векторы. Как карта: города — точки, а стрелка из одного города в другой — вектор. Следствия: вектор MM — нулевой, а NM = −MN. Размерность n у аффинного пространства Aₙ та же, что у его линейного пространства. Аффинная система координат: выбираем точку O (начало) и базис e₁…eₙ; координаты точки M — это координаты её радиус-вектора OM. Координаты вектора MN — это координаты конца N минус координаты начала M, потому что MN = ON − OM.","u":"lectures/03.html#c3-5"},{"k":"f","a":"MN + NP = MP","b":"л. 3 · Аффинное пространство · Пройти из M в N, потом из N в P — то же самое, что сразу из M в P.","u":"lectures/03.html#c3-5"},{"k":"l","a":"Лекция 4. Произведения векторов","b":"Скалярное произведение · Векторное произведение · Смешанное произведение · Ортонормированный базис","u":"lectures/04.html"},{"k":"c","a":"Скалярное произведение (л. 4)","b":"Скалярное произведение перемножает два вектора. Результат — обычное число, а не стрелка. Длина вектора: |x| = √(x, x). Угол между ненулевыми векторами: cos φ = (x, y) / (|x|·|y|). Если (x, y) = 0, векторы перпендикулярны (ортогональны). Неравенство Коши–Буняковского |(x, y)| ≤ |x|·|y| даёт |cos φ| ≤ 1.","u":"lectures/04.html#c4-1"},{"k":"f","a":"(x, y) = α₁β₁ + α₂β₂ + … + αₙβₙ","b":"л. 4 · Скалярное произведение · Перемножь числа с одинаковыми номерами и сложи. Верно в ℝⁿ и в ортонормированном базисе.","u":"lectures/04.html#c4-1"},{"k":"c","a":"Векторное произведение (л. 4)","b":"Векторное произведение двух стрелок в ℝ³ — это новая стрелка. Она смотрит перпендикулярно обеим. c перпендикулярен a и b; тройка a, b, c правая. Ненулевые векторы параллельны тогда и только тогда, когда a × b = 0. В координатах: определитель 3×3 с i, j, k в первой строке. Площадь треугольника ABC: S = ½·|AB × AC|.","u":"lectures/04.html#c4-2"},{"k":"f","a":"|a × b| = |a|·|b|·sin φ","b":"л. 4 · Векторное произведение · Длина новой стрелки равна площади параллелограмма на a и b. φ — угол между ними.","u":"lectures/04.html#c4-2"},{"k":"c","a":"Смешанное произведение (л. 4)","b":"Смешанное произведение — это три стрелки. Результат — число: объём коробки, построенной на них. В координатах: определитель 3×3 из строк координат a, b, c. Ноль тогда и только тогда, когда векторы компланарны (в одной плоскости). Пирамида: V = (1/6)·|(AB × AC)·AD|.","u":"lectures/04.html#c4-3"},{"k":"f","a":"V = |(a × b) · c|","b":"л. 4 · Смешанное произведение · Объём параллелепипеда. (a × b)·c без модуля: «плюс» — правая тройка, «минус» — левая.","u":"lectures/04.html#c4-3"},{"k":"c","a":"Ортонормированный базис (л. 4)","b":"Ортонормированный базис — это перпендикулярные стрелки длины 1. Любой базис можно так сделать. Ненулевые попарно перпендикулярные векторы всегда независимы. Ортонормированный: перпендикулярны, и все длины равны 1. Стандартный базис (1, 0, …, 0), (0, 1, …, 0), … в ℝⁿ с обычным (x, y) — ортонормированный.","u":"lectures/04.html#c4-4"},{"k":"f","a":"b₂ = a₂ − ((a₂, b₁) / (b₁, b₁))·b₁","b":"л. 4 · Ортонормированный базис · Так b₂ становится перпендикулярен b₁. Остальные векторы — по тому же правилу.","u":"lectures/04.html#c4-4"},{"k":"l","a":"Лекция 5. Линейные отображения","b":"Линейное отображение · Ядро и образ · Матрица отображения · Линейные операторы","u":"lectures/05.html"},{"k":"c","a":"Линейное отображение (л. 5)","b":"Линейное отображение — умная машинка. Сложение и умножение на число проходят через неё без изменений. Инъективно: разным входам соответствуют разные выходы. Сюръективно: каждый элемент W получается из какого-то входа. Биективно: и инъективно, и сюръективно. Тогда отображение обратимо. Любые образы базисных векторов задают ровно одно линейное отображение.","u":"lectures/05.html#c5-1"},{"k":"f","a":"A(λ₁v₁ + λ₂v₂) = λ₁A(v₁) + λ₂A(v₂)","b":"л. 5 · Линейное отображение · Одна формула заменяет два правила: сложение и умножение на число. Ноль переходит в ноль.","u":"lectures/05.html#c5-1"},{"k":"c","a":"Ядро и образ (л. 5)","b":"Ядро — всё, что превращается в ноль. Образ — всё, что получилось на выходе. Ядро и образ — подпространства: ядро — «комнатка» в V, образ — в W. Инъективно тогда и только тогда, когда ядро состоит из одного нуля. Сюръективно, когда ранг равен dim W. Биективно и обратимо, когда его матрица (см. дальше) квадратная и невырожденная.","u":"lectures/05.html#c5-2"},{"k":"f","a":"dim(Ker A) + dim(Im A) = dim V","b":"л. 5 · Ядро и образ · Размер ядра плюс размер образа равен размеру исходного пространства.","u":"lectures/05.html#c5-2"},{"k":"c","a":"Матрица отображения (л. 5)","b":"Матрица отображения записывает, во что превратился каждый базисный кубик. Тождественное отображение в одном базисе: матрица — единичная E. Поворот на угол φ: матрица (cos φ −sin φ; sin φ cos φ). Нулевое отображение: матрица из одних нулей. Дифференцирование: x^k переходит в k·x^(k−1).","u":"lectures/05.html#c5-3"},{"k":"f","a":"w = A·v","b":"л. 5 · Матрица отображения · Координаты образа w получаем умножением матрицы A на координаты прообраза v.","u":"lectures/05.html#c5-3"},{"k":"c","a":"Линейные операторы (л. 5)","b":"Оператор — линейное отображение пространства в само себя. Его матрица меняется при смене базиса. Поворот на угол φ: вектор крутится против часовой стрелки. Гомотетия v ↦ λv: растяжение при λ > 1, сжатие при 0 < λ < 1, при λ = −1 — центральная симметрия. Проекция на L₁ параллельно L₂ (V = L₁ ⊕ L₂): остаётся часть из L₁. Отражение от L₁ вдоль L₂ (V = L₁ ⊕ L₂): часть из L₂ меняет знак.","u":"lectures/05.html#c5-4"},{"k":"f","a":"A_f = S⁻¹ · A_e · S","b":"л. 5 · Линейные операторы · S — матрица перехода от базиса e к базису f. Такие матрицы называют подобными.","u":"lectures/05.html#c5-4"},{"k":"l","a":"Лекция 6. Пределы","b":"Логика, множества, кванторы · Метод математической индукции · Предел последовательности · Предел функции","u":"lectures/06.html"},{"k":"c","a":"Логика, множества, кванторы (л. 6)","b":"Математика говорит очень точно. Любое утверждение бывает либо верным, либо неверным. Как строгий судья! «Земля вращается вокруг Солнца» — верно. «6 делится на 4» — неверно. «Если A, то B» ложно только тогда, когда A верно, а B неверно. Множество — набор объектов с общим признаком. Например, деревья в парке. Из «если A, то B» не всегда следует обратное «если B, то A».","u":"lectures/06.html#c6-1"},{"k":"f","a":"¬(∀x A(x)) = ∃x ¬A(x)","b":"л. 6 · Логика, множества, кванторы · «Не у всех верно» значит: найдётся хотя бы один, у кого нет.","u":"lectures/06.html#c6-1"},{"k":"c","a":"Метод математической индукции (л. 6)","b":"Как доказать, что правило верно для всех чисел? Проверь первое и докажи переход к следующему. Метод нужен для утверждений, которые зависят от натурального n. Пример: неравенство Бернулли доказывают именно этим методом. Нужны все три шага: база, шаг и вывод.","u":"lectures/06.html#c6-2"},{"k":"f","a":"k ∈ A ⇒ k + 1 ∈ A","b":"л. 6 · Метод математической индукции · Если верно для k, то верно и для k + 1.","u":"lectures/06.html#c6-2"},{"k":"c","a":"Предел последовательности (л. 6)","b":"Представь, что ты идёшь к воротам. Номер n растёт, и числа xₙ всё ближе подходят к числу a. Предел единственный. Сходящаяся последовательность ограничена. Растёт и не выше какого-то числа — значит, сходится. Важный предел: lim (1 + 1/n)ⁿ = e ≈ 2,718. Из ограниченной последовательности можно выбрать сходящуюся часть.","u":"lectures/06.html#c6-3"},{"k":"f","a":"∀ε > 0 ∃N ∀n > N: |xₙ − a| < ε","b":"л. 6 · Предел последовательности · Для любого малого ε найдётся номер N. Дальше все xₙ ближе к a, чем на ε.","u":"lectures/06.html#c6-3"},{"k":"c","a":"Предел функции (л. 6)","b":"Функция — машинка: ты даёшь x, а она выдаёт f(x). Предел — число, к которому приходит ответ, когда x подходит к x₀. Предел суммы — сумма пределов. Так же с произведением; частное — если делитель не ноль. Если f зажата между φ и g, а φ и g стремятся к A, то f тоже стремится к A. Предел есть ровно тогда, когда левый и правый пределы равны. Предел A значит: f(x) = A + крошечный хвостик, который стремится к нулю.","u":"lectures/06.html#c6-4"},{"k":"f","a":"∀ε > 0 ∃δ > 0: 0 < |x − x₀| < δ ⇒ |f(x) − A| < ε","b":"л. 6 · Предел функции · Для любого малого ε найдётся δ. Если x близко к x₀, то f(x) близко к A.","u":"lectures/06.html#c6-4"},{"k":"l","a":"Лекция 7. Непрерывность функций одной переменной","b":"Непрерывность в точке · Точки разрыва · Свойства непрерывных функций · Элементарные функции","u":"lectures/07.html"},{"k":"c","a":"Непрерывность в точке (л. 7)","b":"Непрерывная функция — та, у которой нет скачков. График можно нарисовать, не отрывая карандаш. Функция в точке x₀ определена. Слева и справа подходим к одному числу — пределу. Это число равно f(x₀).","u":"lectures/07.html#c7-1"},{"k":"f","a":"lim x → x₀ f(x) = f(x₀)","b":"л. 7 · Непрерывность в точке · Предел в точке равен значению в точке. Так пишут «без дырок».","u":"lectures/07.html#c7-1"},{"k":"c","a":"Точки разрыва (л. 7)","b":"Разрыв — место, где график «рвётся». Таких мест бывает два вида. Первого рода: оба односторонних предела существуют. Второго рода: хотя бы один предел не существует. Если оба предела равны, разрыв устранимый — дырку можно заклеить.","u":"lectures/07.html#c7-2"},{"k":"f","a":"x₀ — разрыв 1-го рода ⇔ существуют оба односторонних предела","b":"л. 7 · Точки разрыва · Если оба предела есть — первого рода. Иначе — второго рода.","u":"lectures/07.html#c7-2"},{"k":"c","a":"Свойства непрерывных функций (л. 7)","b":"Если функция на отрезке без дыр, у неё есть важные свойства. Вейерштрасс: есть наибольшее и наименьшее значение. Больцано–Коши: встречаются все значения между A и B. Если на концах знаки разные, внутри есть ноль.","u":"lectures/07.html#c7-3"},{"k":"f","a":"f(a) · f(b) < 0  ⇒  f(ξ) = 0 для некоторого ξ ∈ (a, b)","b":"л. 7 · Свойства непрерывных функций · Знаки на концах разные — внутри точно есть ноль.","u":"lectures/07.html#c7-3"},{"k":"c","a":"Элементарные функции (л. 7)","b":"Элементарные функции — синус, логарифм, степень — без дыр там, где определены. Сумма, произведение и частное тоже непрерывны (на ноль не делим). Функция внутри функции тоже непрерывна. Обратная к строго возрастающей непрерывной тоже непрерывна.","u":"lectures/07.html#c7-4"},{"k":"f","a":"lim x → 0 sin x = 0","b":"л. 7 · Элементарные функции · Синус подходит к нулю, когда x подходит к нулю. По этому доказывают непрерывность синуса.","u":"lectures/07.html#c7-4"},{"k":"l","a":"Лекция 8. Дифференцируемость функций одной переменной","b":"Что такое производная · Правила дифференцирования · Касательная и скорость · Сложная, обратная, неявная функции","u":"lectures/08.html"},{"k":"c","a":"Что такое производная (л. 8)","b":"Производная — это спидометр функции. Она показывает, как быстро функция меняется. y′, f′(x) и dy/dx — записи одной и той же производной. Производная — скорость изменения функции в точке. Примеры: (C)′ = 0, (x)′ = 1, (xⁿ)′ = n·xⁿ⁻¹.","u":"lectures/08.html#c8-1"},{"k":"f","a":"y′ = lim Δx → 0  Δy / Δx","b":"л. 8 · Что такое производная · Предел отношения приращения функции к приращению аргумента.","u":"lectures/08.html#c8-1"},{"k":"c","a":"Правила дифференцирования (л. 8)","b":"Есть готовые правила. Не надо каждый раз считать предел заново. (u ± v)′ = u′ ± v′ — суммы считаем по частям. (u·v)′ = u′·v + u·v′. (C·u)′ = C·u′: константу выносим за знак. Таблицу основных производных учат наизусть.","u":"lectures/08.html#c8-2"},{"k":"f","a":"(u / v)′ = (u′·v − u·v′) / v²","b":"л. 8 · Правила дифференцирования · Производная дроби. Знаменатель v не должен быть нулём.","u":"lectures/08.html#c8-2"},{"k":"c","a":"Касательная и скорость (л. 8)","b":"Производная показывает наклон графика в точке. Чем круче горка, тем больше производная. Механика: скорость — это производная пути, v(t) = s′(t). Пример: y = x² − 4x + 7 при x₀ = 3 даёт касательную y = 2x − 2. Точка касания: x₀ и y₀ = f(x₀).","u":"lectures/08.html#c8-3"},{"k":"f","a":"y − y₀ = f′(x₀) · (x − x₀)","b":"л. 8 · Касательная и скорость · Уравнение касательной в точке (x₀; y₀), где y₀ = f(x₀).","u":"lectures/08.html#c8-3"},{"k":"c","a":"Сложная, обратная, неявная функции (л. 8)","b":"Сложную функцию разбирай по шагам: сначала внешняя часть, потом внутренняя. Обратная: (f⁻¹)′(y₀) = 1 / f′(x₀), если f′(x₀) ≠ 0. Неявная F(x, y) = 0: продифференцируй обе части. Пример: x² + y² = 1 даёт y′ = −x/y. Параметрическая x = φ(t), y = ψ(t): y′ = ψ′(t) / φ′(t). Вторая производная — производная от первой: f″ = (f′)′.","u":"lectures/08.html#c8-4"},{"k":"f","a":"y′(x) = y′(u) · u′(x)","b":"л. 8 · Сложная, обратная, неявная функции · Производная сложной функции: производная снаружи умножить на производную внутри.","u":"lectures/08.html#c8-4"},{"k":"l","a":"Лекция 9. Теоремы о производных","b":"Высшие производные · Теоремы Ферма, Ролля, Лагранжа, Коши · Формула Тейлора · Правило Лопиталя","u":"lectures/09.html"},{"k":"c","a":"Высшие производные (л. 9)","b":"Производная от производной — это вторая производная. Она показывает, как меняется сама скорость. (f ± g)⁽ⁿ⁾ = f⁽ⁿ⁾ ± g⁽ⁿ⁾ — сумму дифференцируем по частям. (cf)⁽ⁿ⁾ = c·f⁽ⁿ⁾ — число c выносится наружу. Второй дифференциал: d²f = f″·(dx)². Верно, если x — независимая переменная.","u":"lectures/09.html#c9-1"},{"k":"f","a":"(fg)⁽ⁿ⁾ = Σ(k=0..n) Cₙᵏ · f⁽ⁿ⁻ᵏ⁾ · g⁽ᵏ⁾,  где Cₙᵏ = n!/(k!(n−k)!)","b":"л. 9 · Высшие производные · Формула Лейбница: производная n-го порядка от произведения. Читается как сумма слагаемых с числами C.","u":"lectures/09.html#c9-1"},{"k":"c","a":"Теоремы Ферма, Ролля, Лагранжа, Коши (л. 9)","b":"Между двумя точками графика есть место, где касательная параллельна хорде. Это главная мысль теорем о среднем. Ферма: в самой высокой или низкой точке f′ = 0. Ролль: если f(a) = f(b), то есть точка с f′ = 0. Коши: (f(b)−f(a))/(g(b)−g(a)) = f′(ξ)/g′(ξ). Лагранж — частный случай при g(x) = x.","u":"lectures/09.html#c9-2"},{"k":"f","a":"f(b) − f(a) = f′(ξ) · (b − a),   ξ ∈ (a; b)","b":"л. 9 · Теоремы Ферма, Ролля, Лагранжа, Коши · Формула Лагранжа (конечных приращений). Читается: есть точка ξ между a и b, где наклон касательной равен наклону хорды.","u":"lectures/09.html#c9-2"},{"k":"c","a":"Формула Тейлора (л. 9)","b":"Гладкую функцию рядом с точкой можно записать как многочлен и маленький хвостик. Это формула Тейлора. Остаток rₙ = o((x − x₀)ⁿ): рядом с x₀ он очень мал. Форма Лагранжа: rₙ = f⁽ⁿ⁺¹⁾(ξ)/(n+1)! · (x − x₀)ⁿ⁺¹, ξ между x₀ и x. eˣ = 1 + x + x²/2! + …;  sin x = x − x³/3! + x⁵/5! − …","u":"lectures/09.html#c9-3"},{"k":"f","a":"f(x) = Σ(k=0..n) f⁽ᵏ⁾(x₀)/k! · (x − x₀)ᵏ + rₙ(x)","b":"л. 9 · Формула Тейлора · Функция = многочлен Тейлора + остаток rₙ. При x₀ = 0 это формула Маклорена.","u":"lectures/09.html#c9-3"},{"k":"c","a":"Правило Лопиталя (л. 9)","b":"Если предел даёт 0/0 или ∞/∞, можно взять производные сверху и снизу. Это правило Лопиталя. Виды 0·∞ и ∞ − ∞ сводят к дроби 0/0 или ∞/∞. Виды 0⁰, ∞⁰, 1^∞ — сначала логарифмируют. Не всегда помогает: (2x + sin x)/x при x → +∞ Лопиталем не берётся.","u":"lectures/09.html#c9-4"},{"k":"f","a":"lim (x→a) f(x)/g(x) = lim (x→a) f′(x)/g′(x)","b":"л. 9 · Правило Лопиталя · Правило Лопиталя: если предел f′/g′ существует, то предел f/g такой же. Рядом с точкой g′ ≠ 0.","u":"lectures/09.html#c9-4"},{"k":"l","a":"Лекция 10. Применение производных","b":"Возрастание и экстремумы · Выпуклость и перегибы · Асимптоты · Наибольшее и наименьшее значение","u":"lectures/10.html"},{"k":"c","a":"Возрастание и экстремумы (л. 10)","b":"Производная подсказывает, куда идёт график: вверх или вниз. Это как горка. Максимум: слева f′ > 0, справа f′ < 0. Вершина горки. Минимум: слева f′ < 0, справа f′ > 0. Дно ямки. Ферма: в гладкой точке экстремума f′ = 0. Обратное неверно: у x³ в нуле f′ = 0, но экстремума нет.","u":"lectures/10.html#c10-1"},{"k":"f","a":"f′(x) ≥ 0 на (a; b)  ⇔  f возрастает на (a; b)","b":"л. 10 · Возрастание и экстремумы · Читается: если производная не отрицательная, функция растёт. Для убывания нужен знак f′ ≤ 0.","u":"lectures/10.html#c10-1"},{"k":"c","a":"Выпуклость и перегибы (л. 10)","b":"Вторая производная показывает, как график гнётся: как улыбка или как шапка. Перегиб: точка, где f″ меняет знак. Изгиб переворачивается. Перегибы ищи там, где f″ = 0 или f″ не существует. Если f′ = f″ = … = f⁽ⁿ⁻¹⁾ = 0, а f⁽ⁿ⁾ ≠ 0: при чётном n экстремум, при нечётном — нет.","u":"lectures/10.html#c10-2"},{"k":"f","a":"f′(x₀) = 0 и f″(x₀) > 0  ⇒  x₀ — минимум;   f″(x₀) < 0  ⇒  x₀ — максимум","b":"л. 10 · Выпуклость и перегибы · Признак экстремума через вторую производную. Сначала находим точку, где f′ = 0.","u":"lectures/10.html#c10-2"},{"k":"c","a":"Асимптоты (л. 10)","b":"Асимптота — прямая, к которой график подходит всё ближе. Вертикальная асимптота x = x₀, если lim f(x) = ∞ при x → x₀. Пример: (x² + x)/(x − 2) = x + 3 + 6/(x − 2). Асимптоты: y = x + 3 и x = 2. Пример: x³/(x − 1)²: вертикальная x = 1, наклонная y = x + 2.","u":"lectures/10.html#c10-3"},{"k":"f","a":"k = lim(x→∞) f(x)/x,   b = lim(x→∞) (f(x) − k·x),   y = k·x + b","b":"л. 10 · Асимптоты · Наклонная асимптота y = kx + b. Если k = 0, она горизонтальная: b = lim f(x).","u":"lectures/10.html#c10-3"},{"k":"c","a":"Наибольшее и наименьшее значение (л. 10)","b":"Задача «самое большое» — например, самый большой прямоугольник. Ищем критические точки и концы отрезка. Пример: в треугольник с основанием a и высотой h вписан прямоугольник. Площадь S(y) = (a/h)·(h − y)·y. S′ = 0 при y = h/2. Тогда основание x = a/2, а S = ah/4. Локальный максимум не всегда наибольший на отрезке: проверь концы.","u":"lectures/10.html#c10-4"},{"k":"f","a":"max[a; b] f = max{ f(xкрит), f(a), f(b) }","b":"л. 10 · Наибольшее и наименьшее значение · Работает на замкнутом отрезке, где функция непрерывна. Берём все кандидаты и сравниваем.","u":"lectures/10.html#c10-4"},{"k":"l","a":"Лекция 11. Неопределённый интеграл","b":"Первообразная и интеграл · Таблица интегралов · Замена переменной · Интегрирование по частям","u":"lectures/11.html"},{"k":"c","a":"Первообразная и интеграл (л. 11)","b":"Интеграл — это обратный ход. Знаешь, как всё меняется, и ищешь, каким всё было. F — первообразная: её производная равна f. Интеграл суммы равен сумме интегралов. Число (не ноль) можно вынести за знак интеграла.","u":"lectures/11.html#c11-1"},{"k":"f","a":"∫f(x)dx = F(x) + C","b":"л. 11 · Первообразная и интеграл · Интеграл от эф от икс дэ икс равен эф от икс плюс цэ. Цэ — любое число.","u":"lectures/11.html#c11-1"},{"k":"c","a":"Таблица интегралов (л. 11)","b":"Есть готовые ответы на частые случаи. Их надо знать, как таблицу умножения. ∫dx/x = ln|x| + C, при x ≠ 0. ∫eˣ dx = eˣ + C — экспонента сама себе равна. ∫sin x dx = −cos x + C. ∫cos x dx = sin x + C.","u":"lectures/11.html#c11-2"},{"k":"f","a":"∫xᵅ dx = xᵅ⁺¹ / (α + 1) + C,  α ≠ −1","b":"л. 11 · Таблица интегралов · Икс в степени альфа: степень поднимаем на один и делим на новую степень. Альфа не равна минус единице.","u":"lectures/11.html#c11-2"},{"k":"c","a":"Замена переменной (л. 11)","b":"Сложный интеграл можно упростить заменой. Как в конструкторе: сложную деталь меняешь на простую. Замена помогает, когда новый интеграл проще старого. Пример: ∫cos(ax)dx = (1/a)·sin(ax) + C, a ≠ 0. Пример: ∫x dx / (x²+a²) = ½·ln(x²+a²) + C.","u":"lectures/11.html#c11-3"},{"k":"f","a":"∫f(x)dx = ∫f[φ(t)]·φ′(t)dt","b":"л. 11 · Замена переменной · Икс заменяем на фи от тэ, дэ икс — на фи штрих от тэ, умножить на дэ тэ. В конце возвращаемся к иксу.","u":"lectures/11.html#c11-3"},{"k":"c","a":"Интегрирование по частям (л. 11)","b":"Иногда интеграл делят на две части. Как торт: сначала один кусок, потом остальное. Не каждый выбор u и dv упрощает задачу. Иногда формулу применяют несколько раз. Пример: ∫x·eˣ dx = x·eˣ − eˣ + C. Для Pₙ(x)·e^(αx) применяют формулу n раз.","u":"lectures/11.html#c11-4"},{"k":"f","a":"∫u dv = u·v − ∫v du","b":"л. 11 · Интегрирование по частям · Интеграл от u дэ вэ равен u умножить на вэ минус интеграл от вэ дэ у.","u":"lectures/11.html#c11-4"},{"k":"l","a":"Лекция 12. Интегрирование рациональных функций","b":"Рациональные дроби · Разложение на простые дроби · Интегралы простых дробей · Интеграл рациональной дроби","u":"lectures/12.html"},{"k":"c","a":"Рациональные дроби (л. 12)","b":"Дробь из двух многочленов — как пирог. Если верх ниже по степени, дробь «правильная». Степень многочлена — сколько раз x умножен сам на себя. Неправильную дробь сначала делим, как столбиком. Правильную дробь потом раскладываем на простые.","u":"lectures/12.html#c12-1"},{"k":"f","a":"P(x) / Q(x) = R(x) + P₁(x) / Q₁(x)","b":"л. 12 · Рациональные дроби · Пэ от икс на ку от икс равно эр от икс плюс пэ один на ку один. Дробь пэ один на ку один — правильная.","u":"lectures/12.html#c12-1"},{"k":"c","a":"Разложение на простые дроби (л. 12)","b":"Правильную дробь можно разбить на простые кусочки. Как сдачу: крупную купюру меняют на монетки. Любая правильная дробь раскладывается на элементарные. Числа ищем методом неопределённых коэффициентов. Подставь корни знаменателя: числа находятся быстрее. Пример: x/((x²−1)(x−2)) = −1/(2(x−1)) − 1/(6(x+1)) + 2/(3(x−2)).","u":"lectures/12.html#c12-2"},{"k":"f","a":"A / (x − a)ᵅ  +  (Mx + N) / (x² + px + q)ᵝ","b":"л. 12 · Разложение на простые дроби · Это элементарные дроби. Буквы A, M, N — числа, которые надо найти.","u":"lectures/12.html#c12-2"},{"k":"c","a":"Интегралы простых дробей (л. 12)","b":"Простые дроби интегрируются легко. Есть готовые рецепты для каждого вида. При n ≠ 1: ∫A/(x−a)ⁿ dx = −A / ((n−1)(x−a)ⁿ⁻¹) + C. В квадрате x² + px + q делаем замену t = x + p/2. Затем ∫dt/(t²+a²) = (1/a)·arctg(t/a) + C.","u":"lectures/12.html#c12-3"},{"k":"f","a":"∫A/(x − a) dx = A·ln|x − a| + C","b":"л. 12 · Интегралы простых дробей · Интеграл от А на икс минус а дэ икс равен А умножить на логарифм модуля икс минус а, плюс цэ.","u":"lectures/12.html#c12-3"},{"k":"c","a":"Интеграл рациональной дроби (л. 12)","b":"Любую рациональную дробь можно проинтегрировать по одному порядку. Как собирать пазл: сначала края, потом кусочки. Теорема: интеграл от рациональной дроби — через дроби, ln и arctg. Знаменатель не должен обращаться в ноль на промежутке. Иногда короче решить другим способом, например по частям.","u":"lectures/12.html#c12-4"},{"k":"f","a":"∫ x dx / ((x²−1)(x−2)) = −½·ln|x−1| − ⅙·ln|x+1| + ⅔·ln|x−2| + C","b":"л. 12 · Интеграл рациональной дроби · Интеграл от икс на икс квадрат минус один, умножить на икс минус два, равен сумме трёх логарифмов с коэффициентами. Плюс цэ.","u":"lectures/12.html#c12-4"},{"k":"l","a":"Лекция 13. Интегрирование иррациональных функций","b":"","u":"lectures/13.html"},{"k":"l","a":"Лекция 14. Определённый интеграл","b":"","u":"lectures/14.html"},{"k":"l","a":"Лекция 15. Прямая на плоскости","b":"","u":"lectures/15.html"},{"k":"l","a":"Лекция 16. Кривые второго порядка","b":"","u":"lectures/16.html"},{"k":"l","a":"Лекция 17. Трёхмерная геометрия","b":"","u":"lectures/17.html"},{"k":"l","a":"Лекция 18. Поверхности 2-го порядка","b":"","u":"lectures/18.html"},{"k":"t","a":"матрица","b":"таблица из чисел по строкам и столбцам (л. 1)","u":"lectures/01.html#c1-1"},{"k":"t","a":"главная диагональ","b":"клетки от левого верхнего угла к правому нижнему (л. 1)","u":"lectures/01.html#c1-1"},{"k":"t","a":"транспонирование","b":"строки становятся столбцами (л. 1)","u":"lectures/01.html#c1-1"},{"k":"t","a":"определитель","b":"число, которое считаем из квадратной таблицы (л. 1)","u":"lectures/01.html#c1-2"},{"k":"t","a":"минор Mᵢⱼ","b":"определитель без строки i и столбца j, где стоит aᵢⱼ (л. 1)","u":"lectures/01.html#c1-2"},{"k":"t","a":"алгебраическое дополнение","b":"минор со знаком (−1)^(i+j): «плюс» при чётной i + j (л. 1)","u":"lectures/01.html#c1-2"},{"k":"t","a":"обратная матрица A⁻¹","b":"матрица, для которой A · A⁻¹ = A⁻¹ · A = E (л. 1)","u":"lectures/01.html#c1-3"},{"k":"t","a":"единичная матрица E","b":"единицы на диагонали, остальное нули (л. 1)","u":"lectures/01.html#c1-3"},{"k":"t","a":"невырожденная","b":"квадратная матрица с det A ≠ 0 (л. 1)","u":"lectures/01.html#c1-3"},{"k":"t","a":"ранг","b":"максимальный порядок ненулевого минора (л. 1, 2)","u":"lectures/01.html#c1-4"},{"k":"t","a":"базисный минор","b":"ненулевой минор порядка, равного рангу (л. 1)","u":"lectures/01.html#c1-4"},{"k":"t","a":"линейная зависимость","b":"одна строка выражается через остальные (л. 1)","u":"lectures/01.html#c1-4"},{"k":"t","a":"коэффициенты","b":"числа перед неизвестными (л. 2)","u":"lectures/02.html#c2-1"},{"k":"t","a":"свободные члены","b":"числа справа от знака равно (л. 2)","u":"lectures/02.html#c2-1"},{"k":"t","a":"совместная система","b":"у неё есть хотя бы одно решение (л. 2)","u":"lectures/02.html#c2-1"},{"k":"t","a":"определитель системы Δ","b":"определитель таблицы коэффициентов (л. 2)","u":"lectures/02.html#c2-2"},{"k":"t","a":"невырожденная система","b":"n уравнений, n неизвестных, Δ ≠ 0 (л. 2)","u":"lectures/02.html#c2-2"},{"k":"t","a":"формулы Крамера","b":"ответы через определители (л. 2)","u":"lectures/02.html#c2-2"},{"k":"t","a":"ступенчатый вид","b":"уравнения идут лесенкой: в каждом следующем первая неизвестная правее (л. 2)","u":"lectures/02.html#c2-3"},{"k":"t","a":"базисные неизвестные","b":"неизвестные, которые выражаем через остальные (л. 2)","u":"lectures/02.html#c2-3"},{"k":"t","a":"однородная система","b":"все свободные члены равны нулю (л. 2)","u":"lectures/02.html#c2-4"},{"k":"t","a":"фундаментальная система решений","b":"n − r линейно независимых решений; любое решение — их комбинация (л. 2)","u":"lectures/02.html#c2-4"},{"k":"t","a":"тривиальное решение","b":"все неизвестные равны нулю (л. 2)","u":"lectures/02.html#c2-4"},{"k":"t","a":"вектор","b":"любой элемент линейного пространства, не обязательно стрелка (л. 3)","u":"lectures/03.html#c3-1"},{"k":"t","a":"аксиомы","b":"8 правил, которые должны выполняться (л. 3)","u":"lectures/03.html#c3-1"},{"k":"t","a":"арифметическое пространство Rⁿ","b":"наборы из n чисел, например (1; 2; −2) (л. 3)","u":"lectures/03.html#c3-1"},{"k":"t","a":"линейная комбинация","b":"сумма векторов, каждый умножен на своё число (л. 3)","u":"lectures/03.html#c3-2"},{"k":"t","a":"линейно независимые","b":"ни один вектор не собирается из остальных (л. 3)","u":"lectures/03.html#c3-2"},{"k":"t","a":"базис","b":"набор независимых векторов, из которых всё собирается (л. 3)","u":"lectures/03.html#c3-3"},{"k":"t","a":"координаты","b":"числа, сколько базисных векторов взять (л. 3)","u":"lectures/03.html#c3-3"},{"k":"t","a":"размерность","b":"число векторов в базисе (л. 3)","u":"lectures/03.html#c3-3"},{"k":"t","a":"изоморфизм","b":"взаимно однозначное соответствие, сохраняющее сложение и умножение на число (л. 3)","u":"lectures/03.html#c3-3"},{"k":"t","a":"матрица перехода C","b":"таблица, которая пересчитывает координаты из одного базиса в другой (л. 3)","u":"lectures/03.html#c3-4"},{"k":"t","a":"ортонормированный базис","b":"базис из перпендикулярных векторов длины 1 (л. 3, 4)","u":"lectures/03.html#c3-4"},{"k":"t","a":"аффинное пространство","b":"точки плюс векторы между ними с правилом треугольника (л. 3)","u":"lectures/03.html#c3-5"},{"k":"t","a":"радиус-вектор","b":"вектор OM из начала координат O в точку M (л. 3)","u":"lectures/03.html#c3-5"},{"k":"t","a":"аффинная система координат","b":"начало O и базис векторов (л. 3)","u":"lectures/03.html#c3-5"},{"k":"t","a":"скалярное произведение","b":"число, которое получается из двух векторов (л. 4)","u":"lectures/04.html#c4-1"},{"k":"t","a":"евклидово пространство","b":"пространство, где есть скалярное произведение и длины (л. 4)","u":"lectures/04.html#c4-1"},{"k":"t","a":"ортогональные векторы","b":"перпендикулярные векторы: их скалярное произведение равно нулю (л. 4)","u":"lectures/04.html#c4-1"},{"k":"t","a":"векторное произведение","b":"вектор c = a × b в ℝ³: ⊥ a и b, длина |a||b|sin φ, тройка правая (л. 4)","u":"lectures/04.html#c4-2"},{"k":"t","a":"правая тройка","b":"с конца c кратчайший поворот от a к b виден против часовой стрелки (л. 4)","u":"lectures/04.html#c4-2"},{"k":"t","a":"смешанное произведение","b":"число (a × b)·c: сначала векторное, потом скалярное (л. 4)","u":"lectures/04.html#c4-3"},{"k":"t","a":"компланарные векторы","b":"векторы, которые лежат в одной плоскости (л. 4)","u":"lectures/04.html#c4-3"},{"k":"t","a":"параллелепипед","b":"коробка, у которой все грани — параллелограммы (л. 4)","u":"lectures/04.html#c4-3"},{"k":"t","a":"ортогональный базис","b":"базис из попарно перпендикулярных векторов (л. 4)","u":"lectures/04.html#c4-4"},{"k":"t","a":"ортогонализация","b":"процесс, который делает базис перпендикулярным (л. 4)","u":"lectures/04.html#c4-4"},{"k":"t","a":"отображение","b":"правило: каждому элементу V ставится в соответствие один элемент W (л. 5)","u":"lectures/05.html#c5-1"},{"k":"t","a":"образ и прообраз","b":"образ — результат; прообраз — то, из чего он получился (л. 5)","u":"lectures/05.html#c5-1"},{"k":"t","a":"ядро Ker A","b":"все векторы, которые превращаются в ноль (л. 5)","u":"lectures/05.html#c5-2"},{"k":"t","a":"дефект и ранг","b":"дефект — размер ядра; ранг — размер образа, он равен рангу матрицы отображения (л. 5)","u":"lectures/05.html#c5-2"},{"k":"t","a":"матрица линейного отображения","b":"таблица из координат образов базисных векторов (л. 5)","u":"lectures/05.html#c5-3"},{"k":"t","a":"координатный столбец","b":"столбик координат вектора в выбранном базисе (л. 5)","u":"lectures/05.html#c5-3"},{"k":"t","a":"линейный оператор","b":"линейное отображение пространства в самого себя (л. 5)","u":"lectures/05.html#c5-4"},{"k":"t","a":"подобные матрицы","b":"матрицы A и B = S⁻¹AS (S невырожденная): один оператор в разных базисах (л. 5)","u":"lectures/05.html#c5-4"},{"k":"t","a":"V = L₁ ⊕ L₂","b":"любой вектор единственным способом равен v₁ + v₂, где v₁ из L₁, v₂ из L₂ (л. 5)","u":"lectures/05.html#c5-4"},{"k":"t","a":"высказывание","b":"утверждение, которое верно или неверно (л. 6)","u":"lectures/06.html#c6-1"},{"k":"t","a":"импликация ⇒","b":"«если A, то B» (л. 6)","u":"lectures/06.html#c6-1"},{"k":"t","a":"квантор","b":"знак «для всех» ∀ или «существует» ∃ (л. 6)","u":"lectures/06.html#c6-1"},{"k":"t","a":"пересечение ∩","b":"то, что есть и в первом, и во втором множестве (л. 6)","u":"lectures/06.html#c6-1"},{"k":"t","a":"база индукции","b":"проверка первого случая (л. 6)","u":"lectures/06.html#c6-2"},{"k":"t","a":"шаг индукции","b":"переход от k к k + 1 (л. 6)","u":"lectures/06.html#c6-2"},{"k":"t","a":"предел последовательности","b":"число, к которому подходят члены при большом n (л. 6)","u":"lectures/06.html#c6-3"},{"k":"t","a":"ограниченная","b":"все члены не уходят дальше какого-то числа M (л. 6)","u":"lectures/06.html#c6-3"},{"k":"t","a":"монотонная","b":"всё время растёт или всё время убывает (л. 6)","u":"lectures/06.html#c6-3"},{"k":"t","a":"подпоследовательность","b":"часть последовательности с растущими номерами (л. 6)","u":"lectures/06.html#c6-3"},{"k":"t","a":"δ (дельта)","b":"маленький радиус вокруг x₀, который мы выбираем (л. 6)","u":"lectures/06.html#c6-4"},{"k":"t","a":"односторонний предел","b":"предел, когда подходим только слева или только справа (л. 6)","u":"lectures/06.html#c6-4"},{"k":"t","a":"бесконечно малая","b":"величина, которая стремится к нулю (л. 6)","u":"lectures/06.html#c6-4"},{"k":"t","a":"частное пределов","b":"делить пределы можно, если делитель не равен нулю (л. 6)","u":"lectures/06.html#c6-4"},{"k":"t","a":"непрерывность","b":"график без скачков и дырок (л. 7)","u":"lectures/07.html#c7-1"},{"k":"t","a":"предел","b":"число, к которому подходят значения функции (л. 7)","u":"lectures/07.html#c7-1"},{"k":"t","a":"точка разрыва","b":"место, где функция не непрерывна (л. 7)","u":"lectures/07.html#c7-2"},{"k":"t","a":"устранимый разрыв","b":"пределы слева и справа совпадают (л. 7)","u":"lectures/07.html#c7-2"},{"k":"t","a":"отрезок [a, b]","b":"все числа от a до b, включая концы (л. 7)","u":"lectures/07.html#c7-3"},{"k":"t","a":"метод половинного деления","b":"делишь отрезок пополам и оставляешь половину со сменой знака (л. 7)","u":"lectures/07.html#c7-3"},{"k":"t","a":"элементарная функция","b":"построена из основных функций сложением, умножением и вложением (л. 7)","u":"lectures/07.html#c7-4"},{"k":"t","a":"сложная функция","b":"одна функция подставлена внутрь другой (л. 7, 8)","u":"lectures/07.html#c7-4"},{"k":"t","a":"приращение","b":"на сколько изменилось: новое значение минус старое (л. 8)","u":"lectures/08.html#c8-1"},{"k":"t","a":"дифференцирование","b":"поиск производной (л. 8)","u":"lectures/08.html#c8-1"},{"k":"t","a":"таблица производных","b":"готовые ответы для основных функций (л. 8)","u":"lectures/08.html#c8-2"},{"k":"t","a":"правило дифференцирования","b":"готовый способ найти производную суммы, произведения или дроби (л. 8)","u":"lectures/08.html#c8-2"},{"k":"t","a":"касательная","b":"прямая, которая касается графика в одной точке (л. 8, 9)","u":"lectures/08.html#c8-3"},{"k":"t","a":"нормаль","b":"прямая через точку касания, перпендикулярная касательной (л. 8)","u":"lectures/08.html#c8-3"},{"k":"t","a":"параметрическое задание","b":"x и y заданы через третью переменную t (л. 8)","u":"lectures/08.html#c8-4"},{"k":"t","a":"производная n-го порядка","b":"производная от производной, взятая n раз (л. 9)","u":"lectures/09.html#c9-1"},{"k":"t","a":"формула Лейбница","b":"правило для производной n-го порядка от произведения (л. 9)","u":"lectures/09.html#c9-1"},{"k":"t","a":"дифференциал","b":"маленькое изменение функции, записанное через dx (л. 9)","u":"lectures/09.html#c9-1"},{"k":"t","a":"хорда","b":"прямая между двумя точками графика (л. 9)","u":"lectures/09.html#c9-2"},{"k":"t","a":"теорема Ролля","b":"если f(a) = f(b), то есть точка с f′ = 0 (л. 9)","u":"lectures/09.html#c9-2"},{"k":"t","a":"многочлен Тейлора","b":"первые слагаемые формулы Тейлора (л. 9)","u":"lectures/09.html#c9-3"},{"k":"t","a":"формула Маклорена","b":"формула Тейлора при x₀ = 0 (л. 9)","u":"lectures/09.html#c9-3"},{"k":"t","a":"факториал k!","b":"1·2·3·…·k, например 3! = 6 (л. 9)","u":"lectures/09.html#c9-3"},{"k":"t","a":"неопределённость","b":"предел, где сразу не видно ответ: 0/0 или ∞/∞ (л. 9)","u":"lectures/09.html#c9-4"},{"k":"t","a":"правило Лопиталя","b":"предел отношения = предел отношения производных (л. 9)","u":"lectures/09.html#c9-4"},{"k":"t","a":"экстремум","b":"точка максимума или минимума функции (л. 10)","u":"lectures/10.html#c10-1"},{"k":"t","a":"критическая точка","b":"точка, где f′ = 0 или производной нет (л. 10)","u":"lectures/10.html#c10-1"},{"k":"t","a":"стационарная точка","b":"точка, где f′ = 0 (л. 10)","u":"lectures/10.html#c10-1"},{"k":"t","a":"выпуклость вниз","b":"график лежит не ниже своей касательной (л. 10)","u":"lectures/10.html#c10-2"},{"k":"t","a":"точка перегиба","b":"точка, где изгиб графика меняется на противоположный (л. 10)","u":"lectures/10.html#c10-2"},{"k":"t","a":"асимптота","b":"прямая, к которой график подходит очень близко (л. 10)","u":"lectures/10.html#c10-3"},{"k":"t","a":"наклонная асимптота","b":"прямая y = kx + b (л. 10)","u":"lectures/10.html#c10-3"},{"k":"t","a":"наибольшее значение","b":"самое большое значение функции на отрезке (л. 10)","u":"lectures/10.html#c10-4"},{"k":"t","a":"локальный экстремум","b":"максимум или минимум в маленькой окрестности точки (л. 10)","u":"lectures/10.html#c10-4"},{"k":"t","a":"первообразная","b":"функция, у которой производная равна f (л. 11)","u":"lectures/11.html#c11-1"},{"k":"t","a":"неопределённый интеграл","b":"все первообразные сразу: F + C (л. 11)","u":"lectures/11.html#c11-1"},{"k":"t","a":"постоянная C","b":"любое число, его добавляем в конце (л. 11)","u":"lectures/11.html#c11-1"},{"k":"t","a":"табличный интеграл","b":"готовая формула, её надо знать наизусть (л. 11)","u":"lectures/11.html#c11-2"},{"k":"t","a":"замена переменной","b":"новая буква вместо сложного кусочка (л. 11)","u":"lectures/11.html#c11-3"},{"k":"t","a":"интегрирование по частям","b":"способ: разбить интеграл на части u и dv (л. 11)","u":"lectures/11.html#c11-4"},{"k":"t","a":"многочлен","b":"сумма степеней x с числами, например x² − 1 (л. 12)","u":"lectures/12.html#c12-1"},{"k":"t","a":"правильная дробь","b":"степень верха меньше степени низа (л. 12)","u":"lectures/12.html#c12-1"},{"k":"t","a":"элементарная дробь","b":"простая дробь вида A/(x−a)ⁿ или (Mx+N)/(x²+px+q)ⁿ (л. 12)","u":"lectures/12.html#c12-2"},{"k":"t","a":"неопределённые коэффициенты","b":"неизвестные числа, которые находим при разложении (л. 12)","u":"lectures/12.html#c12-2"},{"k":"t","a":"ln","b":"натуральный логарифм, есть кнопка на калькуляторе (л. 12)","u":"lectures/12.html#c12-3"},{"k":"t","a":"arctg","b":"угол, у которого тангенс равен данному числу (л. 12)","u":"lectures/12.html#c12-3"},{"k":"t","a":"рациональная функция","b":"дробь из двух многочленов (л. 12)","u":"lectures/12.html#c12-4"},{"k":"t","a":"целая часть","b":"полные части, которые получаются при делении верха на низ (л. 12)","u":"lectures/12.html#c12-4"}];